#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// Constants
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 2
#define DELAY_SECONDS 5

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
}

// Function to set GPIO output
int set_gpio_output(struct gpiod_line *line, int value) {
    int ret;

    if (value != 0 && value != 1) {
        fprintf(stderr, "Error: Invalid GPIO value: %d. Must be 0 or 1.\n", value);
        return -1;
    }

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to set GPIO value: %s\n", strerror(-ret));
        return -1;
    }

    return 0;
}

// Function to read GPIO input
int read_gpio_input(struct gpiod_line *line) {
    int value;

    value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error: Failed to read GPIO value: %s\n", strerror(-value));
        return -1;
    }

    return value;
}

// Function to report GPIO state
void report_gpio_state(int value) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    printf("%s GPIO state: %d\n", buf, value);
}

int main() {
    int ret;
    int gpio_value;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Failed to open GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error: Failed to get GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to request GPIO line for output: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Set GPIO output to 1
        if (set_gpio_output(line, 1) < 0) {
            fprintf(stderr, "Error: Failed to set GPIO output to 1.\n");
            break;
        }

        // Read GPIO input
        gpio_value = read_gpio_input(line);
        if (gpio_value < 0) {
            fprintf(stderr, "Error: Failed to read GPIO input.\n");
            break;
        }

        // Report GPIO state
        report_gpio_state(gpio_value);

        // Set GPIO output to 0
        if (set_gpio_output(line, 0) < 0) {
            fprintf(stderr, "Error: Failed to set GPIO output to 0.\n");
            break;
        }

        // Read GPIO input
        gpio_value = read_gpio_input(line);
        if (gpio_value < 0) {
            fprintf(stderr, "Error: Failed to read GPIO input.\n");
            break;
        }

        // Report GPIO state
        report_gpio_state(gpio_value);

        // Wait for 5 seconds
        sleep(DELAY_SECONDS);
    }

    // Release GPIO line
    if (line) {
        gpiod_line_release(line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <inttypes.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register settings
#define CONFIG_OS_SINGLE 0x8000  // Start a single conversion
#define CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0000  // +/-4.096V range
#define CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define CONFIG_DR_128SPS 0x0060  // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_ACTV_LOW 0x0000 // Active low comparator
#define CONFIG_COMP_LAT_NON_LATCH 0x0000 // Non-latching comparator
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

int i2c_fd;
volatile sig_atomic_t stop_flag = 0;

void signal_handler(int sig) {
    stop_flag = 1;
}

int init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int16_t read_ads1115() {
    uint8_t write_data[3];
    uint8_t read_data[2];

    // Configure the ADS1115 for single-ended AIN0, +/-4.096V, single-shot mode
    uint16_t config = CONFIG_OS_SINGLE | CONFIG_MUX_SINGLE_0 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_ACTV_LOW | CONFIG_COMP_LAT_NON_LATCH | CONFIG_COMP_QUE_DISABLE;

    write_data[0] = ADS1115_REG_CONFIG;
    write_data[1] = (config >> 8) & 0xFF;
    write_data[2] = config & 0xFF;

    if (write(i2c_fd, write_data, 3) != 3) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read the conversion result
    write_data[0] = ADS1115_REG_CONVERT;
    if (write(i2c_fd, write_data, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    if (read(i2c_fd, read_data, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Combine the two bytes into a 16-bit signed integer
    int16_t value = (read_data[0] << 8) | read_data[1];

    return value;
}

int main() {
    if (init_i2c() < 0) {
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!stop_flag) {
        int16_t value = read_ads1115();
        if (value != -1) {
            printf("ADC Value: %d\n", value);
        } else {
            fprintf(stderr, "Failed to read ADC value.\n");
        }
        sleep(0.5);
    }

    close(i2c_fd);
    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX90614_ADDR 0x5A
#define MLX90614_TOBJ1 0x07

int i2c_fd;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting...\n");
    if (i2c_fd > 0) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read temperature from MLX90614
float read_temperature() {
    unsigned char buf[3];
    int result;

    // Write the register address to read from
    buf[0] = MLX90614_TOBJ1;
    result = write(i2c_fd, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1000.0; // Indicate error
    }

    // Read 3 bytes of data (2 for temperature, 1 for CRC)
    result = read(i2c_fd, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1000.0; // Indicate error
    }

    // Convert the data to temperature (Celsius)
    int raw_temp = (buf[1] << 8) | buf[0];
    float temperature = (float)raw_temp * 0.02 - 273.15;

    return temperature;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        float temperature = read_temperature();

        if (temperature > -999.0) {
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Error reading temperature.\n");
        }

        sleep(5);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 4
#define GPIO_PIN_2 17

struct gpiod_chip *chip;
struct gpiod_line *line;
struct gpiod_line *line2;

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", sig);
}

int main() {
    int ret;
    struct timespec delay = {0, 100000000}; // 100ms

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Open chip failed");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Get line failed");
        gpiod_chip_close(chip);
        return 1;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("Get line failed");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio-test", 0);
    if (ret < 0) {
        perror("Request line output failed");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line2, "gpio-test", 0);
    if (ret < 0) {
        perror("Request line output failed");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Toggle GPIO 4
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Set line value failed");
            break;
        }
        nanosleep(&delay, NULL);

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Set line value failed");
            break;
        }
        nanosleep(&delay, NULL);

        // Toggle GPIO 17
        ret = gpiod_line_set_value(line2, 1);
        if (ret < 0) {
            perror("Set line value failed");
            break;
        }
        nanosleep(&delay, NULL);

        ret = gpiod_line_set_value(line2, 0);
        if (ret < 0) {
            perror("Set line value failed");
            break;
        }
        nanosleep(&delay, NULL);
    }

    // Release GPIO line
    gpiod_line_release(line);
    gpiod_line_release(line2);

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("Program finished.\n");
    return 0;
}

