#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN_17 17
#define GPIO_PIN_18 18

struct gpiod_chip *chip;
struct gpiod_line *line_17, *line_18;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (line_17) {
        gpiod_line_release(line_17);
    }
    if (line_18) {
        gpiod_line_release(line_18);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    int ret;
    int value;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line_17 = gpiod_chip_get_line(chip, GPIO_PIN_17);
    if (!line_17) {
        perror("Error getting GPIO line 17");
        gpiod_chip_close(chip);
        return 1;
    }

    line_18 = gpiod_chip_get_line(chip, GPIO_PIN_18);
    if (!line_18) {
        perror("Error getting GPIO line 18");
        gpiod_chip_close(chip);
        gpiod_line_release(line_17);
        return 1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line_17, "gpio_test", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 17 for output");
        gpiod_chip_close(chip);
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        return 1;
    }

    ret = gpiod_line_request_output(line_18, "gpio_test", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 18 for output");
        gpiod_chip_close(chip);
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        return 1;
    }

    // Set GPIO lines to 1 and 0
    ret = gpiod_line_set_value(line_17, 1);
    if (ret < 0) {
        perror("Error setting GPIO line 17 to 1");
        gpiod_chip_close(chip);
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        return 1;
    }

