        gpiod_chip_close(chip);
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        return 1;
    }
    printf("GPIO 18: %d\n", value);

    // Release GPIO lines and chip
    gpiod_line_release(line_17);
    gpiod_line_release(line_18);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Generate PWM signal
        for (int duty_cycle = 0; duty_cycle <= PWM_RANGE; duty_cycle += 100) {
            gpioPWM(PWM_GPIO, duty_cycle);
            printf("Duty cycle: %d\n", duty_cycle);
            gpioDelay(500000); // 0.5 seconds
        }
        for (int duty_cycle = PWM_RANGE; duty_cycle >= 0; duty_cycle -= 100) {
            gpioPWM(PWM_GPIO, duty_cycle);
            printf("Duty cycle: %d\n", duty_cycle);
            gpioDelay(500000); // 0.5 seconds
        }
    }

