    gpioPWM(PWM_GPIO, 0); // Stop PWM
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 500000       // 0.5 seconds timeout

// Global variable for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance in centimeters
float measureDistance() {
    long long start_tick, end_tick, diff_tick;

    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Wait for the echo pin to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo start.\n");
        return -1.0; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo end.\n");
        return -1.0; // Indicate timeout error
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s, and by 2 for one-way distance

    return distance;
}

// Function to get the current timestamp
void getTimestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Trigger the sensor
        triggerSensor();

        // Measure the distance
        float distance = measureDistance();

        // Get the current timestamp
        char timestamp[20];
        getTimestamp(timestamp);

        // Print the timestamp and distance
        if (distance >= 0) {
            printf("%s, Distance: %.2f cm\n", timestamp, distance);
        } else {
            fprintf(stderr, "%s, Error: Sensor timeout or error\n", timestamp);
        }

        // Wait for 60 seconds
        sleep(60);
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x28

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register settings
#define ADS1115_CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define ADS1115_CONFIG_PGA_4_096V 0x0000  // +/-4.096V range
#define ADS1115_CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS 0x0080  // 128 SPS
#define ADS1115_CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define ADS1115_CONFIG_COMP_POL_LOW 0x0000  // Active low comparator
#define ADS1115_CONFIG_COMP_LAT_NON 0x0000 // Non-latching comparator
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variables
int i2c_fd;
volatile sig_atomic_t stop_flag = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    stop_flag = 1;
}

// Function to write a 16-bit value to the ADS1115
int write_ads1115(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;       // LSB

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to ADS1115");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from the ADS1115
int read_ads1115(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[1];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address to ADS1115");
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from ADS1115");
        return -1;
    }

    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read the ADC value from AIN0
int read_adc(int fd) {
    uint16_t config;
    uint16_t conversion;

    // Configure the ADS1115 for single-ended AIN0, +/-4.096V, single conversion
    config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD | ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON | ADS1115_CONFIG_COMP_QUE_DISABLE;

    if (write_ads1115(fd, ADS1115_REG_CONFIG, config) != 0) {
        fprintf(stderr, "Failed to configure ADS1115\n");
        return -1;
    }

    // Wait for the conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    if (read_ads1115(fd, ADS1115_REG_CONVERT, &conversion) != 0) {
        fprintf(stderr, "Failed to read conversion result\n");
        return -1;
    }

    // Check for valid reading (ADS1115 is a 16-bit ADC, so the value is always valid)
    if (conversion > 32767 || conversion < -32768) {
        fprintf(stderr, "Invalid ADC reading: %d\n", conversion);
        return -1;
    }

    return (int16_t)conversion;
}

int main() {
    int adc_value;
    struct timespec ts;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!stop_flag) {
        adc_value = read_adc(i2c_fd);

        if (adc_value >= 0) {
            clock_gettime(CLOCK_REALTIME, &ts);
            printf("%ld.%09ld, %d\n", ts.tv_sec, ts.tv_nsec, adc_value);
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        sleep(5);
    }

    // Close I2C device
    close(i2c_fd);

    printf("Exiting cleanly.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18
#define DELAY_SECONDS 1

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int ret;
    int i;

    /* Register signal handler for SIGINT (Ctrl+C) */
    signal(SIGINT, signal_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    /* Request GPIO line for output */
    ret = gpiod_line_request_output(line, "gpio-test", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    /* Main loop */
    while (!terminate) {
        /* Toggle GPIO state */
        for (i = 0; i < 2; i++) {
            ret = gpiod_line_set_value(line, i);
            if (ret < 0) {
                fprintf(stderr, "Error setting GPIO value: %s\n", strerror(errno));
                goto cleanup;
            }

            /* Read GPIO state and print to stdout */
            int value = gpiod_line_get_value(line);
            if (value < 0) {
                fprintf(stderr, "Error getting GPIO value: %s\n", strerror(errno));
                goto cleanup;
            }
            printf("GPIO %d: %d\n", GPIO_PIN, value);

            sleep(DELAY_SECONDS);
        }
    }

cleanup:
    /* Release GPIO line */
    if (line) {
        gpiod_line_release(line);
    }

    /* Close GPIO chip */
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18
#define NUM_CYCLES 3
#define CYCLE_DELAY 2

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int i, ret;
    struct gpiod_line_request_config config;

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure GPIO line as output
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop: Toggle GPIO output and report state
    for (i = 0; i < NUM_CYCLES; i++) {
        // Set GPIO high
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO high: %s\n", strerror(errno));
            gpiod_chip_close(chip);
            return 1;
        }
        printf("GPIO %d set to HIGH\n", GPIO_PIN);
        sleep(CYCLE_DELAY);

        // Set GPIO low
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO low: %s\n", strerror(errno));
            gpiod_chip_close(chip);
            return 1;
        }
        printf("GPIO %d set to LOW\n", GPIO_PIN);
        sleep(CYCLE_DELAY);
    }

    // Release GPIO line and chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Program terminated gracefully.\n");
    return 0;
}

