// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register settings
#define CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0000  // +/-4.096V range
#define CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define CONFIG_DR_128SPS 0x0060  // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_LOW 0x0000 // Active low comparator
#define CONFIG_COMP_LAT_NON 0x0000 // Non-latching comparator
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

int i2c_fd;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd > 0) {
        close(i2c_fd);
    }
    gpioTerminate();
    exit(0);
}

// Function to read a 16-bit value from the ADS1115
int16_t read_ads1115(int fd) {
    uint8_t buf[2];
    int16_t value;

    // Write the configuration register address
    if (write(fd, &ADS1115_REG_CONVERT, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    // Read the conversion result
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    value = (buf[0] << 8) | buf[1];

    return value;
}

int main() {
    int16_t adc_value;
    uint16_t config;

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpioTerminate();
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Configure the ADS1115 for single-ended input on AIN0, +/-4.096V range, 128 SPS, and single conversion mode
    config = CONFIG_OS_SINGLE | CONFIG_MUX_SINGLE_0 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_LOW | CONFIG_COMP_LAT_NON | CONFIG_COMP_QUE_DISABLE;

    // Write the configuration to the ADS1115
    uint8_t config_buf[3];
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (config >> 8) & 0xFF;
    config_buf[2] = config & 0xFF;

    if (write(i2c_fd, config_buf, 3) != 3) {
        perror("Failed to write configuration to I2C device");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Wait for the conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the ADC value
    adc_value = read_ads1115(i2c_fd);
    if (adc_value < 0) {
        fprintf(stderr, "Failed to read ADC value\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Print the ADC value
    printf("ADC Value: %d\n", adc_value);

    // Close the I2C device and terminate pigpio
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

