#define GPIO_PIN_2 3

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line1, *line2;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    int i, ret;
    struct timespec sleep_time;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("Error getting GPIO line 1");
        gpiod_chip_close(chip);
        return 1;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("Error getting GPIO line 2");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        return 1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line1, "gpio_control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 1 for output");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        return 1;
    }

    ret = gpiod_line_request_output(line2, "gpio_control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 2 for output");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        return 1;
    }

    // Main loop
    while (1) {
        // Toggle GPIO 2
        ret = gpiod_line_set_value(line2, 1);
        if (ret < 0) {
            perror("Error setting GPIO line 2 value");
            break;
        }
        printf("GPIO %d: %d\n", GPIO_PIN_2, 1);

        // Toggle GPIO 3
        ret = gpiod_line_set_value(line1, 0);
        if (ret < 0) {
            perror("Error setting GPIO line 1 value");
            break;
        }
        printf("GPIO %d: %d\n", GPIO_PIN_1, 0);

        // Sleep for 5 seconds
        sleep_time.tv_sec = 5;
        sleep_time.tv_nsec = 0;
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup (in case of error)
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

