static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int ret;
    struct timespec ts;
    int value;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
