#include <time.h>

// Define GPIO pins
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_22 22
#define GPIO_27 27

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line4, *line17, *line22, *line27;

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Function to set GPIO output
int set_gpio_output(struct gpiod_line *line, int value);

// Function to read GPIO input
int read_gpio_input(struct gpiod_line *line);

// Function to cleanup GPIO resources
void cleanup_gpio();

int main()
{
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line4 = gpiod_chip_get_line(chip, GPIO_4);
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    line22 = gpiod_chip_get_line(chip, GPIO_22);
    line27 = gpiod_chip_get_line(chip, GPIO_27);

    if (!line4 || !line17 || !line22 || !line27) {
        perror("Error getting GPIO line");
        cleanup_gpio();
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line4, "gpio_test", 0) < 0) {
        perror("Error requesting GPIO line for output");
        cleanup_gpio();
        return 1;
    }
    if (gpiod_line_request_output(line17, "gpio_test", 0) < 0) {
        perror("Error requesting GPIO line for output");
        cleanup_gpio();
        return 1;
    }
    if (gpiod_line_request_output(line22, "gpio_test", 0) < 0) {
        perror("Error requesting GPIO line for output");
        cleanup_gpio();
        return 1;
    }
    if (gpiod_line_request_output(line27, "gpio_test", 0) < 0) {
        perror("Error requesting GPIO line for output");
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO outputs
        if (set_gpio_output(line4, 1) < 0) {
            fprintf(stderr, "Error setting GPIO %d\n", GPIO_4);
        }
        if (set_gpio_output(line17, 0) < 0) {
            fprintf(stderr, "Error setting GPIO %d\n", GPIO_17);
        }
        if (set_gpio_output(line22, 1) < 0) {
            fprintf(stderr, "Error setting GPIO %d\n", GPIO_22);
        }
        if (set_gpio_output(line27, 0) < 0) {
            fprintf(stderr, "Error setting GPIO %d\n", GPIO_27);
        }

        // Read GPIO inputs
        int value4 = read_gpio_input(line4);
        int value17 = read_gpio_input(line17);
        int value22 = read_gpio_input(line22);
        int value27 = read_gpio_input(line27);

        // Print GPIO states
        printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n",
               GPIO_4, value4, GPIO_17, value17, GPIO_22, value22, GPIO_27, value27);

        // Wait for 2 seconds
        sleep(2);
    }

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("Caught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Function to set GPIO output
int set_gpio_output(struct gpiod_line *line, int value)
{
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Function to read GPIO input
int read_gpio_input(struct gpiod_line *line)
{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading GPIO value");
        return -1;
    }
    return value;
}

// Function to cleanup GPIO resources
void cleanup_gpio()
{
    if (line4) {
        gpiod_line_release(line4);
    }
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line22) {
        gpiod_line_release(line22);
    }
    if (line27) {
        gpiod_line_release(line27);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

