#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line1, *line2;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    int value1, value2;
    struct timespec delay;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN_1, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN_2, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        return 1;
    }

    // Request GPIO lines as output
    if (gpiod_line_request_output(line1, "gpio_control", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_PIN_1, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        return 1;
    }

    if (gpiod_line_request_output(line2, "gpio_control", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_PIN_2, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        return 1;
    }

    // Main loop
    while (1) {
        // Read GPIO lines
        value1 = gpiod_line_get_value(line1);
        value2 = gpiod_line_get_value(line2);

        // Validate readings
        if (value1 != 0 && value1 != 1) {
            fprintf(stderr, "Error: Invalid value read from GPIO %d: %d\n", GPIO_PIN_1, value1);
            gpiod_line_set_value(line1, 0); // Reset to 0
            value1 = 0;
        }
        if (value2 != 0 && value2 != 1) {
            fprintf(stderr, "Error: Invalid value read from GPIO %d: %d\n", GPIO_PIN_2, value2);
            gpiod_line_set_value(line2, 0); // Reset to 0
            value2 = 0;
        }

        // Toggle GPIO lines
        gpiod_line_set_value(line1, !value1);
        gpiod_line_set_value(line2, !value2);

        // Print GPIO states
        printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_PIN_1, gpiod_line_get_value(line1), GPIO_PIN_2, gpiod_line_get_value(line2));

        // Delay for 5 seconds
        delay.tv_sec = 5;
        delay.tv_nsec = 0;
        nanosleep(&delay, NULL);
    }

    // Cleanup (should not reach here in normal operation due to the infinite loop)
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return 0;
}

