#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define SI7021_ADDR 0x40
#define MEASURE_TEMP_CMD 0xE3
#define MEASURE_HUMID_CMD 0xE5

int i2c_fd;
volatile sig_atomic_t stop_flag = 0;

void signal_handler(int sig) {
    stop_flag = 1;
}

int init_i2c() {
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }
    return 0;
}

int read_sensor(int cmd, float *value) {
    unsigned char buf[2];
    int retries = 3;
    int delay_ms = 10;

    while (retries > 0) {
        if (write(i2c_fd, &cmd, 1) != 1) {
            perror("Error writing to I2C device");
            retries--;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }

        usleep(10000); // Wait for measurement (datasheet specifies typical 12.5ms)

        if (read(i2c_fd, buf, 2) != 2) {
            perror("Error reading from I2C device");
            retries--;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }

        unsigned int raw_value = (buf[0] << 8) | buf[1];

        if (cmd == MEASURE_TEMP_CMD) {
            *value = (175.72 * raw_value / 65536.0) - 46.85;
        } else if (cmd == MEASURE_HUMID_CMD) {
            *value = (125.0 * raw_value / 65536.0) - 6.0;
        } else {
            fprintf(stderr, "Invalid sensor command: %d\n", cmd);
            return -1;
        }

        return 0; // Success
    }

    fprintf(stderr, "Failed to read sensor after multiple retries.\n");
    return -1; // Failure
}

int main() {
    struct timespec sleep_time = {5, 0}; // 5 seconds
    float temperature, humidity;

    signal(SIGINT, signal_handler);

    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    while (!stop_flag) {
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

        if (read_sensor(MEASURE_TEMP_CMD, &temperature) == 0 &&
            read_sensor(MEASURE_HUMID_CMD, &humidity) == 0) {
            printf("%s Temperature: %.2f C, Humidity: %.2f %%\n", buf, temperature, humidity);
        } else {
            fprintf(stderr, "%s Sensor read failed.\n", buf);
        }

        nanosleep(&sleep_time, NULL);
    }

    close(i2c_fd);
    printf("Exiting cleanly.\n");
    return 0;
}

#include <stdio.h>
