#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096

int i2c_fd;

// Function to write a 16-bit value to the ADS1115 configuration register
int write_config_register(int fd, uint16_t config) {
    uint8_t buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to config register");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from the ADS1115 conversion register
int16_t read_conversion_register(int fd) {
    uint8_t buf[2];
    buf[0] = CONVERSION_REG;

    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to conversion register address");
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        perror("Failed to read conversion register");
        return -1;
    }

    return (int16_t)((buf[0] << 8) | buf[1]);
}

int main() {
    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Configure the ADS1115 for single-ended channel 0, 4.096V range, 128 SPS
    uint16_t config = 0x4003; // 0b0100000000000011

    if (write_config_register(i2c_fd, config) != 0) {
        close(i2c_fd);
        return 1;
    }

    // Wait for the conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read and print the conversion result
    int16_t conversion_result = read_conversion_register(i2c_fd);
    if (conversion_result < 0) {
        close(i2c_fd);
        return 1;
    }

    float voltage = (float)conversion_result * REF_VOLTAGE / 32768.0;
    printf("Channel 0: %.3f V\n", voltage);

    // Close the I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_8 8
#define GPIO_9 9
#define GPIO_10 10
#define GPIO_11 11
#define GPIO_23 23
#define GPIO_24 24

// Define chip name
#define CHIP_NAME "gpiochip0"

// Define chip and line structs
struct gpiod_chip *chip;
struct gpiod_line *line8, *line9, *line10, *line11, *line23, *line24;

// Define the number of cycles
#define NUM_CYCLES 256

// Define the delay in nanoseconds
#define DELAY_NS 100000000 // 100ms

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

// Function to set GPIO line value
int set_gpio_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Function to get GPIO line value
int get_gpio_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error getting GPIO value");
        return -1;
    }
    return value;
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line8 = gpiod_chip_get_line(chip, GPIO_8);
    line9 = gpiod_chip_get_line(chip, GPIO_9);
    line10 = gpiod_chip_get_line(chip, GPIO_10);
    line11 = gpiod_chip_get_line(chip, GPIO_11);
    line23 = gpiod_chip_get_line(chip, GPIO_23);
    line24 = gpiod_chip_get_line(chip, GPIO_24);

    if (!line8 || !line9 || !line10 || !line11 || !line23 || !line24) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line8, "gpio_test", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(line9, "gpio_test", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(line10, "gpio_test", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(line11, "gpio_test", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(line23, "gpio_test", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(line24, "gpio_test", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    for (int i = 0; i < NUM_CYCLES && program_running; ++i) {
        // Set GPIO values
        if (set_gpio_value(line8, 1) < 0) goto cleanup;
        if (set_gpio_value(line9, 0) < 0) goto cleanup;
        if (set_gpio_value(line10, 1) < 0) goto cleanup;
        if (set_gpio_value(line11, 0) < 0) goto cleanup;
        if (set_gpio_value(line23, 1) < 0) goto cleanup;
        if (set_gpio_value(line24, 0) < 0) goto cleanup;

        // Get GPIO values
        int value8 = get_gpio_value(line8);
        int value9 = get_gpio_value(line9);
        int value10 = get_gpio_value(line10);
        int value11 = get_gpio_value(line11);
        int value23 = get_gpio_value(line23);
        int value24 = get_gpio_value(line24);

        if (value8 < 0 || value9 < 0 || value10 < 0 || value11 < 0 || value23 < 0 || value24 < 0) {
            goto cleanup;
        }

        // Print GPIO values
        printf("Cycle %d: GPIO8=%d, GPIO9=%d, GPIO10=%d, GPIO11=%d, GPIO23=%d, GPIO24=%d\n",
               i, value8, value9, value10, value11, value23, value24);

        // Delay
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = DELAY_NS;
        nanosleep(&ts, NULL);

        // Reset GPIO values
        if (set_gpio_value(line8, 0) < 0) goto cleanup;
        if (set_gpio_value(line9, 1) < 0) goto cleanup;
        if (set_gpio_value(line10, 0) < 0) goto cleanup;
        if (set_gpio_value(line11, 1) < 0) goto cleanup;
        if (set_gpio_value(line23, 0) < 0) goto cleanup;
        if (set_gpio_value(line24, 1) < 0) goto cleanup;

        // Get GPIO values
        value8 = get_gpio_value(line8);
        value9 = get_gpio_value(line9);
        value10 = get_gpio_value(line10);
        value11 = get_gpio_value(line11);
        value23 = get_gpio_value(line23);
        value24 = get_gpio_value(line24);

        if (value8 < 0 || value9 < 0 || value10 < 0 || value11 < 0 || value23 < 0 || value24 < 0) {
            goto cleanup;
        }

        // Print GPIO values
        printf("Cycle %d: GPIO8=%d, GPIO9=%d, GPIO10=%d, GPIO11=%d, GPIO23=%d, GPIO24=%d\n",
               i, value8, value9, value10, value11, value23, value24);

        // Delay
        ts.tv_sec = 0;
        ts.tv_nsec = DELAY_NS;
        nanosleep(&ts, NULL);
    }

    // Cleanup
cleanup:
    printf("Cleaning up GPIO lines.\n");
    gpiod_line_release(line8);
    gpiod_line_release(line9);
    gpiod_line_release(line10);
    gpiod_line_release(line11);
    gpiod_line_release(line23);
    gpiod_line_release(line24);
    gpiod_chip_close(chip);

    return 0;
}

