void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int ret;
    struct gpiod_line_request_config config;

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure GPIO line as output
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        perror("gpiod_line_request");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set GPIO line to HIGH
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        gpiod_chip_close(chip);
        return 1;
    }

    // Report GPIO state
    printf("GPIO %d set to HIGH\n", GPIO_PIN);

    // Wait for a short period
    sleep(1);

    // Set GPIO line to LOW
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        gpiod_chip_close(chip);
        return 1;
    }

    // Report GPIO state
    printf("GPIO %d set to LOW\n", GPIO_PIN);

    // Release GPIO line and chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

