        // Set GPIO output to 0
        if (set_gpio_output(line1, 0) < 0) {
            fprintf(stderr, "Error setting GPIO output\n");
            break;
        }

        // Read GPIO input
        input_value = read_gpio_input(line2);
        if (input_value < 0) {
            fprintf(stderr, "Error reading GPIO input\n");
            break;
        }

        // Get timestamp
        get_timestamp(timestamp);

        // Print output
        printf("%s GPIO1: %d, GPIO2: %d\n", timestamp, 0, input_value);

        // Wait for 0.5 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500000000; // 500 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO lines
    gpiod_line_release(line1);
    gpiod_line_release(line2);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

