    printf("GPIO %d toggling output. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (!terminate) {
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Set line value failed");
            break;
        }
        printf("GPIO %d set to 1\n", GPIO_PIN);
        nanosleep(&ts, NULL);

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Set line value failed");
            break;
        }
        printf("GPIO %d set to 0\n", GPIO_PIN);
        nanosleep(&ts, NULL);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("GPIO %d released and chip closed.\n", GPIO_PIN);

    return 0;
}

