        if (set_gpio_output(line2, 1) < 0) {
            fprintf(stderr, "Error setting GPIO output for line %d\n", GPIO_PIN_2);
            break;
        }

        // Read GPIO input
        int pin1_value = read_gpio_input(line1);
        int pin2_value = read_gpio_input(line2);

        // Get timestamp
        char timestamp[30];
        get_timestamp(timestamp);

        // Log data
        log_data(pin1_value, pin2_value, timestamp);

        // Wait for 5 seconds
