#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3
#define NUM_CYCLES 3

struct gpiod_chip *chip;
struct gpiod_line *line1, *line2;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    int i, ret;
    struct gpiod_line_request_config config;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN_1, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN_2, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        return 1;
    }

    // Request GPIO lines for output
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line1, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO_PIN_1, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        return 1;
    }

    ret = gpiod_line_request(line2, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO_PIN_2, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        return 1;
    }

    // Main loop
    for (i = 0; i < NUM_CYCLES; i++) {
        // Set GPIO 2 HIGH
        ret = gpiod_line_set_value(line1, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d: %s\n", GPIO_PIN_1, strerror(errno));
            gpiod_chip_close(chip);
            gpiod_line_release(line1);
            gpiod_line_release(line2);
            return 1;
        }
        printf("GPIO %d: HIGH\n", GPIO_PIN_1);

        // Set GPIO 3 LOW
        ret = gpiod_line_set_value(line2, 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d: %s\n", GPIO_PIN_2, strerror(errno));
            gpiod_chip_close(chip);
            gpiod_line_release(line1);
            gpiod_line_release(line2);
            return 1;
        }
        printf("GPIO %d: LOW\n", GPIO_PIN_2);

        sleep(1);

        // Set GPIO 2 LOW
        ret = gpiod_line_set_value(line1, 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d: %s\n", GPIO_PIN_1, strerror(errno));
            gpiod_chip_close(chip);
            gpiod_line_release(line1);
            gpiod_line_release(line2);
            return 1;
        }
        printf("GPIO %d: LOW\n", GPIO_PIN_1);

        // Set GPIO 3 HIGH
        ret = gpiod_line_set_value(line2, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d: %s\n", GPIO_PIN_2, strerror(errno));
            gpiod_chip_close(chip);
            gpiod_line_release(line1);
            gpiod_line_release(line2);
            return 1;
        }
        printf("GPIO %d: HIGH\n", GPIO_PIN_2);

        sleep(1);
    }

    // Cleanup
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return 0;
}

