#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define DELAY_MS 500

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int ret;
    int value;

    /* Register signal handler for SIGINT (Ctrl+C) */
    signal(SIGINT, signal_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    /* Request GPIO line for output */
    ret = gpiod_line_request_output(line, "gpio-test", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    /* Main loop */
    value = 0;
    while (!terminate) {
        /* Set GPIO line value */
        ret = gpiod_line_set_value(line, value);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
            break;
        }

        /* Print GPIO line value */
        printf("GPIO %d: %d\n", GPIO_PIN, value);

        /* Toggle value */
        value = !value;

        /* Wait for 0.5 seconds */
        usleep(DELAY_MS * 1000);
    }

    /* Release GPIO line */
    if (line) {
        gpiod_line_release(line);
    }

    /* Close GPIO chip */
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

