volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", sig);
}

int main() {
    int ret;
    struct timespec delay = {0, DELAY_MS * 1000000L}; // 100ms

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line_17 = gpiod_chip_get_line(chip, GPIO_PIN_17);
    if (!line_17) {
        perror("Error getting GPIO line 17");
        gpiod_chip_close(chip);
        return 1;
    }

    line_18 = gpiod_chip_get_line(chip, GPIO_PIN_18);
    if (!line_18) {
        perror("Error getting GPIO line 18");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line_17, "gpio-test", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 17 for output");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line_18, "gpio-test", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 18 for output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    int state_17 = 0;
    int state_18 = 0;
    while (program_running) {
        // Toggle states
        state_17 = !state_17;
        state_18 = !state_18;

        // Set GPIO line values
        ret = gpiod_line_set_value(line_17, state_17);
        if (ret < 0) {
            perror("Error setting GPIO line 17 value");
            break;
        }

        ret = gpiod_line_set_value(line_18, state_18);
        if (ret < 0) {
            perror("Error setting GPIO line 18 value");
            break;
        }

        // Print state
        printf("GPIO 17: %d, GPIO 18: %d\n", state_17, state_18);

        // Delay
        nanosleep(&delay, NULL);
    }

    // Release GPIO lines
    gpiod_line_release(line_17);
    gpiod_line_release(line_18);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 4
#define TIMEOUT_US 100000 // 100ms

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int read_dht11(int gpio_pin, int *temperature, int *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    struct timespec start, end;
    long duration;

    // Request GPIO line
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, gpio_pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "dht11_reader", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    // Send start signal
    gpiod_line_set_value(line, 0);
    usleep(1000); // 1ms
    gpiod_line_set_value(line, 1);
    usleep(30); // 20-40us

    // Prepare to read data
    gpiod_line_set_value(line, 0);
    gpiod_line_set_direction(line, GPIOD_LINE_DIR_INPUT);
    usleep(40);

    // Read data
    for (int i = 0; i < 40; i++) {
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(line) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
            if (duration > TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for HIGH\n");
                gpiod_line_release(line);
                gpiod_chip_close(chip);
                return -1;
            }
        }

        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(line) == 1) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
            if (duration > TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for LOW\n");
                gpiod_line_release(line);
                gpiod_chip_close(chip);
                return -1;
            }
        }

        clock_gettime(CLOCK_MONOTONIC, &end);
        duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

        if (duration > 40) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    // Validate checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        fprintf(stderr, "Checksum error\n");
        return -1;
    }

    *humidity = data[0];
    *temperature = data[2];

    return 0;
}

int main() {
    int temperature, humidity;
    int result;

    signal(SIGINT, signal_handler);

    result = read_dht11(GPIO_PIN, &temperature, &humidity);
    if (result == 0) {
        printf("Temperature: %d C, Humidity: %d %%\n", temperature, humidity);
    } else {
        fprintf(stderr, "Failed to read DHT11 sensor\n");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

