#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PWM_PIN_1 2
#define PWM_PIN_2 3
#define PWM_PIN_3 18

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define PWM range (0-1000 for 0-100% duty cycle)
#define PWM_RANGE 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCtrl+C detected. Exiting gracefully...\n");
}

// Function to set PWM duty cycle
int set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > PWM_RANGE) {
        fprintf(stderr, "Error: Invalid duty cycle value. Must be between 0 and %d.\n", PWM_RANGE);
        return -1;
    }

    if (gpioPWM(gpio_pin, duty_cycle) != 0) {
        fprintf(stderr, "Error: Failed to set PWM duty cycle for GPIO %d.\n", gpio_pin);
        return -1;
    }

    return 0;
}

// Function to report PWM state
void report_pwm_state(int gpio_pin, int duty_cycle) {
    printf("GPIO %d: Duty Cycle = %d\n", gpio_pin, duty_cycle);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);

    // Main loop
    int duty_cycle = 0;
    while (program_running) {
        // Set PWM duty cycle for each pin
        if (set_pwm_duty_cycle(PWM_PIN_1, duty_cycle) != 0) {
            program_running = 0; // Exit loop on error
            break;
        }
        if (set_pwm_duty_cycle(PWM_PIN_2, duty_cycle) != 0) {
            program_running = 0; // Exit loop on error
            break;
        }
        if (set_pwm_duty_cycle(PWM_PIN_3, duty_cycle) != 0) {
            program_running = 0; // Exit loop on error
            break;
        }

        // Report PWM state
        report_pwm_state(PWM_PIN_1, duty_cycle);
        report_pwm_state(PWM_PIN_2, duty_cycle);
        report_pwm_state(PWM_PIN_3, duty_cycle);

        // Increment duty cycle
        duty_cycle = (duty_cycle + 100) % (PWM_RANGE + 1);

        // Wait for 0.15 seconds
        usleep(150000); // 150000 microseconds = 0.15 seconds
    }

    // Stop PWM signals
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

