#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins to control
const int gpio_pins[] = {2, 3, 4, 5, 6, 7, 8, 9, 17};
const int num_pins = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

// Global variables for GPIO chip and line
struct gpiod_chip *chip;
struct gpiod_line *lines[10]; // Assuming a maximum of 10 pins

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Function to set GPIO output
int set_gpio_output(int pin, int value);

// Function to get GPIO input
int get_gpio_input(int pin);

// Function to cleanup GPIO resources
void cleanup_gpio();

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

int main()
{
    int i, ret;
    struct timespec sleep_time = {0, 50000000}; // 0.05 seconds

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    // Request GPIO lines
    for (i = 0; i < num_pins; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting GPIO line %d\n", gpio_pins[i]);
            cleanup_gpio();
            return 1;
        }

        ret = gpiod_line_request_output(lines[i], "gpio_control", 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting GPIO line %d as output\n", gpio_pins[i]);
            cleanup_gpio();
            return 1;
        }
    }

    // Main loop
    while (program_running) {
        // Toggle GPIO pins
        for (i = 0; i < num_pins; i++) {
            int current_value = get_gpio_input(gpio_pins[i]);
            if (current_value < 0) {
                fprintf(stderr, "Error getting GPIO input for pin %d\n", gpio_pins[i]);
                cleanup_gpio();
                return 1;
            }
            int new_value = (current_value == 0) ? 1 : 0;
            if (set_gpio_output(gpio_pins[i], new_value) < 0) {
                fprintf(stderr, "Error setting GPIO output for pin %d\n", gpio_pins[i]);
                cleanup_gpio();
                return 1;
            }
            printf("GPIO %d set to %d\n", gpio_pins[i], new_value);
        }

        // Sleep for 0.05 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

// Signal handler function
void signal_handler(int sig)
{
    program_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

// Function to set GPIO output
int set_gpio_output(int pin, int value)
{
    int i;
    for (i = 0; i < num_pins; i++) {
        if (gpio_pins[i] == pin) {
            int ret = gpiod_line_set_value(lines[i], value);
            if (ret < 0) {
                fprintf(stderr, "Error setting GPIO line %d value to %d\n", pin, value);
                return -1;
            }
            return 0;
        }
    }
    fprintf(stderr, "GPIO pin %d not found\n", pin);
    return -1;
}

// Function to get GPIO input
int get_gpio_input(int pin)
{
    int i;
    for (i = 0; i < num_pins; i++) {
        if (gpio_pins[i] == pin) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                fprintf(stderr, "Error getting GPIO line %d value\n", pin);
                return -1;
            }
            return value;
        }
    }
    fprintf(stderr, "GPIO pin %d not found\n", pin);
    return -1;
}

// Function to cleanup GPIO resources
void cleanup_gpio()
{
    int i;
    for (i = 0; i < num_pins; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

