#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>

#define OPT3001_ADDR 0x44
#define I2C_BUS "/dev/i2c-1"

int main() {
    int file;
    uint16_t raw_data;
    float lux;

    // Open I2C bus
    if ((file = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Specify slave address
    if (ioctl(file, I2C_SLAVE, OPT3001_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return 1;
    }

    // Read result register (0x00)
    if (read(file, &raw_data, 2) != 2) {
        perror("Failed to read from I2C bus");
        close(file);
        return 1;
    }

    // Convert to lux
    uint16_t exponent = (raw_data >> 12) & 0x0F;
    uint16_t result = raw_data & 0x0FFF;
    lux = result * (0.01 * (1 << exponent));

    // Print lux value
    printf("Lux: %.2f\n", lux);

    // Close I2C bus
    close(file);

    return 0;
}

