// Function to discover the DS18B20 device ID
int discover_device() {
    DIR *dir;
    struct dirent *ent;
    char path[256];
    int fd;
    char buf[256];
    ssize_t num_read;

    dir = opendir(W1_DEVICES_DIR);
    if (dir == NULL) {
        perror("opendir");
        return -1;
    }

    while ((ent = readdir(dir)) != NULL) {
        if (strncmp(ent->d_name, "28-", 3) == 0) {
            snprintf(path, sizeof(path), "%s/%s/%s", W1_DEVICES_DIR, ent->d_name, W1_SLAVE_FILE);
            fd = open(path, O_RDONLY);
            if (fd != -1) {
                // Check if the device is valid by reading the file
                num_read = read(fd, buf, sizeof(buf));
                if (num_read > 0) {
                    close(fd);
                    strncpy(device_id, ent->d_name, sizeof(device_id) - 1);
                    device_id[sizeof(device_id) - 1] = '\0'; // Ensure null termination
                    printf("Found DS18B20 device: %s\n", device_id);
                    closedir(dir);
                    return 0; // Success
                } else {
                    fprintf(stderr, "Error reading %s: %s\n", path, strerror(errno));
                    close(fd);
                }
            } else {
                fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
            }
        }
    }

    closedir(dir);
    fprintf(stderr, "Error: DS18B20 device not found!\n");
    return -1; // Failure
}

// Function to read the temperature from the DS18B20
float read_temperature() {
    char path[256];
    int fd;
    char buf[256];
    ssize_t num_read;
    char *token;
    float temperature = -999.0; // Default error value

    if (device_id[0] == '\0') {
        fprintf(stderr, "Error: Device ID not found. Please run discover_device() first.\n");
        return -999.0;
    }

    snprintf(path, sizeof(path), "%s/%s/%s", W1_DEVICES_DIR, device_id, W1_SLAVE_FILE);
    fd = open(path, O_RDONLY);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -999.0;
    }

    num_read = read(fd, buf, sizeof(buf));
    if (num_read > 0) {
        close(fd);

        // Check for CRC error
        if (strstr(buf, "YES") != NULL) {
            // Find the temperature line
            char *temp_line = strstr(buf, "t=");
            if (temp_line != NULL) {
                // Extract the temperature value
                token = strtok(temp_line, "=");
                if (token != NULL) {
                    token = strtok(NULL, "\n");
                    if (token != NULL) {
                        temperature = atof(token) / 1000.0;
                    }
                }
            }
        } else {
            fprintf(stderr, "CRC check failed!\n");
            return -999.0;
        }
    } else {
        fprintf(stderr, "Error reading %s: %s\n", path, strerror(errno));
        close(fd);
        return -999.0;
    }

    return temperature;
}

