    time_t rawtime;
    struct tm * timeinfo;
    float temperature;

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Discover the DS18B20 device
    if (discover_device() != 0) {
        return 1;
    }

    // Main loop
    while (1) {
        // Read the temperature
        temperature = read_temperature();

        // Get current time
        time (&rawtime);
        timeinfo = localtime (&rawtime);

        // Print the temperature with timestamp
        if (temperature != -999.0) {
            printf("[%s] Temperature: %.2f °C\n", asctime(timeinfo), temperature);
        } else {
            fprintf(stderr, "[%s] Error reading temperature\n", asctime(timeinfo));
        }

        // Wait for 5 seconds
        sleep(5);
    }

    return 0;
}

