    uint8_t buf[3];
    if (write(i2c_fd, &TRIGGER_TEMP_MEASURE, 1) != 1) {
        perror("Failed to write temperature command");
        return -1;
    }
    usleep(100000); // Wait for measurement (at least 50ms)
    if (read(i2c_fd, buf, 3) != 3) {
        perror("Failed to read temperature data");
        return -1;
    }
    *raw_temp = (buf[0] << 8) | buf[1];
    return 0;
}

int read_raw_humidity(uint16_t *raw_humidity) {
    uint8_t buf[3];
    if (write(i2c_fd, &TRIGGER_HUMID_MEASURE, 1) != 1) {
        perror("Failed to write humidity command");
        return -1;
    }
    usleep(100000); // Wait for measurement (at least 50ms)
    if (read(i2c_fd, buf, 3) != 3) {
        perror("Failed to read humidity data");
        return -1;
    }
    *raw_humidity = (buf[0] << 8) | buf[1];
