int adxl345_init(int fd) {
    // Set POWER_CTL register to start measurement
    if (write(fd, "\x28", 1) != 1) {
        perror("Failed to write to POWER_CTL");
        return -1;
    }
    return 0;
}

// Function to read acceleration data from ADXL345
int adxl345_read_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];

    // Set the register to read from (DATAX0)
    if (write(fd, "\x32", 1) != 1) {
        perror("Failed to set register address");
        return -1;
    }

    // Read 6 bytes of data (X, Y, Z axes)
    if (read(fd, data, 6) != 6) {
        perror("Failed to read data");
        return -1;
    }

    // Combine high and low bytes for each axis
    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

