#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define GPIO pins for DHT22 sensors
#define DHT22_PIN_1 17
#define DHT22_PIN_2 22
#define DHT22_PIN_3 23
#define DHT22_PIN_4 24

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int error;
} DHT22Data;

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read DHT22 data from a given GPIO pin
DHT22Data read_dht22(int gpio_pin) {
    DHT22Data data;
    data.temperature = -999.0; // Initialize with error value
    data.humidity = -999.0;
    data.error = 1; // Assume error initially

    int result;
    int i;
    int data_bits[40];

    gpioSetMode(gpio_pin, PI_OUTPUT);
    gpioWrite(gpio_pin, 0);
    gpioDelay(1);
    gpioWrite(gpio_pin, 1);
    gpioDelay(30);

    gpioSetMode(gpio_pin, PI_INPUT);

    // Wait for the DHT22 to pull the line low (response signal)
    int timeout = 0;
    while (gpioRead(gpio_pin) == 1) {
        gpioDelay(1); // Wait 1 us
        timeout++;
        if (timeout > 100) {
            fprintf(stderr, "DHT22 timeout waiting for start signal on pin %d\n", gpio_pin);
            return data; // Return error
        }
    }

    timeout = 0;
    while (gpioRead(gpio_pin) == 0) {
        gpioDelay(1); // Wait 1 us
        timeout++;
        if (timeout > 100) {
            fprintf(stderr, "DHT22 timeout waiting for end of start signal on pin %d\n", gpio_pin);
            return data; // Return error
        }
    }

    timeout = 0;
    while (gpioRead(gpio_pin) == 1) {
        gpioDelay(1); // Wait 1 us
        timeout++;
        if (timeout > 100) {
            fprintf(stderr, "DHT22 timeout waiting for end of data signal on pin %d\n", gpio_pin);
            return data; // Return error
        }
    }

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(gpio_pin) == 0) {
            gpioDelay(1); // Wait 1 us
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "DHT22 timeout waiting for bit start on pin %d\n", gpio_pin);
                return data; // Return error
            }
        }

        long start = gpioTick();
        timeout = 0;
        while (gpioRead(gpio_pin) == 1) {
            gpioDelay(1); // Wait 1 us
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "DHT22 timeout waiting for bit end on pin %d\n", gpio_pin);
                return data; // Return error
            }
        }
        long end = gpioTick();

        if ((end - start) > 40) {
            data_bits[i] = 1;
        } else {
            data_bits[i] = 0;
        }
    }

    // Convert the data bits to bytes
    unsigned char data_bytes[5];
    for (i = 0; i < 5; i++) {
        data_bytes[i] = 0;
    }

    for (i = 0; i < 40; i++) {
        data_bytes[i / 8] <<= 1;
        data_bytes[i / 8] |= data_bits[i];
    }

    // Verify checksum
    if ((data_bytes[0] + data_bytes[1] + data_bytes[2] + data_bytes[3]) & 0xFF != data_bytes[4]) {
        fprintf(stderr, "DHT22 checksum error on pin %d\n", gpio_pin);
        return data; // Return error
    }

    // Convert data to temperature and humidity
    data.humidity = (float)((data_bytes[0] << 8) | data_bytes[1]) / 10.0;
    data.temperature = (float)(((data_bytes[2] & 0x7F) << 8) | data_bytes[3]) / 10.0;
    if (data_bytes[2] & 0x80) {
        data.temperature *= -1.0;
    }

    data.error = 0; // No error
    return data;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read data from DHT22 sensors
        DHT22Data data1 = read_dht22(DHT22_PIN_1);
        DHT22Data data2 = read_dht22(DHT22_PIN_2);
        DHT22Data data3 = read_dht22(DHT22_PIN_3);
        DHT22Data data4 = read_dht22(DHT22_PIN_4);

        // Print sensor data
        printf("Sensor 1: Temperature = %.1f C, Humidity = %.1f %%\n", data1.temperature, data1.humidity);
        printf("Sensor 2: Temperature = %.1f C, Humidity = %.1f %%\n", data2.temperature, data2.humidity);
        printf("Sensor 3: Temperature = %.1f C, Humidity = %.1f %%\n", data3.temperature, data3.humidity);
        printf("Sensor 4: Temperature = %.1f C, Humidity = %.1f %%\n", data4.temperature, data4.humidity);

        // Wait for 2 seconds
        sleep(2);
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PWM_PIN_1 17
#define PWM_PIN_2 22
#define PWM_PIN_3 27

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define PWM range
#define PWM_RANGE 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCtrl+C detected. Exiting gracefully...\n");
}

// Function to set PWM duty cycle
int set_pwm(int gpio, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > PWM_RANGE) {
        fprintf(stderr, "Error: Duty cycle out of range (0-%d): %d\n", PWM_RANGE, duty_cycle);
        return -1; // Indicate error
    }

    gpioPWM(gpio, duty_cycle);
    return 0; // Indicate success
}

// Function to report PWM state
void report_state(int gpio, int duty_cycle) {
    printf("GPIO %d: Duty Cycle = %d\n", gpio, duty_cycle);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1; // Exit with error code
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);

    // Main loop
    int duty_cycle = 0;
    while (program_running) {
        // Set PWM duty cycles
        if (set_pwm(PWM_PIN_1, duty_cycle) != 0) {
            program_running = 0; // Exit on error
            break;
        }
        if (set_pwm(PWM_PIN_2, duty_cycle) != 0) {
            program_running = 0; // Exit on error
            break;
        }
        if (set_pwm(PWM_PIN_3, duty_cycle) != 0) {
            program_running = 0; // Exit on error
            break;
        }

        // Report PWM state
        report_state(PWM_PIN_1, duty_cycle);
        report_state(PWM_PIN_2, duty_cycle);
        report_state(PWM_PIN_3, duty_cycle);

        // Increment duty cycle
        duty_cycle = (duty_cycle + 100) % (PWM_RANGE + 1);

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    // Cleanup and exit
    gpioTerminate();
    return 0;
}

