    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    /* Get GPIO line for GPIO 17 */
    line_17 = gpiod_chip_get_line(chip, GPIO_PIN_17);
    if (!line_17) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN_17, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    /* Get GPIO line for GPIO 27 */
    line_27 = gpiod_chip_get_line(chip, GPIO_PIN_27);
