        gpiod_chip_close(chip);
        return 1;
    }

    /* Request GPIO line for output */
    ret = gpiod_line_request_output(line_17, "gpio-test", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", GPIO_PIN_17, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line_27, "gpio-test", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", GPIO_PIN_27, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    /* Main loop */
    while (program_running) {
        /* Set GPIO 17 to HIGH */
        ret = gpiod_line_set_value(line_17, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO_PIN_17, strerror(errno));
            break;
        }

        /* Set GPIO 27 to LOW */
        ret = gpiod_line_set_value(line_27, 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO_PIN_27, strerror(errno));
            break;
