        /* Print GPIO states */
        printf("GPIO %d: HIGH, GPIO %d: LOW\n", GPIO_PIN_17, GPIO_PIN_27);

        /* Wait for 1 second */
        sleep(1);

        /* Set GPIO 17 to LOW */
        ret = gpiod_line_set_value(line_17, 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO_PIN_17, strerror(errno));
            break;
        }

        /* Set GPIO 27 to HIGH */
        ret = gpiod_line_set_value(line_27, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO_PIN_27, strerror(errno));
            break;
        }

        /* Print GPIO states */
        printf("GPIO %d: LOW, GPIO %d: HIGH\n", GPIO_PIN_17, GPIO_PIN_27);

        /* Wait for 1 second */
        sleep(1);
    }

    /* Release GPIO lines */
    gpiod_line_release(line_17);
    gpiod_line_release(line_27);

    /* Close GPIO chip */
    gpiod_chip_close(chip);

    return 0;
}

