            printf("PWM Duty Cycle: %d\n", duty_cycle);
            usleep(20000); // 20ms delay
        }
        for (int duty_cycle = PWM_RANGE; duty_cycle >= 0; duty_cycle -= 100) {
            gpioPWM(PWM_PIN, duty_cycle);
            printf("PWM Duty Cycle: %d\n", duty_cycle);
            usleep(20000); // 20ms delay
        }
    }

    // Cleanup and exit
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

