#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// TCS34725 I2C address
#define TCS34725_ADDRESS 0x29

// TCS34725 registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CDATA 0x90
#define TCS34725_RDATA 0x92
#define TCS34725_GDATA 0x94
#define TCS34725_BDATA 0x96

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from the TCS34725
int read_register(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return value;
}

// Function to write a single byte to the TCS34725
int write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register value");
        return -1;
    }
    return 0;
}

// Function to initialize the TCS34725
int initialize_tcs34725(int fd) {
    // Enable the device (power on and enable RGBC)
    if (write_register(fd, TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error enabling TCS34725\n");
        return -1;
    }

    // Set integration time (ATIME) - adjust as needed
    if (write_register(fd, TCS34725_ATIME, 0xD5) < 0) { // 101ms integration time
        fprintf(stderr, "Error setting integration time\n");
        return -1;
    }

    return 0;
}

// Function to read color data from the TCS34725
int read_color_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    int c, r, g, b;

    c = read_register(fd, TCS34725_CDATA);
    r = read_register(fd, TCS34725_RDATA);
    g = read_register(fd, TCS34725_GDATA);
    b = read_register(fd, TCS34725_BDATA);

    if (c < 0 || r < 0 || g < 0 || b < 0) {
        fprintf(stderr, "Error reading color data\n");
        return -1;
    }

    *clear = (uint16_t)c | ((uint16_t)read_register(fd, TCS34725_CDATA + 1) << 8);
    *red   = (uint16_t)r | ((uint16_t)read_register(fd, TCS34725_RDATA + 1) << 8);
    *green = (uint16_t)g | ((uint16_t)read_register(fd, TCS34725_GDATA + 1) << 8);
    *blue  = (uint16_t)b | ((uint16_t)read_register(fd, TCS34725_BDATA + 1) << 8);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize TCS34725
    if (initialize_tcs34725(i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        uint16_t clear, red, green, blue;

        if (read_color_data(i2c_fd, &clear, &red, &green, &blue) == 0) {
            printf("C: %5d, R: %5d, G: %5d, B: %5d\n", clear, red, green, blue);
        } else {
            fprintf(stderr, "Failed to read color data. Retrying...\n");
        }

        usleep(200000); // 0.2 seconds
    }

    // The program should never reach here due to the signal handler
    return 0;
}

