            // Placeholder: Replace with actual font data and rendering logic
            // For example, you might use a lookup table or a bitmap font
            // This example just writes a simple character
            ssd1306_write_data(str[i]);
        } else {
            ssd1306_write_data('?'); // Unknown character
        }
    }
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SSD1306_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize SSD1306
    if (ssd1306_init() < 0) {
        fprintf(stderr, "SSD1306 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Get current time
        time_t rawtime;
        struct tm *timeinfo;
        char buffer[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Clear display
        ssd1306_clear_display();

        // Display current time
        ssd1306_display_string(0, 0, buffer);

        // Wait for 0.1 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 0.1 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    printf("Cleaning up and exiting...\n");
    ssd1306_clear_display();
    close(i2c_fd);

    return 0;
}

