// Define GPIO pins for PWM output
#define PWM_PIN_1 8
#define PWM_PIN_2 9
#define PWM_PIN_3 11
#define PWM_PIN_4 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stdout, "Ctrl+C detected. Exiting gracefully.\n");
}

int main() {
    int result;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);

    // Set PWM frequency to 1000 Hz
    gpioSetPWMfrequency(PWM_PIN_1, 1000);
    gpioSetPWMfrequency(PWM_PIN_2, 1000);
    gpioSetPWMfrequency(PWM_PIN_3, 1000);
    gpioSetPWMfrequency(PWM_PIN_4, 1000);

    // Set PWM range (0-255)
    gpioSetPWMrange(PWM_PIN_1, 255);
    gpioSetPWMrange(PWM_PIN_2, 255);
    gpioSetPWMrange(PWM_PIN_3, 255);
    gpioSetPWMrange(PWM_PIN_4, 255);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set PWM duty cycle for each pin (example values)
        gpioPWM(PWM_PIN_1, 128); // 50% duty cycle
        gpioPWM(PWM_PIN_2, 191); // 75% duty cycle
        gpioPWM(PWM_PIN_3, 64);  // 25% duty cycle
        gpioPWM(PWM_PIN_4, 200); // 80% duty cycle

        // Report the state to standard output
        fprintf(stdout, "PWM_PIN_1: %d, PWM_PIN_2: %d, PWM_PIN_3: %d, PWM_PIN_4: %d\n",
                gpioPWM(PWM_PIN_1, 128), gpioPWM(PWM_PIN_2, 191), gpioPWM(PWM_PIN_3, 64), gpioPWM(PWM_PIN_4, 200));

        // Wait for 1 second
        sleep(1);
    }

    // Stop PWM signals
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_4, 0);

    // Terminate pigpio library
    gpioTerminate();

    fprintf(stdout, "Program terminated successfully.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 23

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 500000       // Timeout in microseconds (0.5 seconds)

// Global variable for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to measure distance using HC-SR04
float measure_distance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Measure echo pulse duration
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            return -1.0; // Indicate timeout error
        }
    }
    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            return -1.0; // Indicate timeout error
        }
    }
    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s, and by 2 for one-way distance

    return distance;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        float distance = measure_distance();

        if (distance >= 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: Distance measurement failed\n");
        }

        gpioDelay(200); // Delay for 0.2 seconds
    }

    // Cleanup and exit
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the GPIO pin connected to the RGB LED strip
#define RGB_GPIO 18

// Define the number of LEDs in the strip
#define NUM_LEDS 10

// Define the delay between colour changes (in milliseconds)
#define DELAY_MS 10

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to set the RGB color of a single LED
void set_led_color(int gpio, int led_index, int red, int green, int blue)
{
    // Calculate the GPIO pin number for the specific LED
    int led_gpio = gpio + led_index;

    // Set the GPIO pin to HIGH or LOW based on the color values
    gpioWrite(led_gpio, (red > 0) ? 1 : 0);
    gpioWrite(led_gpio + 1, (green > 0) ? 1 : 0);
    gpioWrite(led_gpio + 2, (blue > 0) ? 1 : 0);
}

int main()
{
    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the RGB_GPIO pin as an output
    gpioSetMode(RGB_GPIO, PI_OUTPUT);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Main loop to cycle through colors
    while (!terminate)
    {
        // Red color
        for (int i = 0; i < NUM_LEDS; i++)
        {
            set_led_color(RGB_GPIO, i, 255, 0, 0);
            gpioDelay(DELAY_MS * 1000); // Delay in microseconds
        }

        // Green color
        for (int i = 0; i < NUM_LEDS; i++)
        {
            set_led_color(RGB_GPIO, i, 0, 255, 0);
            gpioDelay(DELAY_MS * 1000); // Delay in microseconds
        }

        // Blue color
        for (int i = 0; i < NUM_LEDS; i++)
        {
            set_led_color(RGB_GPIO, i, 0, 0, 255);
            gpioDelay(DELAY_MS * 1000); // Delay in microseconds
        }
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

