static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int ret;
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = TIMEOUT_MS * 1000000; // Convert milliseconds to nanoseconds

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio-test", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop: Toggle GPIO output
    while (!terminate) {
        // Set GPIO high
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line high: %s\n", strerror(errno));
            break;
        }
        printf("GPIO %d set to HIGH\n", GPIO_PIN);

        // Wait for a short period
        nanosleep(&ts, NULL);

        // Set GPIO low
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line low: %s\n", strerror(errno));
            break;
        }
        printf("GPIO %d set to LOW\n", GPIO_PIN);

        // Wait for a short period
        nanosleep(&ts, NULL);
    }

    // Release GPIO line and chip
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Program terminated.\n");
    return 0;
}

