    gpiod_line_release(line5);
    gpiod_line_release(line6);
    gpiod_line_release(line21);
    gpiod_line_release(line22);
    gpiod_line_release(line23);
    gpiod_line_release(line24);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FORMAT V4L2_PIX_FMT_JPEG

// Structure to hold camera device information
typedef struct {
    int fd;
    void *buffer;
    struct v4l2_buffer buf;
} camera_device_t;

// Global variable to track if the program should exit
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the camera device
int init_camera(camera_device_t *camera) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;

    // Open the device
    camera->fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (camera->fd < 0) {
        perror("Error opening device");
        return -1;
    }

    // Check device capabilities
    if (ioctl(camera->fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(camera->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        close(camera->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        close(camera->fd);
        return -1;
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = IMAGE_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(camera->fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(camera->fd);
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(camera->fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(camera->fd);
        return -1;
    }

    // Query buffer
    memset(&camera->buf, 0, sizeof(camera->buf));
    camera->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    camera->buf.memory = V4L2_MEMORY_MMAP;
    camera->buf.index = 0;

    if (ioctl(camera->fd, VIDIOC_QUERYBUF, &camera->buf) < 0) {
        perror("Error querying buffer");
        close(camera->fd);
        return -1;
    }

    // Map the buffer
    camera->buffer = mmap(NULL, camera->buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, camera->fd, camera->buf.m.offset);
    if (camera->buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(camera->fd);
        return -1;
    }

    return 0;
}

// Function to capture an image
int capture_image(camera_device_t *camera) {
    struct v4l2_buffer buf;
    struct timespec ts;
    char filename[64];
    FILE *fp;

    // Queue the buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(camera->fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(camera->fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        return -1;
    }

    // Dequeue the buffer
    if (ioctl(camera->fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        ioctl(camera->fd, VIDIOC_STREAMOFF, &type);
        return -1;
    }

    // Get timestamp
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return -1;
    }

    // Create filename
    snprintf(filename, sizeof(filename), "image_%04ld.jpg", ts.tv_sec);

    // Write to file
    fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        ioctl(camera->fd, VIDIOC_STREAMOFF, &type);
        return -1;
    }

    fwrite(camera->buffer, 1, buf.bytesused, fp);
    fclose(fp);

    // Stop streaming
    if (ioctl(camera->fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        return -1;
    }

    return 0;
}

// Function to cleanup the camera device
void cleanup_camera(camera_device_t *camera) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (camera->fd > 0) {
        ioctl(camera->fd, VIDIOC_STREAMOFF, &type);
        if (camera->buffer != MAP_FAILED && camera->buffer != NULL) {
            munmap(camera->buffer, camera->buf.length);
        }
        close(camera->fd);
    }
}

int main() {
    camera_device_t camera;
    struct timespec sleep_time;

    // Initialize camera device
    if (init_camera(&camera) < 0) {
        fprintf(stderr, "Failed to initialize camera. Exiting.\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 50000000; // 0.05 seconds

    while (program_running) {
        if (capture_image(&camera) < 0) {
            fprintf(stderr, "Failed to capture image. Continuing.\n");
        }
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup camera device
    cleanup_camera(&camera);

    return 0;
}

