// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register settings
#define CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0000  // +/-4.096V range
#define CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define CONFIG_DR_128SPS 0x0060  // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_ACTV_LOW 0x0000 // Active low comparator
#define CONFIG_COMP_LAT_NON_LATCH 0x0000 // Non-latching comparator
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

int i2c_fd;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("Exiting...\n");
    if (i2c_fd > 0) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a 16-bit value to the ADS1115
int write_ads1115(int fd, uint16_t value) {
    uint8_t buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;       // LSB

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to ADS1115");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from the ADS1115
int16_t read_ads1115(int fd) {
    uint8_t buf[2];
    buf[0] = ADS1115_REG_CONVERT;

    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to ADS1115 for read");
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from ADS1115");
        return -1;
    }

    return (int16_t)((buf[0] << 8) | buf[1]);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Configure ADS1115 for single-ended AIN0, +/-4.096V, 128 SPS
        uint16_t config = CONFIG_OS_SINGLE | CONFIG_MUX_SINGLE_0 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_ACTV_LOW | CONFIG_COMP_LAT_NON_LATCH | CONFIG_COMP_QUE_DISABLE;

        if (write_ads1115(i2c_fd, config) < 0) {
            close(i2c_fd);
            return 1;
        }

        // Wait for conversion to complete (at least 125ms for 128 SPS)
        usleep(150000); // 150ms

        // Read conversion result
        int16_t conversion = read_ads1115(i2c_fd);
        if (conversion < 0) {
            close(i2c_fd);
            return 1;
        }

        // Print the conversion result
        printf("AIN0: %d\n", conversion);

        // Wait for 0.2 seconds
        sleep(0.2);
    }

    // Close I2C device (this will never be reached in the infinite loop)
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 4
#define DELAY_SECONDS 60

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int ret;
    int i;
    struct timespec delay = {DELAY_SECONDS, 0};

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s\n", GPIO_CHIP);
        return 1;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    /* Request GPIO line for output */
    ret = gpiod_line_request_output(line, "gpio-test", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %d\n", ret);
        gpiod_chip_close(chip);
        return 1;
    }

    /* Set up signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    /* Main loop */
    while (!terminate) {
        /* Toggle GPIO state */
        for (i = 0; i < 2; i++) {
            ret = gpiod_line_set_value(line, i);
            if (ret < 0) {
                fprintf(stderr, "Error setting GPIO value: %d\n", ret);
                goto cleanup;
            }
            printf("GPIO %d set to %d\n", GPIO_PIN, i);
            nanosleep(&delay, NULL);
        }
    }

cleanup:
    /* Release GPIO line */
    if (line) {
        gpiod_line_release(line);
    }

    /* Close GPIO chip */
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

