// Initialize the LCD
int lcd_init() {
    // 4-bit initialization sequence
    usleep(50000); // Wait for more than 40ms after VCC rises to 4.5V
    lcd_send_command(0x30); // Initialization command 1
    usleep(5000);  // Wait for more than 4.1ms
    lcd_send_command(0x30); // Initialization command 2
    usleep(1000);  // Wait for more than 100us
    lcd_send_command(0x30); // Initialization command 3
    usleep(1000);  // Wait for more than 100us
    lcd_send_command(0x20); // 4-bit mode
    usleep(1000);  // Wait for more than 100us

    lcd_send_command(LCD_FUNCTIONSET | LCD_4BITMODE | LCD_2LINE | LCD_5x8DOTS);
    lcd_send_command(LCD_DISPLAYCONTROL | LCD_DISPLAYON | LCD_CURSOROFF | LCD_BLINKOFF);
    lcd_send_command(LCD_ENTRYMODESET | LCD_ENTRYLEFT | LCD_ENTRYSHIFTDECREMENT);
    lcd_clear();
    return 0;
}

// Send a command to the LCD
int lcd_send_command(unsigned char cmd) {
    unsigned char data_u, data_l;
	data_u = (cmd & 0xF0);
	data_l = ((cmd << 4) & 0xF0);

	unsigned char data[4] = {data_u | 0x0C, data_u | 0x08, data_l | 0x0C, data_l | 0x08};

	for (int i = 0; i < 4; i++) {
		if (write(i2c_fd, &data[i], 1) != 1) {
			perror("Failed to write command to LCD");
			return -1;
		}
		usleep(1); // Delay for 1us
	}
    return 0;
}

