#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B

int main() {
    int file;
    int16_t accel_x, accel_y, accel_z;
    int i;

    // Open I2C device
    if ((file = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify slave address
    if (ioctl(file, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return 1;
    }

    // Wake up MPU6050
    uint8_t data[2] = {PWR_MGMT_1, 0x00};
    if (write(file, data, 2) != 2) {
        perror("Failed to write to I2C device");
        close(file);
        return 1;
    }

    // Read accelerometer data
    for (i = 0; i < 100; i++) {
        // Read accelerometer data
        if (read(file, (char[14]){ACCEL_XOUT_H}, 14) != 14) {
            perror("Failed to read from I2C device");
            close(file);
            return 1;
        }

        // Extract accelerometer values
        accel_x = (int16_t)((buffer[1] << 8) | buffer[0]);
        accel_y = (int16_t)((buffer[3] << 8) | buffer[2]);
        accel_z = (int16_t)((buffer[5] << 8) | buffer[4]);

        // Print accelerometer values
        printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n", accel_x, accel_y, accel_z);

        usleep(10000); // 10ms delay
    }

    // Close I2C device
    close(file);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins
#define GPIO_PIN_1 14
#define GPIO_PIN_2 15

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line1, *line2;

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Function to set GPIO output
int set_gpio_output(struct gpiod_line *line, int value);

// Function to read GPIO input
int read_gpio_input(struct gpiod_line *line);

// Function to get current timestamp
void get_timestamp(char *timestamp);

// Function to log data to standard output
void log_data(int pin1_value, int pin2_value);

// Global variable to control the main loop
volatile sig_atomic_t running = 1;

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN_1, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN_2, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line1, "gpio_control", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", GPIO_PIN_1, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line2, "gpio_control", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", GPIO_PIN_2, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (running) {
        // Set GPIO output to 1
        if (set_gpio_output(line1, 1) < 0) {
            fprintf(stderr, "Error setting GPIO line %d to 1\n", GPIO_PIN_1);
            break;
        }
        if (set_gpio_output(line2, 1) < 0) {
            fprintf(stderr, "Error setting GPIO line %d to 1\n", GPIO_PIN_2);
            break;
        }

        // Read GPIO input
        int pin1_value = read_gpio_input(line1);
        int pin2_value = read_gpio_input(line2);

        // Log data
        log_data(pin1_value, pin2_value);

        // Set GPIO output to 0
        if (set_gpio_output(line1, 0) < 0) {
            fprintf(stderr, "Error setting GPIO line %d to 0\n", GPIO_PIN_1);
            break;
        }
        if (set_gpio_output(line2, 0) < 0) {
            fprintf(stderr, "Error setting GPIO line %d to 0\n", GPIO_PIN_2);
            break;
        }

        // Read GPIO input
        pin1_value = read_gpio_input(line1);
        pin2_value = read_gpio_input(line2);

        // Log data
        log_data(pin1_value, pin2_value);

        // Wait for 5 seconds
        sleep(5);
    }

    // Release GPIO lines and chip
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    running = 0;
    printf("Exiting...\n");
}

// Function to set GPIO output
int set_gpio_output(struct gpiod_line *line, int value)
{
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read GPIO input
int read_gpio_input(struct gpiod_line *line)
{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Function to get current timestamp
void get_timestamp(char *timestamp)
{
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

// Function to log data to standard output
void log_data(int pin1_value, int pin2_value)
