    char timestamp[20];
    get_timestamp(timestamp);

    if (pin1_value == -1 || pin2_value == -1) {
        fprintf(stderr, "%s: Error reading GPIO values\n", timestamp);
    } else {
        printf("%s: GPIO %d: %d, GPIO %d: %d\n", timestamp, GPIO_PIN_1, pin1_value, GPIO_PIN_2, pin2_value);
