#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 22

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MAX_DISTANCE 400.0    // cm
#define MIN_DISTANCE 2.0      // cm
#define TIMEOUT_US 50000       // 50ms timeout

// Global variable for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to trigger the ultrasonic sensor
void triggerSensor()
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance in centimeters
float measureDistance()
{
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    triggerSensor();

    // Wait for echo to start (rising edge)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US)
    {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US)
    {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1.0; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for echo to end (falling edge)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US)
    {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US)
    {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1.0; // Indicate timeout error
    }

    end_tick = gpioTick();

    // Calculate the pulse duration in microseconds
    diff_tick = end_tick - start_tick;

    // Calculate the distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s, and by 2 for one-way distance

    return distance;
}

// Function to validate the distance reading
int validateDistance(float distance)
{
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE)
    {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        return 0; // Invalid
    }
    return 1; // Valid
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate)
    {
        float distance = measureDistance();

        if (distance >= 0) // Check for valid distance reading
        {
            if (validateDistance(distance))
            {
                printf("Distance: %.2f cm\n", distance);
            }
        }
        else
        {
            fprintf(stderr, "Failed to measure distance\n");
        }

        gpioDelay(100); // 0.1 second delay
    }

    // Cleanup and exit
    gpioTerminate();
    fprintf(stderr, "pigpio terminated\n");
    return 0;
}

