    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo end.\n");
            return -1.0; // Indicate timeout error
        }
    }
    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate the distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s, and by 2 for one-way distance

    return distance;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        float distance = measure_distance();

        if (distance > 0) {
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            time(&rawtime);
            timeinfo = localtime(&rawtime);

            char timestamp[80];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Print the distance with timestamp
            printf("%s Distance: %.2f cm\n", timestamp, distance);
        } else {
            fprintf(stderr, "Error: Distance measurement failed.\n");
        }

        // Wait for 0.2 seconds
        gpioDelay(200000); // 200 ms
    }

    // Release GPIO resources before exiting
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for PWM output
#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 22
#define PWM_PIN_4 23

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set PWM duty cycle for a given GPIO pin
int set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 255) {
        fprintf(stderr, "Error: Duty cycle out of range (0-255): %d\n", duty_cycle);
        return -1; // Indicate an error
    }

    if (gpioPWM(gpio_pin, duty_cycle) != 0) {
        fprintf(stderr, "Error: Failed to set PWM for GPIO %d\n", gpio_pin);
        return -1; // Indicate an error
    }

    return 0; // Indicate success
}

// Function to report the current state of the PWM output
void report_state(int gpio_pin, int duty_cycle) {
    printf("GPIO %d: Duty Cycle = %d\n", gpio_pin, duty_cycle);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1; // Exit with an error code
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);

    // Set PWM frequency to 1000 Hz
    gpioSetPWMfrequency(PWM_PIN_1, 1000);
    gpioSetPWMfrequency(PWM_PIN_2, 1000);
    gpioSetPWMfrequency(PWM_PIN_3, 1000);
    gpioSetPWMfrequency(PWM_PIN_4, 1000);

    // Set PWM range to 255
    gpioSetPWMrange(PWM_PIN_1, 255);
    gpioSetPWMrange(PWM_PIN_2, 255);
    gpioSetPWMrange(PWM_PIN_3, 255);
    gpioSetPWMrange(PWM_PIN_4, 255);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    int duty_cycle = 0;
    while (program_running) {
        // Set PWM duty cycle for each GPIO pin
        if (set_pwm_duty_cycle(PWM_PIN_1, duty_cycle) != 0) {
            program_running = 0; // Exit on error
            break;
        }
        if (set_pwm_duty_cycle(PWM_PIN_2, duty_cycle) != 0) {
            program_running = 0; // Exit on error
            break;
        }
        if (set_pwm_duty_cycle(PWM_PIN_3, duty_cycle) != 0) {
            program_running = 0; // Exit on error
            break;
        }
        if (set_pwm_duty_cycle(PWM_PIN_4, duty_cycle) != 0) {
            program_running = 0; // Exit on error
            break;
        }

        // Report the current state
        report_state(PWM_PIN_1, duty_cycle);
        report_state(PWM_PIN_2, duty_cycle);
        report_state(PWM_PIN_3, duty_cycle);
        report_state(PWM_PIN_4, duty_cycle);

        // Increment duty cycle (0-255)
        duty_cycle = (duty_cycle + 1) % 256;

        // Wait for 0.1 seconds
        usleep(100000); // 100000 microseconds = 0.1 seconds
    }

    // Stop PWM output
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_4, 0);

    // Terminate pigpio library
    gpioTerminate();

    fprintf(stderr, "Program terminated.\n");
    return 0; // Exit successfully
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define MQTT_BROKER "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/data"
#define SENSOR_GPIO 4
#define VALID_READING_MIN 0
#define VALID_READING_MAX 1023
#define SAMPLE_INTERVAL_MS 1000

// Global variables
static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function prototypes
int read_sensor();
int validate_reading(int reading);
int publish_reading(int reading);
void signal_handler(int signum);

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, shutting down...\n");
        running = 0;
    }
}

// Reads the sensor value from the GPIO pin
int read_sensor() {
    int reading = gpioRead(SENSOR_GPIO);
    return reading;
}

// Validates the sensor reading
int validate_reading(int reading) {
    if (reading >= VALID_READING_MIN && reading <= VALID_READING_MAX) {
        return 1; // Valid
    } else {
        return 0; // Invalid
    }
}

// Publishes the sensor reading to the MQTT broker
int publish_reading(int reading) {
    char payload[20];
    snprintf(payload, sizeof(payload), "%d", reading);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
        return 0; // Indicate failure
    }
    return 1; // Indicate success
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(SENSOR_GPIO, PI_INPUT);

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new Mosquitto client instance
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        gpioTerminate();
        return 1;
    }

    // Connect to the MQTT broker
    int ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Read sensor value
        int reading = read_sensor();

        // Validate reading
        if (validate_reading(reading)) {
            // Publish reading
            if (!publish_reading(reading)) {
                fprintf(stderr, "Failed to publish reading: %d\n", reading);
            }
        } else {
            fprintf(stderr, "Invalid reading: %d\n", reading);
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Disconnect from MQTT broker
    mosquitto_disconnect(mosq);

    // Destroy Mosquitto client instance
    mosquitto_destroy(mosq);

    // Clean up libmosquitto
    mosquitto_lib_cleanup();

    // Terminate pigpio
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define MQTT_BROKER "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "ads1115/sensor_data"
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define NUM_SENSORS 3
#define READINGS_PER_SENSOR 10
#define ADS1115_ADDR 0x48 // Default I2C address

// ADS1115 Registers
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_REG_LO_THRESH 0x02
#define ADS1115_REG_HI_THRESH 0x03

// Global variables
static volatile int running = 1;
static int spi_handle;
static struct mosquitto *mosq = NULL;

// Structure to hold sensor data
typedef struct {
    int16_t channel0;
    int16_t channel1;
    int16_t channel2;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int init_spi();
int init_mqtt();
int read_ads1115(int channel, int16_t *reading);
int publish_sensor_data(sensor_data_t data);
void signal_handler(int sig);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI interface
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize MQTT client
int init_mqtt() {
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "MQTT initialisation failed\n");
        return -1;
    }

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "MQTT connection failed: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "MQTT loop start failed: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    return 0;
}

// Read data from ADS1115
int read_ads1115(int channel, int16_t *reading) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    int16_t config;

    // Configure the ADS1115 for single-ended readings on the specified channel
    config = 0x4000; // Start single conversion
    config |= (channel << 12); // Set channel
    config |= 0x0080; // Single-shot mode
    config |= 0x0003; // 128 SPS
    config |= 0x0080; // PGA = +/- 4.096V

    tx_buf[0] = (ADS1115_REG_CONFIG >> 8) & 0xFF;
    tx_buf[1] = ADS1115_REG_CONFIG & 0xFF;
    tx_buf[2] = (config >> 8) & 0xFF;
    tx_buf[3] = config & 0xFF;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 7) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Read the conversion result
    *reading = (rx_buf[2] << 8) | rx_buf[3];

    return 0;
}

// Publish sensor data to MQTT broker
int publish_sensor_data(sensor_data_t data) {
    char payload[256];
    snprintf(payload, sizeof(payload), "{\"channel0\":%d,\"channel1\":%d,\"channel2\":%d}", data.channel0, data.channel1, data.channel2);

    int rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "MQTT publish failed: %s\n", mosquitto_strerror(rc));
        return -1;
    }

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (mosq) {
        mosquitto_loop_stop(mosq, false);
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    // Initialize MQTT
    if (init_mqtt() != 0) {
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;
    int i, j;

    // Main loop
    for (i = 0; i < NUM_SENSORS; i++) {
        for (j = 0; j < READINGS_PER_SENSOR; j++) {
            if (!running) break;

            // Read sensor data
            if (read_ads1115(0, &sensor_data.channel0) != 0) {
                fprintf(stderr, "Error reading channel 0\n");
                continue;
            }
            if (read_ads1115(1, &sensor_data.channel1) != 0) {
                fprintf(stderr, "Error reading channel 1\n");
                continue;
            }
            if (read_ads1115(2, &sensor_data.channel2) != 0) {
                fprintf(stderr, "Error reading channel 2\n");
                continue;
            }

            // Publish sensor data
            if (publish_sensor_data(sensor_data) != 0) {
                fprintf(stderr, "Error publishing sensor data\n");
            }

            // Wait for a short period
            usleep(100000); // 100ms
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

