#include <pigpio.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 115200
#define MAX_BUFFER_SIZE 256

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

int setup_uart(const char *device, int baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
    tty.c_iflag &= ~IGNBRK;         // disable break processing
    tty.c_lflag = 0;                // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                // no remapping, no delays
    tty.c_cc[VMIN] = 0;              // read doesn't block
    tty.c_cc[VTIME] = 5;             // 0.5 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // shut off xon/xoff ctrl

    tty.c_cflag |= (CLOCAL | CREAD);   // ignore modem controls, enable reading
    tty.c_cflag &= ~(PARENB | PARODD); // shut off parity
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    cfsetospeed(&tty, baud_rate);
    cfsetispeed(&tty, baud_rate);

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int read_uart(int fd, char *buffer, int max_size) {
    ssize_t bytes_read = read(fd, buffer, max_size - 1);
    if (bytes_read == -1) {
        perror("Error reading from UART");
        return -1;
    } else if (bytes_read > 0) {
        buffer[bytes_read] = '\0';
        return (int)bytes_read;
    } else {
        return 0; // No data read
    }
}

int main() {
    signal(SIGINT, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    uart_fd = setup_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        gpioTerminate();
        return 1;
    }

    char buffer[MAX_BUFFER_SIZE];
    int bytes_read;

    while (program_running) {
        bytes_read = read_uart(uart_fd, buffer, MAX_BUFFER_SIZE);
        if (bytes_read > 0) {
            printf("Received: %s", buffer);
        }
        usleep(100000); // 100ms delay
    }

    close(uart_fd);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define MPU6050_REG_PWR_MGMT_1 0x6B
#define MPU6050_REG_ACCEL_XOUT_H 0x3B
#define MPU6050_REG_GYRO_XOUT_H 0x43

// I2C device file
#define I2C_DEVICE "/dev/i2c-1"

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the MPU6050
int init_mpu6050() {
    // Wake up the MPU6050 (set power management register to 0)
    uint8_t data[2] = {MPU6050_REG_PWR_MGMT_1, 0x00};
    if (write(i2c_fd, data, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read accelerometer and gyroscope data
int read_mpu6050_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t reg = MPU6050_REG_ACCEL_XOUT_H;
    uint8_t buffer[14];

    // Set the register to read from
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    // Read 14 bytes of data (6 accelerometer, 6 gyroscope)
    if (read(i2c_fd, buffer, 14) != 14) {
        perror("Failed to read data from I2C device");
        return -1;
    }

    // Combine high and low bytes for each axis
    *accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);
    *gyro_x = (int16_t)((buffer[8] << 8) | buffer[9]);
    *gyro_y = (int16_t)((buffer[10] << 8) | buffer[11]);
    *gyro_z = (int16_t)((buffer[12] << 8) | buffer[13]);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() < 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

        // Read data from MPU6050
        if (read_mpu6050_data(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Print the data
            printf("Accel: X=%6d, Y=%6d, Z=%6d  Gyro: X=%6d, Y=%6d, Z=%6d\n", accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Failed to read MPU6050 data\n");
        }

        // Wait for 0.1 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 0.1 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Close I2C device (this will never be reached in the infinite loop)
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_ID 0xD0

// Calibration data registers
#define BMP280_REG_CALIB_00 0x88

// Global variables
int i2c_fd;
volatile sig_atomic_t stop_flag = 0;

// Calibration data structure
struct bmp280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
};

struct bmp280_calib_data calib;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    stop_flag = 1;
    printf("\nExiting...\n");
}

// Function to read a single byte from an I2C register
int i2c_read_reg(int fd, uint8_t reg_addr, uint8_t *data) {
    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return 0;
}

// Function to write a single byte to an I2C register
int i2c_write_reg(int fd, uint8_t reg_addr, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg_addr;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to register");
        return -1;
    }
    return 0;
}

// Function to read multiple bytes from I2C registers
int i2c_read_regs(int fd, uint8_t reg_addr, uint8_t *data, int len) {
    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read register values");
        return -1;
    }
    return 0;
}

// Function to initialize the BMP280 sensor
int bmp280_init(int fd) {
    uint8_t id;

    // Check the device ID
    if (i2c_read_reg(fd, BMP280_REG_ID, &id) != 0) {
        fprintf(stderr, "Error reading BMP280 ID\n");
        return -1;
    }

    if (id != 0x58) {
        fprintf(stderr, "Incorrect BMP280 ID: 0x%02X\n", id);
        return -1;
    }

    // Read calibration data
    uint8_t calib_data[26];
    if (i2c_read_regs(fd, BMP280_REG_CALIB_00, calib_data, 26) != 0) {
        fprintf(stderr, "Error reading BMP280 calibration data\n");
        return -1;
    }

    calib.dig_T1 = (uint16_t)calib_data[0] | ((uint16_t)calib_data[1] << 8);
    calib.dig_T2 = (int16_t)calib_data[2] | ((int16_t)calib_data[3] << 8);
    calib.dig_T3 = (int16_t)calib_data[4] | ((int16_t)calib_data[5] << 8);
    calib.dig_P1 = (uint16_t)calib_data[6] | ((uint16_t)calib_data[7] << 8);
    calib.dig_P2 = (int16_t)calib_data[8] | ((int16_t)calib_data[9] << 8);
    calib.dig_P3 = (int16_t)calib_data[10] | ((int16_t)calib_data[11] << 8);
    calib.dig_P4 = (int16_t)calib_data[12] | ((int16_t)calib_data[13] << 8);
    calib.dig_P5 = (int16_t)calib_data[14] | ((int16_t)calib_data[15] << 8);
    calib.dig_P6 = (int16_t)calib_data[16] | ((int16_t)calib_data[17] << 8);
    calib.dig_P7 = (int16_t)calib_data[18] | ((int16_t)calib_data[19] << 8);
    calib.dig_P8 = (int16_t)calib_data[20] | ((int16_t)calib_data[21] << 8);
    calib.dig_P9 = (int16_t)calib_data[22] | ((int16_t)calib_data[23] << 8);

    // Set sensor mode (forced mode, oversampling x16)
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, 0x3F) != 0) { // Oversampling x16, forced mode
        fprintf(stderr, "Error writing to CTRL_MEAS register\n");
        return -1;
    }

    // Set configuration (t_sb = 0.5ms, filter = off)
    if (i2c_write_reg(fd, BMP280_REG_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error writing to CONFIG register\n");
        return -1;
    }

    return 0;
}

// Function to read temperature and pressure data from the BMP280
int bmp280_read_data(int fd, float *temperature, float *pressure) {
    uint8_t data[6];
    int32_t raw_temp, raw_press;
    int32_t var1, var2, T, p;

    // Read raw temperature and pressure data
    if (i2c_read_regs(fd, BMP280_REG_PRESS_MSB, data, 6) != 0) {
        fprintf(stderr, "Error reading temperature and pressure data\n");
        return -1;
    }

    raw_press = (int32_t)data[0] << 12 | (int32_t)data[1] << 4 | (int32_t)data[2] >> 4;
    raw_temp = (int32_t)data[3] << 12 | (int32_t)data[4] << 4 | (int32_t)data[5] >> 4;

    // Temperature compensation
    var1 = ((((raw_temp >> 3) - ((int32_t)calib.dig_T1 << 1))) * ((int32_t)calib.dig_T2)) >> 11;
    var2 = (((((raw_temp >> 4) - ((int32_t)calib.dig_T1)) * ((raw_temp >> 4) - ((int32_t)calib.dig_T1))) >> 12) * ((int32_t)calib.dig_T3)) >> 14;
    T = var1 + var2;
    *temperature = (float)((T * 5 + 128) >> 8) / 100.0;

    // Pressure compensation
    var1 = ((int32_t)T) - 128000;
    var2 = var1 * var1 * (int32_t)calib.dig_P6;
    var2 = var2 + ((var1 * (int32_t)calib.dig_P5) << 17);
    var2 = var2 + (((int32_t)calib.dig_P4) << 35);
    var1 = ((var1 * var1 * (int32_t)calib.dig_P3) >> 8) + ((var1 * (int32_t)calib.dig_P2) << 12);
    var1 = (((((int32_t)1) << 47) + var1)) * ((int32_t)calib.dig_P1) >> 33;

    if (var1 == 0) {
        return 0; // Avoid exception caused by division by zero
    }
    p = 1048576 - raw_press;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int32_t)calib.dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int32_t)calib.dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int32_t)calib.dig_P7) << 4);
    *pressure = (float)p / 25600.0;

    return 0;
}

int main() {
    const char *i2c_device = "/dev/i2c-1"; // I2C device file
    int retries = 3; // Number of retries for I2C communication
    int delay_ms = 100; // Delay between retries in milliseconds

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize BMP280 sensor
    if (bmp280_init(i2c_fd) != 0) {
        fprintf(stderr, "BMP280 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!stop_flag) {
        float temperature, pressure;
        int retry_count = 0;

        // Read data with retries
        while (retry_count < retries) {
            if (bmp280_read_data(i2c_fd, &temperature, &pressure) == 0) {
                // Print temperature and pressure
                printf("Temperature: %.2f \u00b0C, Pressure: %.2f Pa\n", temperature, pressure);
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "BMP280 read failed, retry %d/%d\n", retry_count + 1, retries);
                retry_count++;
                usleep(delay_ms * 1000); // Wait before retrying
            }
        }

        if (retry_count == retries) {
            fprintf(stderr, "BMP280 read failed after %d retries\n", retries);
        }

        sleep(5); // Wait 5 seconds
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
