#define PWM_GPIO 4
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 4 as output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Set PWM duty cycle to 50%
    gpioPWM(PWM_GPIO, PWM_RANGE / 2);

    // Report PWM state
    printf("PWM on GPIO %d, frequency %d Hz, range %d, duty cycle %.2f%%\n",
           PWM_GPIO, PWM_FREQUENCY, PWM_RANGE, (float)(PWM_RANGE / 2) / PWM_RANGE * 100);

    // Wait for a short period
    gpioDelay(1000000); // 1 second

    // Clean up and exit
    gpioPWM(PWM_GPIO, 0); // Stop PWM
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_5 5
#define GPIO_6 6
#define GPIO_13 13

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line5, *line6, *line13;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line5) {
        gpiod_line_release(line5);
    }
    if (line6) {
        gpiod_line_release(line6);
    }
    if (line13) {
        gpiod_line_release(line13);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    int value;
    struct timespec delay;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line5 = gpiod_chip_get_line(chip, GPIO_5);
    line6 = gpiod_chip_get_line(chip, GPIO_6);
    line13 = gpiod_chip_get_line(chip, GPIO_13);

    if (!line5 || !line6 || !line13) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line5, "gpio5_output", 0) < 0) {
        perror("Error requesting GPIO line 5 for output");
        gpiod_line_release(line5);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(line6, "gpio6_output", 0) < 0) {
        perror("Error requesting GPIO line 6 for output");
        gpiod_line_release(line6);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(line13, "gpio13_output", 0) < 0) {
        perror("Error requesting GPIO line 13 for output");
        gpiod_line_release(line13);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    for (int i = 0; i < 10; i++) {
        // Set GPIO 5 to HIGH
        if (gpiod_line_set_value(line5, 1) < 0) {
            perror("Error setting GPIO line 5 value");
            gpiod_line_release(line5);
            gpiod_chip_close(chip);
            return 1;
        }
        printf("GPIO %d: HIGH\n", GPIO_5);

        // Set GPIO 6 to LOW
        if (gpiod_line_set_value(line6, 0) < 0) {
            perror("Error setting GPIO line 6 value");
            gpiod_line_release(line6);
            gpiod_chip_close(chip);
            return 1;
        }
        printf("GPIO %d: LOW\n", GPIO_6);

        // Set GPIO 13 to HIGH
        if (gpiod_line_set_value(line13, 1) < 0) {
            perror("Error setting GPIO line 13 value");
            gpiod_line_release(line13);
            gpiod_chip_close(chip);
            return 1;
        }
        printf("GPIO %d: HIGH\n", GPIO_13);

        // Delay for 1 second
        delay.tv_sec = 1;
        delay.tv_nsec = 0;
        nanosleep(&delay, NULL);

        // Set GPIO 5 to LOW
        if (gpiod_line_set_value(line5, 0) < 0) {
            perror("Error setting GPIO line 5 value");
            gpiod_line_release(line5);
            gpiod_chip_close(chip);
            return 1;
        }
        printf("GPIO %d: LOW\n", GPIO_5);

        // Set GPIO 6 to HIGH
        if (gpiod_line_set_value(line6, 1) < 0) {
            perror("Error setting GPIO line 6 value");
            gpiod_line_release(line6);
            gpiod_chip_close(chip);
            return 1;
        }
        printf("GPIO %d: HIGH\n", GPIO_6);

        // Set GPIO 13 to LOW
        if (gpiod_line_set_value(line13, 0) < 0) {
            perror("Error setting GPIO line 13 value");
            gpiod_line_release(line13);
            gpiod_chip_close(chip);
            return 1;
        }
        printf("GPIO %d: LOW\n", GPIO_13);

        // Delay for 1 second
        delay.tv_sec = 1;
        delay.tv_nsec = 0;
        nanosleep(&delay, NULL);
    }

    // Cleanup
    gpiod_line_release(line5);
    gpiod_line_release(line6);
    gpiod_line_release(line13);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define MQTT_BROKER "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/data"
#define GPIO_PIN 17
#define SAMPLE_INTERVAL_MS 1000

// Global variables
static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function prototypes
int init_gpio();
int init_mqtt();
int publish_sensor_data(int sensor_value);
void signal_handler(int signum);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, exiting gracefully.\n");
        running = 0;
    }
}

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    return 0;
}

// Initialize MQTT
int init_mqtt() {
    mosquitto_lib_init();

    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        return -1;
    }

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: Could not connect to MQTT broker: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    return 0;
}

// Publish sensor data to MQTT broker
int publish_sensor_data(int sensor_value) {
    char payload[20];
    snprintf(payload, sizeof(payload), "%d", sensor_value);

    int rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: Could not publish message: %s\n", mosquitto_strerror(rc));
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");

    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();

    gpioTerminate();
}

int main() {
    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Initialize MQTT
    if (init_mqtt() != 0) {
        cleanup();
        return 1;
    }

    printf("Publishing sensor data to %s:%d/%s every %d ms...\n", MQTT_BROKER, MQTT_PORT, MQTT_TOPIC, SAMPLE_INTERVAL_MS);

    // Main loop
    while (running) {
        // Read sensor value (assuming digital sensor, so just read the GPIO pin)
        int sensor_value = gpioRead(GPIO_PIN);

        // Publish sensor data
        if (publish_sensor_data(sensor_value) != 0) {
            fprintf(stderr, "Error publishing sensor data, retrying...\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

