#define PWM_DUTY_CYCLE 128

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set PWM duty cycle for a given GPIO pin
int set_pwm(int gpio_pin, int duty_cycle) {
    int result = gpioPWM(gpio_pin, duty_cycle);
    if (result != 0) {
        fprintf(stderr, "Error setting PWM for GPIO %d: %d\n", gpio_pin, result);
        return -1;
    }
    return 0;
}

// Function to report the state of a GPIO pin
void report_state(int gpio_pin, int duty_cycle) {
    printf("GPIO %d: PWM Duty Cycle = %d\n", gpio_pin, duty_cycle);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);
    gpioSetMode(PWM_PIN_5, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_4, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_5, PWM_FREQUENCY);

    // Set PWM duty cycle for each GPIO pin
    if (set_pwm(PWM_PIN_1, PWM_DUTY_CYCLE) != 0) {
        gpioTerminate();
        return 1;
    }
    if (set_pwm(PWM_PIN_2, PWM_DUTY_CYCLE) != 0) {
        gpioTerminate();
        return 1;
    }
    if (set_pwm(PWM_PIN_3, PWM_DUTY_CYCLE) != 0) {
        gpioTerminate();
        return 1;
    }
    if (set_pwm(PWM_PIN_4, PWM_DUTY_CYCLE) != 0) {
        gpioTerminate();
        return 1;
    }
    if (set_pwm(PWM_PIN_5, PWM_DUTY_CYCLE) != 0) {
        gpioTerminate();
        return 1;
    }

    // Report the state of each GPIO pin
    report_state(PWM_PIN_1, PWM_DUTY_CYCLE);
    report_state(PWM_PIN_2, PWM_DUTY_CYCLE);
    report_state(PWM_PIN_3, PWM_DUTY_CYCLE);
    report_state(PWM_PIN_4, PWM_DUTY_CYCLE);
    report_state(PWM_PIN_5, PWM_DUTY_CYCLE);

