    gpioDelay(1000000); // 1 second

    // Stop PWM signals
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_4, 0);
    gpioPWM(PWM_PIN_5, 0);

