#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PWM_PIN 17
#define DIR_PIN 22
#define ENABLE_PIN 27

// Define PWM frequency and duty cycle
#define PWM_FREQUENCY 1000
#define PWM_DUTYCYCLE 128

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stdout, "Signal received, exiting gracefully...\n");
}

// Function to set the motor direction
void set_motor_direction(int direction) {
    gpioWrite(DIR_PIN, direction);
}

// Function to set the motor enable state
void set_motor_enable(int enable) {
    gpioWrite(ENABLE_PIN, !enable); // Invert the enable signal
}

// Function to set the PWM duty cycle
void set_pwm_dutycycle(int dutycycle) {
    gpioPWM(PWM_PIN, dutycycle);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetMode(DIR_PIN, PI_OUTPUT);
    gpioSetMode(ENABLE_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY);

    // Set PWM range (optional, but recommended for accuracy)
    gpioSetPWMrange(PWM_PIN, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Set motor direction (forward)
        set_motor_direction(1);

        // Set motor enable (enable)
        set_motor_enable(1);

        // Set PWM duty cycle
        set_pwm_dutycycle(PWM_DUTYCYCLE);

        // Report state
        fprintf(stdout, "Motor: Forward, Enable: Enabled, Duty Cycle: %d\n", PWM_DUTYCYCLE);

        // Wait for 0.05 seconds
        gpioDelay(50000); // 50000 microseconds = 0.05 seconds

        // Set motor direction (reverse)
        set_motor_direction(0);

        // Set motor enable (enable)
        set_motor_enable(1);

        // Set PWM duty cycle
        set_pwm_dutycycle(PWM_DUTYCYCLE);

        // Report state
        fprintf(stdout, "Motor: Reverse, Enable: Enabled, Duty Cycle: %d\n", PWM_DUTYCYCLE);

        // Wait for 0.05 seconds
        gpioDelay(50000); // 50000 microseconds = 0.05 seconds
    }

    // Disable the motor before exiting
    set_motor_enable(0);

    // Terminate pigpio library
    gpioTerminate();

    fprintf(stdout, "Program terminated successfully.\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FORMAT V4L2_PIX_FMT_JPEG

// Structure to hold camera device information
typedef struct {
    int fd;
    void *buffer;
    struct v4l2_buffer buf;
} camera_device_t;

// Global variable to track if the program should exit
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the camera device
int init_camera(camera_device_t *camera) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;

    // Open the device
    camera->fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (camera->fd < 0) {
        perror("Error opening device");
        return -1;
    }

    // Check device capabilities
    if (ioctl(camera->fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(camera->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        close(camera->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        close(camera->fd);
        return -1;
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = IMAGE_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(camera->fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(camera->fd);
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(camera->fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(camera->fd);
        return -1;
    }

    // Query buffer
    memset(&camera->buf, 0, sizeof(camera->buf));
    camera->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    camera->buf.memory = V4L2_MEMORY_MMAP;
    camera->buf.index = 0;

    if (ioctl(camera->fd, VIDIOC_QUERYBUF, &camera->buf) < 0) {
        perror("Error querying buffer");
        close(camera->fd);
        return -1;
    }

    // Map the buffer
    camera->buffer = mmap(NULL, camera->buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, camera->fd, camera->buf.m.offset);
    if (camera->buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(camera->fd);
        return -1;
    }

    return 0;
}

// Function to capture an image
int capture_image(camera_device_t *camera) {
    struct v4l2_buffer buf;
    struct timespec ts;
    char filename[64];
    FILE *fp;

    // Queue the buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(camera->fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(camera->fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        return -1;
    }

    // Dequeue the buffer
    if (ioctl(camera->fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        ioctl(camera->fd, VIDIOC_STREAMOFF, &type);
        return -1;
    }

    // Get timestamp for filename
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return -1;
    }
    snprintf(filename, sizeof(filename), "image_%ld.jpg", ts.tv_sec);

    // Write image to file
    fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        ioctl(camera->fd, VIDIOC_STREAMOFF, &type);
        return -1;
    }

    fwrite(camera->buffer, 1, buf.bytesused, fp);
    fclose(fp);

    // Stop streaming
    if (ioctl(camera->fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        return -1;
    }

    return 0;
}

// Function to cleanup the camera device
void cleanup_camera(camera_device_t *camera) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (camera->fd > 0) {
        ioctl(camera->fd, VIDIOC_STREAMOFF, &type);
        if (camera->buffer != MAP_FAILED && camera->buffer != NULL) {
            munmap(camera->buffer, camera->buf.length);
        }
        close(camera->fd);
    }
}

int main() {
    camera_device_t camera;
    struct sigaction sa;

    // Set up signal handler for Ctrl+C
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error setting up signal handler");
        return 1;
    }

    // Initialize the camera
    if (init_camera(&camera) < 0) {
        fprintf(stderr, "Failed to initialize camera. Exiting.\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        if (capture_image(&camera) < 0) {
            fprintf(stderr, "Failed to capture image. Continuing.\n");
        }
        sleep(1);
    }

    // Cleanup the camera
    cleanup_camera(&camera);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FORMAT V4L2_PIX_FMT_JPEG
#define IMAGE_FILE "captured_image.jpg"

static int fd = -1;
static void *buffer = NULL;
static unsigned int buffer_size = 0;
static struct v4l2_buffer buf;

// Signal handler for graceful exit
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    if (buffer != NULL) {
        munmap(buffer, buffer_size);
    }
    if (fd != -1) {
        close(fd);
    }
    exit(0);
}

// Function to initialize the camera device
int init_device() {
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        fd = -1;
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        fd = -1;
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        fd = -1;
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = IMAGE_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        fd = -1;
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        fd = -1;
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        close(fd);
        fd = -1;
        return -1;
    }

    buffer_size = buf.length;
    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(fd);
        fd = -1;
        return -1;
    }

    return 0;
}

// Function to capture an image
int capture_image() {
    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        return -1;
    }

    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("Error during select");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        return -1;
    }

    return 0;
}

// Function to save the image to a file
int save_image() {
    FILE *fp = fopen(IMAGE_FILE, "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        return -1;
    }

    size_t bytes_written = fwrite(buffer, 1, buffer_size, fp);
    if (bytes_written != buffer_size) {
        fprintf(stderr, "Error writing to file: wrote %zu bytes, expected %u\n", bytes_written, buffer_size);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    printf("Image saved to %s\n", IMAGE_FILE);
    return 0;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    if (init_device() < 0) {
        fprintf(stderr, "Device initialization failed. Exiting.\n");
        return 1;
    }

    if (capture_image() < 0) {
        fprintf(stderr, "Image capture failed. Exiting.\n");
        munmap(buffer, buffer_size);
        close(fd);
        return 1;
    }

    if (save_image() < 0) {
        fprintf(stderr, "Image saving failed. Exiting.\n");
        munmap(buffer, buffer_size);
        close(fd);
        return 1;
    }

    // Cleanup
    munmap(buffer, buffer_size);
    close(fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line1, *line2;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    int i, ret;
    struct timespec delay;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("Error getting GPIO line 1");
        gpiod_chip_close(chip);
        return 1;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("Error getting GPIO line 2");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        return 1;
    }

    // Request GPIO lines as output
    ret = gpiod_line_request_output(line1, "gpio_control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 1 as output");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        return 1;
    }

    ret = gpiod_line_request_output(line2, "gpio_control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 2 as output");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        return 1;
    }

    // Main loop
    while (1) {
        // Toggle GPIO 2
        ret = gpiod_line_set_value(line2, 1);
        if (ret < 0) {
            perror("Error setting GPIO line 2 value");
            break;
        }
        printf("GPIO %d: %d\n", GPIO_PIN_2, 1);

        // Toggle GPIO 3
        ret = gpiod_line_set_value(line1, 0);
        if (ret < 0) {
            perror("Error setting GPIO line 1 value");
            break;
        }
        printf("GPIO %d: %d\n", GPIO_PIN_1, 0);

        // Wait for 0.5 seconds
        delay.tv_sec = 0;
        delay.tv_nsec = 500000000; // 500 milliseconds
        nanosleep(&delay, NULL);
    }

    // Cleanup (in case of error)
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return 1;
}

