#define PWM_PIN 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    signal(SIGINT, signal_handler);

    int duty_cycle = 0;
    int increment = 100;

    while (!terminate) {
        gpioPWM(PWM_PIN, duty_cycle);
        printf("PWM on GPIO %d set to %d\n", PWM_PIN, duty_cycle);
        fflush(stdout);
        gpioDelay(100000); // 100ms

        duty_cycle += increment;
        if (duty_cycle > PWM_RANGE) {
            duty_cycle = PWM_RANGE;
            increment = -100;
        } else if (duty_cycle < 0) {
            duty_cycle = 0;
            increment = 100;
        }
    }

    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate();
    printf("PWM stopped and pigpio terminated\n");
    return 0;
}

