#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int valid;
} DHT22Data;

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", sig);
}

// Function to read DHT22 data using gpiod
DHT22Data read_dht22_data() {
    DHT22Data data = {0.0, 0.0, 0};
    int retries = 0;
    int i;
    unsigned int raw_data[5] = {0};

    while (retries < MAX_RETRIES) {
        // Request data
        if (gpiod_line_set_value(line, 0) < 0) {
            perror("Failed to set line low");
            retries++;
            usleep(100000); // Wait 100ms before retrying
            continue;
        }
        usleep(1000); // Wait 1ms

        if (gpiod_line_set_value(line, 1) < 0) {
            perror("Failed to set line high");
            retries++;
            usleep(100000); // Wait 100ms before retrying
            continue;
        }
        usleep(30); // Wait 30us

        // Read data
        for (i = 0; i < 40; i++) {
            // Wait for line to go low
            int timeout = 0;
            while (gpiod_line_get_value(line) == 1 && timeout < 100) {
                usleep(1); // Wait 1us
                timeout++;
            }
            if (timeout >= 100) {
                fprintf(stderr, "Timeout waiting for line to go low\n");
                retries++;
                goto retry;
            }

            // Wait for line to go high
            timeout = 0;
            while (gpiod_line_get_value(line) == 0 && timeout < 100) {
                usleep(1); // Wait 1us
                timeout++;
            }
            if (timeout >= 100) {
                fprintf(stderr, "Timeout waiting for line to go high\n");
                retries++;
                goto retry;
            }

            // Determine if bit is 0 or 1 based on duration
            if (timeout > 30) {
                raw_data[i / 8] |= (1 << (7 - (i % 8)));
            }
        }

        // Validate checksum
        if ((raw_data[0] + raw_data[1] + raw_data[2] + raw_data[3]) & 0xFF != raw_data[4]) {
            fprintf(stderr, "Checksum error\n");
            retries++;
            goto retry;
        }

        // Convert data to temperature and humidity
        data.humidity = (float)((raw_data[0] << 8) | raw_data[1]) / 10.0;
        data.temperature = (float)(((raw_data[2] & 0x7F) << 8) | raw_data[3]) / 10.0;
        if (raw_data[2] & 0x80) {
            data.temperature *= -1.0;
        }

        // Validate data
        if (data.temperature < -40.0 || data.temperature > 80.0 || data.humidity < 0.0 || data.humidity > 100.0) {
            fprintf(stderr, "Invalid sensor data\n");
            retries++;
            goto retry;
        }

        data.valid = 1;
        return data;

        retry:
        usleep(100000); // Wait 100ms before retrying
    }

    fprintf(stderr, "Failed to read DHT22 data after %d retries\n", MAX_RETRIES);
    return data; // Return invalid data
}

int main() {
    int ret;
    DHT22Data dht22_data;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, DHT22_GPIO);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request line for input
    ret = gpiod_line_request_input(line, "dht22_reader");
    if (ret < 0) {
        perror("Failed to request GPIO line for input");
        gpiod_chip_close(chip);
        return 1;
    }

    // Read DHT22 data
    dht22_data = read_dht22_data();

    // Print data
    if (dht22_data.valid) {
        printf("Temperature: %.1f C, Humidity: %.1f %%\n", dht22_data.temperature, dht22_data.humidity);
    } else {
        printf("Failed to read DHT22 data\n");
    }

    // Release GPIO line and chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

