    line17 = gpiod_chip_get_line(chip, GPIO_17);
    line23 = gpiod_chip_get_line(chip, GPIO_23);
    line24 = gpiod_chip_get_line(chip, GPIO_24);
    line25 = gpiod_chip_get_line(chip, GPIO_25);

    if (!line17 || !line23 || !line24 || !line25) {
        fprintf(stderr, "Error getting GPIO line\n");
        cleanup_gpio();
        return 1;
    }

    // Request GPIO lines as output
    if (gpiod_line_request_output(line17, "gpio_test", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output\n");
        cleanup_gpio();
        return 1;
    }
    if (gpiod_line_request_output(line23, "gpio_test", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output\n");
        cleanup_gpio();
        return 1;
    }
    if (gpiod_line_request_output(line24, "gpio_test", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output\n");
        cleanup_gpio();
        return 1;
    }
    if (gpiod_line_request_output(line25, "gpio_test", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output\n");
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO outputs
        if (set_gpio_output(line17, 1) < 0) {
            fprintf(stderr, "Error setting GPIO output\n");
            cleanup_gpio();
            return 1;
        }
        if (set_gpio_output(line23, 0) < 0) {
            fprintf(stderr, "Error setting GPIO output\n");
            cleanup_gpio();
            return 1;
        }
        if (set_gpio_output(line24, 1) < 0) {
            fprintf(stderr, "Error setting GPIO output\n");
            cleanup_gpio();
            return 1;
        }
        if (set_gpio_output(line25, 0) < 0) {
            fprintf(stderr, "Error setting GPIO output\n");
            cleanup_gpio();
            return 1;
        }

        // Report GPIO state
        report_gpio_state(GPIO_17, get_gpio_input(line17));
        report_gpio_state(GPIO_23, get_gpio_input(line23));
        report_gpio_state(GPIO_24, get_gpio_input(line24));
        report_gpio_state(GPIO_25, get_gpio_input(line25));

        // Wait for 10 seconds
        sleep(10);
    }

    return 0;
}

// Signal handler function
void signal_handler(int sig)
{
    printf("Caught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Function to set GPIO output
int set_gpio_output(struct gpiod_line *line, int value)
{
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %d\n", ret);
        return -1;
    }
    return 0;
}

// Function to get GPIO input
int get_gpio_input(struct gpiod_line *line)
{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error getting GPIO value: %d\n", value);
        return -1;
    }
    return value;
}

// Function to report GPIO state
void report_gpio_state(int gpio, int value)
{
    printf("GPIO %d: %d\n", gpio, value);
}

// Function to cleanup GPIO resources
void cleanup_gpio()
{
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line23) {
        gpiod_line_release(line23);
    }
    if (line24) {
        gpiod_line_release(line24);
    }
    if (line25) {
        gpiod_line_release(line25);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define MQTT_BROKER "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/mcp3008"
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define NUM_SENSORS 3

// Global variables
static volatile int running = 1;
static int spi_handle;
static struct mosquitto *mosq = NULL;

// Function prototypes
int read_mcp3008(int channel);
int publish_sensor_data(int sensor_id, int value);
void signal_handler(int signum);

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, shutting down...\n");
        running = 0;
    }
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to publish sensor data to MQTT broker
int publish_sensor_data(int sensor_id, int value) {
    char topic[100];
    char payload[50];

    // Construct topic string
    snprintf(topic, sizeof(topic), "%s/sensor%d", MQTT_TOPIC, sensor_id);

    // Construct payload string
    snprintf(payload, sizeof(payload), "%d", value);

    // Publish message
    int ret = mosquitto_publish(mosq, NULL, topic, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Channel 0, 1MHz, default flags
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Connect to MQTT broker
    int ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: Could not connect to MQTT broker: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int adc_value = read_mcp3008(i);
            if (adc_value >= 0) {
                if (publish_sensor_data(i, adc_value) != 0) {
                    fprintf(stderr, "Error: Failed to publish sensor data for sensor %d\n", i);
                }
            } else {
                fprintf(stderr, "Error: Failed to read ADC value for sensor %d\n", i);
            }
        }

        sleep(1); // Publish data every 1 second
    }

    // Cleanup
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 3 / 2) // YUV420
#define OUTPUT_FILE "captured_image.raw"

int main() {
    int fd;
    void *buffer;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    // Open the device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return 1;
    }

    // Check device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        close(fd);
        return 1;
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV; // YUV422
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return 1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return 1;
    }

    // Map the buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        close(fd);
        return 1;
    }

    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(fd);
        return 1;
    }

    // Queue the buffer
    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    // Dequeue the buffer
    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    // Save the image to a file
    FILE *fp = fopen(OUTPUT_FILE, "wb");
    if (fp == NULL) {
        perror("Error opening output file");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    if (fwrite(buffer, 1, buf.bytesused, fp) != buf.bytesused) {
        perror("Error writing to output file");
        fclose(fp);
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    fclose(fp);

    // Stop streaming
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
    }

    // Unmap the buffer
    if (munmap(buffer, buf.length) < 0) {
        perror("Error unmapping buffer");
    }

    // Close the device
    close(fd);

    printf("Image captured and saved to %s\n", OUTPUT_FILE);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for PWM output
#define PWM_PIN_1 4
#define PWM_PIN_2 5
#define PWM_PIN_3 6
#define PWM_PIN_4 7
#define PWM_PIN_5 8
#define PWM_PIN_6 9

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioPWM(PWM_PIN_1, 0); // Stop PWM on pin 4
    gpioPWM(PWM_PIN_2, 0); // Stop PWM on pin 5
    gpioPWM(PWM_PIN_3, 0); // Stop PWM on pin 6
    gpioPWM(PWM_PIN_4, 0); // Stop PWM on pin 7
    gpioPWM(PWM_PIN_5, 0); // Stop PWM on pin 8
    gpioPWM(PWM_PIN_6, 0); // Stop PWM on pin 9
    gpioTerminate(); // Terminate pigpio
    exit(0); // Exit program
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);
    gpioSetMode(PWM_PIN_5, PI_OUTPUT);
    gpioSetMode(PWM_PIN_6, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(PWM_PIN_1, 255);
    gpioSetPWMrange(PWM_PIN_2, 255);
    gpioSetPWMrange(PWM_PIN_3, 255);
    gpioSetPWMrange(PWM_PIN_4, 255);
    gpioSetPWMrange(PWM_PIN_5, 255);
    gpioSetPWMrange(PWM_PIN_6, 255);

    // Set PWM frequency (e.g., 1000 Hz)
    gpioSetPWMfrequency(PWM_PIN_1, 1000);
    gpioSetPWMfrequency(PWM_PIN_2, 1000);
    gpioSetPWMfrequency(PWM_PIN_3, 1000);
    gpioSetPWMfrequency(PWM_PIN_4, 1000);
    gpioSetPWMfrequency(PWM_PIN_5, 1000);
    gpioSetPWMfrequency(PWM_PIN_6, 1000);

    // Set PWM duty cycle for each pin (example values)
    gpioPWM(PWM_PIN_1, 128); // Pin 4, 50% duty cycle
    gpioPWM(PWM_PIN_2, 192); // Pin 5, 75% duty cycle
    gpioPWM(PWM_PIN_3, 64);  // Pin 6, 25% duty cycle
    gpioPWM(PWM_PIN_4, 255); // Pin 7, 100% duty cycle
    gpioPWM(PWM_PIN_5, 0);   // Pin 8, 0% duty cycle
    gpioPWM(PWM_PIN_6, 127); // Pin 9, 50% duty cycle

    // Report PWM state
    printf("PWM state:\n");
    printf("  Pin %d: %d\n", PWM_PIN_1, gpioGetPWMdutycycle(PWM_PIN_1));
    printf("  Pin %d: %d\n", PWM_PIN_2, gpioGetPWMdutycycle(PWM_PIN_2));
    printf("  Pin %d: %d\n", PWM_PIN_3, gpioGetPWMdutycycle(PWM_PIN_3));
    printf("  Pin %d: %d\n", PWM_PIN_4, gpioGetPWMdutycycle(PWM_PIN_4));
    printf("  Pin %d: %d\n", PWM_PIN_5, gpioGetPWMdutycycle(PWM_PIN_5));
    printf("  Pin %d: %d\n", PWM_PIN_6, gpioGetPWMdutycycle(PWM_PIN_6));

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Keep the program running until a signal is received
    while (1) {
        gpioDelay(1000); // Wait for 1 second
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN_17 17
#define GPIO_PIN_18 18
#define NUM_CYCLES 3

struct gpiod_chip *chip;
struct gpiod_line *line_17, *line_18;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    if (line_17) {
        gpiod_line_release(line_17);
    }
    if (line_18) {
        gpiod_line_release(line_18);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    int i, ret;
    int value;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    // Get GPIO lines
    line_17 = gpiod_chip_get_line(chip, GPIO_PIN_17);
    if (!line_17) {
        perror("gpiod_chip_get_line (17)");
        gpiod_chip_close(chip);
        return 1;
    }

    line_18 = gpiod_chip_get_line(chip, GPIO_PIN_18);
    if (!line_18) {
        perror("gpiod_chip_get_line (18)");
        gpiod_chip_close(chip);
        gpiod_line_release(line_17);
        return 1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line_17, "gpio_test", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (17)");
        gpiod_chip_close(chip);
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        return 1;
    }

    ret = gpiod_line_request_output(line_18, "gpio_test", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (18)");
        gpiod_chip_close(chip);
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        return 1;
    }

    // Main loop
    for (i = 0; i < NUM_CYCLES; i++) {
        // Set GPIO 17 to HIGH
        ret = gpiod_line_set_value(line_17, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (17)");
            break;
        }
        printf("GPIO 17: HIGH\n");
        sleep(1);

        // Set GPIO 18 to LOW
        ret = gpiod_line_set_value(line_18, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (18)");
            break;
        }
        printf("GPIO 18: LOW\n");
        sleep(1);

        // Set GPIO 17 to LOW
        ret = gpiod_line_set_value(line_17, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (17)");
            break;
        }
        printf("GPIO 17: LOW\n");
        sleep(1);

        // Set GPIO 18 to HIGH
        ret = gpiod_line_set_value(line_18, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (18)");
            break;
        }
        printf("GPIO 18: HIGH\n");
        sleep(1);
    }

    // Cleanup
    gpiod_line_release(line_17);
    gpiod_line_release(line_18);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define DELAY_SECONDS 5

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int ret;
    int i;

    /* Register signal handler for SIGINT (Ctrl+C) */
    signal(SIGINT, signal_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    /* Request GPIO line for output */
    ret = gpiod_line_request_output(line, "gpio-test", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    /* Main loop */
    while (!terminate) {
        /* Toggle GPIO state */
        for (i = 0; i < 2; i++) {
            ret = gpiod_line_set_value(line, i);
            if (ret < 0) {
                fprintf(stderr, "Error setting GPIO value: %s\n", strerror(errno));
                goto cleanup;
            }
            printf("GPIO %d set to %d\n", GPIO_PIN, i);
            sleep(DELAY_SECONDS);
        }
    }

cleanup:
    /* Release GPIO line */
