#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define PCF8574_ADDR 0x27

// Global variable to store the I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a byte to the PCF8574
int pcf8574_write(int fd, uint8_t value) {
    if (write(fd, &value, 1) != 1) {
        perror("Failed to write to PCF8574");
        return -1;
    }
    return 0;
}

int main() {
    // Register the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Main loop to display readings
    while (1) {
        // Get the current time
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);

        // Extract the hours, minutes, and seconds
        int hours = timeinfo->tm_hour;
        int minutes = timeinfo->tm_min;
        int seconds = timeinfo->tm_sec;

        // Display the time on the PCF8574
        uint8_t display_value = (hours * 100) + (minutes * 10) + seconds;

        if (pcf8574_write(i2c_fd, display_value) != 0) {
            fprintf(stderr, "Failed to write display value. Exiting.\n");
            close(i2c_fd);
            return 1;
        }

        printf("Displayed: %03d\n", display_value);

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    // The program should never reach here due to the infinite loop
    return 0;
}

