#define PWM_PIN_3 11
#define PWM_PIN_4 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set PWM duty cycle for a given GPIO pin
int set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 255) {
        fprintf(stderr, "Error: Duty cycle out of range (0-255): %d\n", duty_cycle);
        return -1; // Indicate an error
    }

    gpioPWM(gpio_pin, duty_cycle);
    return 0; // Indicate success
}

// Function to report the state of all GPIO pins
void report_state() {
    printf("PWM_PIN_1: %d, PWM_PIN_2: %d, PWM_PIN_3: %d, PWM_PIN_4: %d\n",
           gpioGetPWMdutycycle(PWM_PIN_1),
           gpioGetPWMdutycycle(PWM_PIN_2),
           gpioGetPWMdutycycle(PWM_PIN_3),
           gpioGetPWMdutycycle(PWM_PIN_4));
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1; // Indicate an error
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);

    // Main loop
    while (program_running) {
        // Set PWM duty cycles for each GPIO pin
        if (set_pwm_duty_cycle(PWM_PIN_1, 128) != 0) {
            program_running = 0; // Exit on error
            break;
        }
        if (set_pwm_duty_cycle(PWM_PIN_2, 64) != 0) {
            program_running = 0; // Exit on error
            break;
        }
        if (set_pwm_duty_cycle(PWM_PIN_3, 192) != 0) {
            program_running = 0; // Exit on error
            break;
        }
        if (set_pwm_duty_cycle(PWM_PIN_4, 100) != 0) {
            program_running = 0; // Exit on error
            break;
        }

        // Report the state
        report_state();

        // Wait for 1 second
        sleep(1);
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FORMAT V4L2_PIX_FMT_JPEG

// Structure to hold camera device information
typedef struct {
    int fd;
    void *buffer;
    struct v4l2_buffer buf;
} camera_device_t;

// Global variable to track if the program should exit
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully.\n");
    }
}

// Function to initialize the camera device
int init_camera(camera_device_t *camera) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;

    // Open the device
    camera->fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (camera->fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", DEVICE_NAME, strerror(errno));
        return -1;
    }

    // Check device capabilities
    if (ioctl(camera->fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(camera->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(camera->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(camera->fd);
        return -1;
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = IMAGE_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(camera->fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(camera->fd);
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(camera->fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(camera->fd);
        return -1;
    }

    // Query buffer
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(camera->fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        close(camera->fd);
        return -1;
    }

    // Map the buffer
    camera->buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, camera->fd, buf.m.offset);
    if (camera->buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        close(camera->fd);
        return -1;
    }

    camera->buf = buf;

    return 0;
}

// Function to capture an image
int capture_image(camera_device_t *camera) {
    struct v4l2_buffer buf;
    struct timespec ts;
    char filename[64];
    FILE *fp;

    // Prepare buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    // Queue the buffer
    if (ioctl(camera->fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        return -1;
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(camera->fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        return -1;
    }

    // Dequeue the buffer
    if (ioctl(camera->fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    // Stop streaming
    if (ioctl(camera->fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        return -1;
    }

    // Get timestamp
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return -1;
    }

    // Create filename
    snprintf(filename, sizeof(filename), "image_%04ld.jpg", ts.tv_sec);

    // Write image to file
    fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    fwrite(camera->buffer, 1, buf.bytesused, fp);
    fclose(fp);

    printf("Captured image %s\n", filename);

    return 0;
}

// Function to cleanup the camera device
void cleanup_camera(camera_device_t *camera) {
    // Unmap buffer
    if (camera->buffer != MAP_FAILED && camera->buffer != NULL) {
        if (munmap(camera->buffer, camera->buf.length) < 0) {
            fprintf(stderr, "Error unmapping buffer: %s\n", strerror(errno));
        }
    }

    // Close device
    if (camera->fd > 0) {
        close(camera->fd);
    }
}

int main() {
    camera_device_t camera;
    struct timespec sleep_time;

    // Initialize camera device
    if (init_camera(&camera) < 0) {
        fprintf(stderr, "Failed to initialize camera. Exiting.\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 0.1 seconds

    while (program_running) {
        if (capture_image(&camera) < 0) {
            fprintf(stderr, "Failed to capture image. Continuing.\n");
        }
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup camera device
    cleanup_camera(&camera);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    signal(SIGINT, signal_handler);

    int duty_cycle = 0;
    int increment = 100;

    while (!terminate) {
        gpioPWM(PWM_GPIO, duty_cycle);
        printf("Duty cycle: %d\n", duty_cycle);
        sleep(5);

        duty_cycle += increment;
        if (duty_cycle > PWM_RANGE || duty_cycle < 0) {
            increment = -increment;
            duty_cycle += increment;
        }
    }

    gpioPWM(PWM_GPIO, 0); // Stop PWM
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define PCF8574_ADDR 0x27

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for graceful exit
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a byte to the PCF8574
int pcf8574_write(int fd, unsigned char data) {
    if (write(fd, &data, 1) != 1) {
        perror("Failed to write to PCF8574");
        return -1;
    }
    return 0;
}

// Function to display a value on the PCF8574
int display_value(int fd, int value) {
    unsigned char data = (unsigned char)value;
    if (pcf8574_write(fd, data) != 0) {
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Get current time
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Display the current time on the PCF8574
    int hour = timeinfo->tm_hour;
    int minute = timeinfo->tm_min;
    int second = timeinfo->tm_sec;

    printf("Displaying time: %02d:%02d:%02d\n", hour, minute, second);

    if (display_value(i2c_fd, hour) != 0) {
        fprintf(stderr, "Failed to display hour\n");
    }
    if (display_value(i2c_fd, minute) != 0) {
        fprintf(stderr, "Failed to display minute\n");
    }
    if (display_value(i2c_fd, second) != 0) {
        fprintf(stderr, "Failed to display second\n");
    }

    // Close the I2C bus
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 16

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig)
{
    terminate = 1;
}

int main()
{
    int ret;

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Open chip failed");
        return 1;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Get line failed");
        gpiod_chip_close(chip);
        return 1;
    }

    /* Request GPIO line for output */
    ret = gpiod_line_request_output(line, "gpio-test", 0);
    if (ret < 0) {
        perror("Request line as output failed");
        gpiod_chip_close(chip);
        return 1;
    }

    /* Set initial state to 0 */
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        perror("Set line value failed");
        gpiod_chip_close(chip);
        return 1;
    }

    /* Report initial state */
    printf("GPIO %d set to %d\n", GPIO_PIN, 0);

    /* Set signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    /* Wait for a while */
    sleep(1);

    /* Set state to 1 */
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        perror("Set line value failed");
        gpiod_chip_close(chip);
        return 1;
    }

    /* Report new state */
    printf("GPIO %d set to %d\n", GPIO_PIN, 1);

    /* Wait for a while */
    sleep(1);

    /* Release GPIO line */
    ret = gpiod_line_release(line);
    if (ret < 0) {
        perror("Release line failed");
        gpiod_chip_close(chip);
        return 1;
    }

    /* Close GPIO chip */
    gpiod_chip_close(chip);

    return 0;
}

