// Function to read MCP3008 ADC
int read_mcp3008(int channel)
{
    int handle, count;
    char tx_buf[3];
    char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01;                  // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00;                  // Don't care

    // Open SPI channel
    handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", handle);
        return -1;
    }

    // Transfer data
    count = spiXfer(handle, tx_buf, rx_buf, 3);
    if (count != 3) {
        fprintf(stderr, "Error during SPI transfer: %d\n", count);
        spiClose(handle);
        return -1;
    }

    // Close SPI channel
    spiClose(handle);

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to set PWM duty cycle
void set_pwm(int duty_cycle)
{
    gpioPWM(PWM_PIN, duty_cycle);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetMode(DHT22_PIN, PI_INPUT); // DHT22 is input
    gpioSetMode(MCP3008_PIN, PI_INPUT); // MCP3008 is input

    // Set PWM frequency (e.g., 1 kHz)
    gpioSetPWMfrequency(PWM_PIN, 1000);

    // Set PWM range (0-255)
    gpioSetPWMrange(PWM_PIN, 255);

    // Set PWM duty cycle to 0 initially
    set_pwm(0);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature, humidity;
        int adc_value;

        // Read sensor data
        if (read_dht22(&temperature, &humidity) != 0) {
            fprintf(stderr, "Error reading DHT22 sensor\n");
            temperature = -999.0; // Indicate error
            humidity = -999.0;    // Indicate error
        }

        adc_value = read_mcp3008(0); // Read from channel 0
        if (adc_value < 0) {
            fprintf(stderr, "Error reading MCP3008 ADC\n");
            adc_value = -1; // Indicate error
        }

        // Calculate PWM duty cycle (example: temperature * 0.5, humidity * 0.5, ADC * 0.1)
        int duty_cycle = (int)((temperature * 0.5 + humidity * 0.5 + adc_value * 0.1) / 10.0); // Normalize to 0-255
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 255) duty_cycle = 255;

        // Set PWM duty cycle
        set_pwm(duty_cycle);

        // Print sensor data and PWM duty cycle
        printf("Temperature: %.2f, Humidity: %.2f, ADC: %d, Duty Cycle: %d\n", temperature, humidity, adc_value, duty_cycle);

        // Wait for 0.1 seconds
        usleep(100000); // 100 ms
    }

    // Cleanup and exit
    set_pwm(0); // Stop PWM
    gpioTerminate(); // Terminate pigpio
    return 0;
}

#include <stdio.h>
