// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 500000       // 0.5 seconds in microseconds

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static volatile int echo_start_time = 0;
static volatile int echo_end_time = 0;
static volatile int timeout_occurred = 0;

// Function prototypes
int initialize_gpio();
void trigger_pulse();
long measure_pulse_width();
double calculate_distance(long pulse_width);
void cleanup_gpio();
void echo_callback(struct gpiod_line *line, struct gpiod_line_event *event);
