// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Initialize GPIO lines
int initialize_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(trigger_line, "hcsr04", 0) < 0) {
        perror("Error requesting trigger line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(echo_line, "hcsr04") < 0) {
        perror("Error requesting echo line as input");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Trigger the HC-SR04 sensor
void trigger_pulse() {
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        perror("Error setting trigger line high");
        return;
    }
    usleep(10); // 10 us pulse
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        perror("Error setting trigger line low");
        return;
    }
}

// Measure the pulse width of the echo signal
long measure_pulse_width() {
    struct timespec start, end;
    long pulse_width;

    // Wait for the echo pin to go high
    while (1) {
        struct gpiod_line_event event;
        int ret = gpiod_line_event_wait(echo_line, NULL, 0); // Non-blocking wait
        if (ret < 0) {
            perror("Error waiting for echo line event");
            return -1;
        }

        if (gpiod_line_event_read(echo_line, &event) < 0) {
            perror("Error reading echo line event");
            return -1;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            clock_gettime(CLOCK_MONOTONIC, &start);
            break;
        }
        usleep(10); // Small delay to avoid busy-waiting
    }

    // Wait for the echo pin to go low
    while (1) {
        struct gpiod_line_event event;
        int ret = gpiod_line_event_wait(echo_line, NULL, 0); // Non-blocking wait
        if (ret < 0) {
            perror("Error waiting for echo line event");
            return -1;
        }

        if (gpiod_line_event_read(echo_line, &event) < 0) {
            perror("Error reading echo line event");
            return -1;
        }

        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            break;
        }
        usleep(10); // Small delay to avoid busy-waiting
    }

    pulse_width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
    return pulse_width;
}

// Calculate the distance in centimeters
double calculate_distance(long pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Cleanup GPIO resources
void cleanup_gpio() {
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Trigger the sensor
        trigger_pulse();

        // Measure the pulse width
        long pulse_width = measure_pulse_width();

        if (pulse_width < 0) {
            fprintf(stderr, "Error measuring pulse width. Retrying.\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Calculate the distance
        double distance = calculate_distance(pulse_width);

        // Print the distance
        printf("Distance: %.2f cm\n", distance);

        // Wait 500ms before the next measurement
        usleep(500000);
    }

    // Cleanup GPIO (this will never be reached in the current loop)
    cleanup_gpio();

    return 0;
}

