#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Global variables
int i2c_fd;
volatile sig_atomic_t stop_flag = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    stop_flag = 1;
}

// Function to initialize the MPU6050
int init_mpu6050() {
    // Wake up the MPU6050 (set power management register to 0)
    uint8_t data[2] = {PWR_MGMT_1, 0x00};
    if (write(i2c_fd, data, 2) != 2) {
        perror("Failed to write to PWR_MGMT_1");
        return -1;
    }
    return 0;
}

// Function to read accelerometer data
int read_accel_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z) {
    uint8_t reg = ACCEL_XOUT_H;
    uint8_t buffer[6];

    // Write the register address to read from
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    // Read 6 bytes of data (X, Y, Z axes)
    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Failed to read accelerometer data");
        return -1;
    }

    // Combine high and low bytes to form 16-bit values
    *accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() < 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!stop_flag) {
        int16_t accel_x, accel_y, accel_z;

        // Read accelerometer data
        if (read_accel_data(&accel_x, &accel_y, &accel_z) == 0) {
            // Print the data
            printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n", accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Error reading accelerometer data. Retrying...\n");
        }

        // Wait for 0.1 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 0.1 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Close I2C device
    close(i2c_fd);

    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3
#define GPIO_PIN_3 17
#define NUM_CYCLES 3
#define CYCLE_DELAY 5

struct gpiod_chip *chip;
struct gpiod_line *line1, *line2, *line3;

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", sig);
}

int main() {
    int i, ret;
    struct timespec delay;

    // Initialize signal handling
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name failed");
        return 1;
    }

    // Get GPIO lines
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    line3 = gpiod_chip_get_line(chip, GPIO_PIN_3);

    if (!line1 || !line2 || !line3) {
        perror("gpiod_chip_get_line failed");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines as output
    ret = gpiod_line_request_output(line1, "gpio_control", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (line1) failed");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line2, "gpio_control", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (line2) failed");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line3, "gpio_control", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (line3) failed");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up delay
    delay.tv_sec = CYCLE_DELAY;
    delay.tv_nsec = 0;

    // Main loop
    for (i = 0; i < NUM_CYCLES && program_running; i++) {
        // Cycle through states
        ret = gpiod_line_set_value(line1, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (line1) failed");
            break;
        }
        nanosleep(&delay, NULL);

        ret = gpiod_line_set_value(line2, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (line2) failed");
            break;
        }
        nanosleep(&delay, NULL);

        ret = gpiod_line_set_value(line3, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (line3) failed");
            break;
        }
        nanosleep(&delay, NULL);

        ret = gpiod_line_set_value(line1, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (line1) failed");
            break;
        }
        nanosleep(&delay, NULL);

        ret = gpiod_line_set_value(line2, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (line2) failed");
            break;
        }
        nanosleep(&delay, NULL);

        ret = gpiod_line_set_value(line3, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (line3) failed");
            break;
        }
        nanosleep(&delay, NULL);
    }

    // Clean up
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_line_release(line3);
    gpiod_chip_close(chip);

    printf("Program finished.\n");
    return 0;
}

