#define I2C_BUS "/dev/i2c-1"
#define SHT31_ADDR 0x44
#define MEASURE_CMD 0x2400

int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read data from SHT31
int read_sht31(int fd, float *temperature, float *humidity) {
    uint8_t write_data[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t read_data[6];
    int result;

    // Send measurement command
    result = write(fd, write_data, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Wait for measurement (typical 10ms, but let's wait 20ms for safety)
    usleep(20000);

    // Read 6 bytes of data
    result = read(fd, read_data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Convert data
    int32_t temp_raw = (read_data[0] << 8) | read_data[1];
    int32_t hum_raw = (read_data[3] << 8) | read_data[4];

    // Check CRC (simplified, always returns 0 for this example)
    // In a real application, implement CRC check here

    *temperature = -45.0 + (175.0 * (float)temp_raw / 65535.0);
    *humidity = 100.0 * (float)hum_raw / 65535.0;

    return 0;
}

