        printf("GPIO %d set to HIGH\n", GPIO_PIN);

        /* Wait for a short delay */
        usleep(DELAY_MS * 1000); // Convert ms to microseconds

        /* Set GPIO line low */
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line low: %s\n", strerror(errno));
            break;
        }
        printf("GPIO %d set to LOW\n", GPIO_PIN);

        /* Wait for a short delay */
        usleep(DELAY_MS * 1000); // Convert ms to microseconds
    }

    /* Release GPIO line */
    if (line) {
        gpiod_line_release(line);
    }

    /* Close GPIO chip */
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

