#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3
#define GPIO_PIN_3 5
#define GPIO_PIN_4 17

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line1, *line2, *line3, *line4;

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Function to set GPIO output
int set_gpio_output(struct gpiod_line *line, int value);

// Function to read GPIO input
int read_gpio_input(struct gpiod_line *line);

// Function to cleanup GPIO resources
void cleanup_gpio();

// Structure to hold GPIO line pointers
typedef struct {
    struct gpiod_line *line1;
    struct gpiod_line *line2;
    struct gpiod_line *line3;
    struct gpiod_line *line4;
} gpio_lines_t;

// Global variable for GPIO lines
gpio_lines_t gpio_lines;

int main() {
    int i;
    int ret;
    int current_state = 0;
    struct timespec sleep_time;

    // Initialize sleep time
    sleep_time.tv_sec = 5;
    sleep_time.tv_nsec = 0;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    gpio_lines.line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    gpio_lines.line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    gpio_lines.line3 = gpiod_chip_get_line(chip, GPIO_PIN_3);
    gpio_lines.line4 = gpiod_chip_get_line(chip, GPIO_PIN_4);

    if (!gpio_lines.line1 || !gpio_lines.line2 || !gpio_lines.line3 || !gpio_lines.line4) {
        perror("Error getting GPIO line");
        cleanup_gpio();
        return 1;
    }

    // Request GPIO lines as output
    ret = gpiod_line_request_output(gpio_lines.line1, "gpio_test", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        cleanup_gpio();
        return 1;
    }
    ret = gpiod_line_request_output(gpio_lines.line2, "gpio_test", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        cleanup_gpio();
        return 1;
    }
    ret = gpiod_line_request_output(gpio_lines.line3, "gpio_test", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        cleanup_gpio();
        return 1;
    }
    ret = gpiod_line_request_output(gpio_lines.line4, "gpio_test", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO outputs
        for (i = 0; i < 4; i++) {
            struct gpiod_line *line;
            if (i == 0) line = gpio_lines.line1;
            else if (i == 1) line = gpio_lines.line2;
            else if (i == 2) line = gpio_lines.line3;
            else line = gpio_lines.line4;

            if (set_gpio_output(line, current_state) < 0) {
                fprintf(stderr, "Error setting GPIO output for line %d\n", i + 1);
                cleanup_gpio();
                return 1;
            }
        }

        // Read GPIO inputs
        int input1 = read_gpio_input(gpio_lines.line1);
        int input2 = read_gpio_input(gpio_lines.line2);
        int input3 = read_gpio_input(gpio_lines.line3);
        int input4 = read_gpio_input(gpio_lines.line4);

        // Print GPIO states
        printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n",
               GPIO_PIN_1, input1, GPIO_PIN_2, input2, GPIO_PIN_3, input3, GPIO_PIN_4, input4);

        // Toggle current state
        current_state = !current_state;

        // Sleep for 5 seconds
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Function to set GPIO output
int set_gpio_output(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Function to read GPIO input
int read_gpio_input(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading GPIO value");
        return -1;
    }
    return value;
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    if (gpio_lines.line1) {
        gpiod_line_release(gpio_lines.line1);
    }
    if (gpio_lines.line2) {
        gpiod_line_release(gpio_lines.line2);
    }
    if (gpio_lines.line3) {
        gpiod_line_release(gpio_lines.line3);
    }
    if (gpio_lines.line4) {
        gpiod_line_release(gpio_lines.line4);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

