volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", sig);
}

int main() {
    int ret;
    int value1, value2;
    struct timespec delay = {0, 1000000}; // 0.01 seconds

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
