int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pin as an output
    gpioSetMode(RGB_GPIO, PI_OUTPUT);

    // Define the color values for red, green, and blue
    int red_value = 255;
    int green_value = 0;
    int blue_value = 0;

    // Define the number of cycles to run
    int num_cycles = 3;

    // Define the delay between cycles in seconds
    float delay_seconds = 0.005;

    // Run the specified number of cycles
    for (int i = 0; i < num_cycles; i++) {
        // Set the RGB color values
        set_rgb_color(red_value, green_value, blue_value);

        // Wait for the specified delay
        sleep(delay_seconds);

        // Toggle the color values (example: red to green)
        int temp = red_value;
        red_value = green_value;
        green_value = blue_value;
        blue_value = temp;
    }

    // Reset the RGB color to black (all PWM off)
    set_rgb_color(0, 0, 0);

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

