#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define W1_DEVICES_DIR "/sys/bus/w1/devices"
#define MAX_DEVICES 10
#define MAX_DEVICE_ID_LENGTH 20

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
char device_ids[MAX_DEVICES][MAX_DEVICE_ID_LENGTH];
int num_devices = 0;

// Function prototypes
int discover_devices(char device_ids[][MAX_DEVICE_ID_LENGTH], int max_devices);
float read_temperature(const char *device_id);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

// Function to discover DS18B20 devices
int discover_devices(char device_ids[][MAX_DEVICE_ID_LENGTH], int max_devices) {
    DIR *dir;
    struct dirent *ent;
    int device_count = 0;

    dir = opendir(W1_DEVICES_DIR);
    if (dir == NULL) {
        perror("opendir");
        return -1;
    }

    while ((ent = readdir(dir)) != NULL && device_count < max_devices) {
        if (strncmp(ent->d_name, "28-", 3) == 0) {
            strncpy(device_ids[device_count], ent->d_name, MAX_DEVICE_ID_LENGTH - 1);
            device_ids[device_count][MAX_DEVICE_ID_LENGTH - 1] = '\0'; // Ensure null termination
            device_count++;
        }
    }

    closedir(dir);
    return device_count;
}

// Function to read temperature from a DS18B20 device
float read_temperature(const char *device_id) {
    char filepath[256];
    int fd;
    char buffer[256];
    ssize_t bytes_read;
    char *token;
    float temperature = -127.0; // Default error value

    snprintf(filepath, sizeof(filepath), "%s/%s/w1_slave", W1_DEVICES_DIR, device_id);

    fd = open(filepath, O_RDONLY);
    if (fd == -1) {
        perror("open");
        return temperature;
    }

    bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    if (bytes_read == -1) {
        perror("read");
        close(fd);
        return temperature;
    }
    buffer[bytes_read] = '\0';

    close(fd);

    // Parse the temperature from the file content
    token = strstr(buffer, "t=");
    if (token != NULL) {
        long temp_milli_celsius = strtol(token + 2, NULL, 10);
        temperature = (float)temp_milli_celsius / 1000.0;
    }

    return temperature;
}

int main() {
    time_t rawtime;
    struct tm * timeinfo;
    char timestamp[80];

    // Install signal handler for Ctrl+C
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Discover DS18B20 devices
    num_devices = discover_devices(device_ids, MAX_DEVICES);
    if (num_devices == 0) {
        fprintf(stderr, "Error: No DS18B20 devices found. Please ensure 1-Wire is enabled and the device is properly connected.\n");
        return 1;
    }

    printf("Found %d DS18B20 devices:\n", num_devices);
    for (int i = 0; i < num_devices; i++) {
        printf("  Device ID: %s\n", device_ids[i]);
    }

    // Main loop
    for (int i = 0; i < 3 && program_running; i++) {
        for (int j = 0; j < num_devices; j++) {
            float temperature = read_temperature(device_ids[j]);

            if (temperature != -127.0) {
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
                printf("[%s] Temperature from %s: %.2f °C\n", timestamp, device_ids[j], temperature);
            } else {
                fprintf(stderr, "Error reading temperature from device %s\n", device_ids[j]);
            }
        }
        sleep(5);
    }

    printf("Program finished.\n");
    return 0;
}

#include <stdio.h>
