#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN_17 17
#define GPIO_PIN_18 18

struct gpiod_chip *chip;
struct gpiod_line *line_17, *line_18;

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", sig);
}

int main() {
    int ret;
    int value_17, value_18;

    /* Register signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    /* Get GPIO lines */
    line_17 = gpiod_chip_get_line(chip, GPIO_PIN_17);
    if (!line_17) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN_17, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    line_18 = gpiod_chip_get_line(chip, GPIO_PIN_18);
    if (!line_18) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN_18, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    /* Request GPIO lines as output */
    ret = gpiod_line_request_output(line_17, "gpio_test", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_PIN_17, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line_18, "gpio_test", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_PIN_18, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    /* Main loop */
    while (program_running) {
        /* Toggle GPIO 17 */
        value_17 = !gpiod_line_get_value(line_17);
        ret = gpiod_line_set_value(line_17, value_17);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO_PIN_17, strerror(errno));
            program_running = 0; // Exit loop on error
            break;
        }

        /* Toggle GPIO 18 */
        value_18 = !gpiod_line_get_value(line_18);
        ret = gpiod_line_set_value(line_18, value_18);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO_PIN_18, strerror(errno));
            program_running = 0; // Exit loop on error
            break;
        }

        /* Print GPIO states */
        printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_PIN_17, value_17, GPIO_PIN_18, value_18);

        /* Wait for 1 second */
        sleep(1);
    }

    /* Release GPIO lines */
    gpiod_line_release(line_17);
    gpiod_line_release(line_18);

    /* Close GPIO chip */
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>

// Define GPIO pins
#define TRIGGER_PIN 18
#define ECHO_PIN 23

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 500000       // 0.5 seconds in microseconds

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *trigger_line;
struct gpiod_line *echo_line;

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Function to trigger the ultrasonic sensor
void trigger_sensor();

// Function to measure the echo pulse width
long measure_pulse_width();

// Function to calculate the distance in centimeters
float calculate_distance(long pulse_width);

// Function to print the distance to standard output
void print_distance(float distance);

// Function to clean up GPIO resources
void cleanup();

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines for trigger and echo pins
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);

    if (!trigger_line || !echo_line) {
        perror("Error getting GPIO line");
        cleanup();
        return 1;
    }

    // Request GPIO lines for output and input
    if (gpiod_line_request_output(trigger_line, "ultrasonic", 0) < 0) {
        perror("Error requesting trigger line as output");
        cleanup();
        return 1;
    }
    if (gpiod_line_request_input(echo_line, "ultrasonic") < 0) {
        perror("Error requesting echo line as input");
        cleanup();
        return 1;
    }

    // Main loop
    while (1) {
        // Trigger the sensor
        trigger_sensor();

        // Measure the echo pulse width
        long pulse_width = measure_pulse_width();

        // Calculate the distance
        float distance = calculate_distance(pulse_width);

        // Print the distance
        print_distance(distance);

        // Wait for 0.1 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 0.1 seconds
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

// Signal handler function
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup();
    exit(0);
}

// Function to trigger the ultrasonic sensor
void trigger_sensor()
{
    // Set trigger pin HIGH for 10 microseconds
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        perror("Error setting trigger pin HIGH");
        cleanup();
        exit(1);
    }
    usleep(10);

    // Set trigger pin LOW
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        perror("Error setting trigger pin LOW");
        cleanup();
        exit(1);
    }
}

// Function to measure the echo pulse width
long measure_pulse_width()
{
    struct timeval start, end;
    long pulse_width;

    // Wait for the echo pin to go HIGH
    int retries = 0;
    while (gpiod_line_get_value(echo_line) == 0 && retries < TIMEOUT_US) {
        usleep(1); // Small delay to avoid busy-waiting
        retries++;
    }

    if (retries >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo HIGH\n");
        return -1; // Indicate timeout error
    }

    gettimeofday(&start, NULL);

    // Wait for the echo pin to go LOW
    retries = 0;
    while (gpiod_line_get_value(echo_line) == 1 && retries < TIMEOUT_US) {
        usleep(1); // Small delay to avoid busy-waiting
        retries++;
    }

    if (retries >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo LOW\n");
        return -1; // Indicate timeout error
    }

    gettimeofday(&end, NULL);

    // Calculate pulse width in microseconds
    pulse_width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_usec - start.tv_usec);

    return pulse_width;
}

// Function to calculate the distance in centimeters
float calculate_distance(long pulse_width)
{
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (float)pulse_width * SPEED_OF_SOUND / 20000.0; // Divide by 2 for one-way distance
}

// Function to print the distance to standard output
void print_distance(float distance)
{
    if (distance >= 0) {
        printf("Distance: %.2f cm\n", distance);
    } else {
        printf("Error: Invalid distance measurement\n");
    }
}

// Function to clean up GPIO resources
void cleanup()
{
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define NUM_CYCLES 10

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int i, ret;
    struct gpiod_line_request_config config;

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name failed");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line failed");
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure GPIO line as output
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        perror("gpiod_line_request failed");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop: toggle GPIO output and print state
    for (i = 0; i < NUM_CYCLES; i++) {
        // Set GPIO high
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value failed");
            break;
        }
        printf("GPIO %d set to HIGH\n", GPIO_PIN);
        sleep(1);

        // Set GPIO low
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value failed");
            break;
        }
        printf("GPIO %d set to LOW\n", GPIO_PIN);
        sleep(1);

        if (terminate) {
            printf("Termination signal received. Exiting.\n");
            break;
        }
    }

    // Release GPIO line and chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Program finished.\n");
    return 0;
}

