#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 2
#define VALID_LOW 0
#define VALID_HIGH 1

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int ret;
    struct timespec delay = {5, 0}; // 5 seconds
    int value;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio-test", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Set GPIO line to 1
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Error setting GPIO line value");
            break;
        }
        printf("GPIO %d set to 1\n", GPIO_PIN);

        // Wait for 5 seconds
        nanosleep(&delay, NULL);

        // Read GPIO line
        value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("Error reading GPIO line value");
            break;
        }

        // Validate reading
        if (value != VALID_HIGH) {
            fprintf(stderr, "Invalid reading: %d\n", value);
        } else {
            printf("GPIO %d read as %d\n", GPIO_PIN, value);
        }

        // Set GPIO line to 0
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Error setting GPIO line value");
            break;
        }
        printf("GPIO %d set to 0\n", GPIO_PIN);

        // Wait for 5 seconds
        nanosleep(&delay, NULL);

        // Read GPIO line
        value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("Error reading GPIO line value");
            break;
        }

        // Validate reading
        if (value != VALID_LOW) {
            fprintf(stderr, "Invalid reading: %d\n", value);
        } else {
            printf("GPIO %d read as %d\n", GPIO_PIN, value);
        }
    }

    // Release GPIO line
    ret = gpiod_line_release(line);
    if (ret < 0) {
        perror("Error releasing GPIO line");
    }

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("Program terminated.\n");
    return 0;
}

