#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for PWM output
#define PWM_PIN_1 4
#define PWM_PIN_2 17
#define PWM_PIN_3 18

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define PWM range (0-1000 for 0-100% duty cycle)
#define PWM_RANGE 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCtrl+C detected. Exiting gracefully...\n");
}

// Function to set PWM duty cycle for a given GPIO pin
int set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > PWM_RANGE) {
        fprintf(stderr, "Error: Invalid duty cycle value (%d). Must be between 0 and %d.\n", duty_cycle, PWM_RANGE);
        return -1; // Indicate an error
    }

    gpioPWM(gpio_pin, duty_cycle);
    return 0; // Indicate success
}

// Function to read PWM duty cycle from a given GPIO pin
int read_pwm_duty_cycle(int gpio_pin) {
    int duty_cycle = gpioGetPWMdutycycle(gpio_pin);
    if (duty_cycle < 0) {
        fprintf(stderr, "Error: Failed to read duty cycle from GPIO %d.\n", gpio_pin);
        return -1; // Indicate an error
    }
    return duty_cycle;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1; // Exit with an error code
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set PWM duty cycles
        if (set_pwm_duty_cycle(PWM_PIN_1, 500) != 0) {
            program_running = 0; // Exit on error
            continue;
        }
        if (set_pwm_duty_cycle(PWM_PIN_2, 750) != 0) {
            program_running = 0; // Exit on error
            continue;
        }
        if (set_pwm_duty_cycle(PWM_PIN_3, 250) != 0) {
            program_running = 0; // Exit on error
            continue;
        }

        // Read and print PWM duty cycles
        int duty_cycle_1 = read_pwm_duty_cycle(PWM_PIN_1);
        int duty_cycle_2 = read_pwm_duty_cycle(PWM_PIN_2);
        int duty_cycle_3 = read_pwm_duty_cycle(PWM_PIN_3);

        if (duty_cycle_1 == -1 || duty_cycle_2 == -1 || duty_cycle_3 == -1) {
            program_running = 0; // Exit on error
            continue;
        }

        printf("PWM_PIN_1: %d, PWM_PIN_2: %d, PWM_PIN_3: %d\n", duty_cycle_1, duty_cycle_2, duty_cycle_3);

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100000 microseconds = 0.1 seconds
    }

    // Stop PWM output
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0; // Exit successfully
}

