#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 4
#define NUM_CYCLES 3

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int valid;
} DHT22Data;

// Global variables for signal handling
static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    keep_running = 0;
}

// Function to read DHT22 data
DHT22Data read_dht22() {
    DHT22Data data = {0.0, 0.0, 0};
    int i, j;
    int data_bits[40] = {0};

    // Request access to the GPIO line
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "dht22_reader";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting line for output\n");
        return data; // Return invalid data
    }

    // Send start signal
    gpiod_line_set_value(line, 0);
    usleep(1000); // 1ms
    gpiod_line_set_value(line, 1);
    usleep(30); // 30us

    // Release the line
    gpiod_line_release(line);

    // Request access to the GPIO line for input
    memset(&config, 0, sizeof(config));
    config.consumer = "dht22_reader";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting line for input\n");
        return data; // Return invalid data
    }

    // Wait for the DHT22 to pull the line low
    int timeout = 0;
    while (gpiod_line_get_value(line) == 1) {
        usleep(1);
        timeout++;
        if (timeout > 100) {
            fprintf(stderr, "DHT22 timeout waiting for start signal\n");
            gpiod_line_release(line);
            return data; // Return invalid data
        }
    }

    // Wait for the DHT22 to pull the line high
    timeout = 0;
    while (gpiod_line_get_value(line) == 0) {
        usleep(1);
        timeout++;
        if (timeout > 100) {
            fprintf(stderr, "DHT22 timeout waiting for end of start signal\n");
            gpiod_line_release(line);
            return data; // Return invalid data
        }
    }

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        // Wait for the line to go low
        timeout = 0;
        while (gpiod_line_get_value(line) == 1) {
            usleep(1);
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "DHT22 timeout waiting for data low\n");
                gpiod_line_release(line);
                return data; // Return invalid data
            }
        }

        // Measure the length of the high pulse
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);
        timeout = 0;
        while (gpiod_line_get_value(line) == 0) {
            usleep(1);
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "DHT22 timeout waiting for data high\n");
                gpiod_line_release(line);
                return data; // Return invalid data
            }
        }
        clock_gettime(CLOCK_MONOTONIC, &end);

        // Calculate the pulse length
        long pulse_length = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

        // Determine if the pulse is a 0 or a 1
        data_bits[i] = (pulse_length > 40) ? 1 : 0;
    }

    // Release the line
    gpiod_line_release(line);

    // Convert the data bits to bytes
    unsigned char humidity_msb = (data_bits[0] << 7) | (data_bits[1] << 6) | (data_bits[2] << 5) | (data_bits[3] << 4) | (data_bits[4] << 3) | (data_bits[5] << 2) | (data_bits[6] << 1) | data_bits[7];
    unsigned char humidity_lsb = (data_bits[8] << 7) | (data_bits[9] << 6) | (data_bits[10] << 5) | (data_bits[11] << 4) | (data_bits[12] << 3) | (data_bits[13] << 2) | (data_bits[14] << 1) | data_bits[15];
    unsigned char temperature_msb = (data_bits[16] << 7) | (data_bits[17] << 6) | (data_bits[18] << 5) | (data_bits[19] << 4) | (data_bits[20] << 3) | (data_bits[21] << 2) | (data_bits[22] << 1) | data_bits[23];
    unsigned char temperature_lsb = (data_bits[24] << 7) | (data_bits[25] << 6) | (data_bits[26] << 5) | (data_bits[27] << 4) | (data_bits[28] << 3) | (data_bits[29] << 2) | (data_bits[30] << 1) | data_bits[31];
    unsigned char checksum = (data_bits[32] << 7) | (data_bits[33] << 6) | (data_bits[34] << 5) | (data_bits[35] << 4) | (data_bits[36] << 3) | (data_bits[37] << 2) | (data_bits[38] << 1) | data_bits[39];

    // Calculate the checksum
    unsigned char calculated_checksum = humidity_msb + humidity_lsb + temperature_msb + temperature_lsb;

    // Validate the checksum
    if (checksum != calculated_checksum) {
        fprintf(stderr, "DHT22 checksum error\n");
        return data; // Return invalid data
    }

    // Convert the data to temperature and humidity
    data.humidity = (float)((humidity_msb << 8) | humidity_lsb) / 10.0;
    data.temperature = (float)(((temperature_msb & 0x7F) << 8) | temperature_lsb) / 10.0;
    if (temperature_msb & 0x80) {
        data.temperature *= -1;
    }

    // Validate the data
    if (data.temperature < -40.0 || data.temperature > 80.0 || data.humidity < 0.0 || data.humidity > 100.0) {
        fprintf(stderr, "DHT22 data out of range\n");
        return data; // Return invalid data
    }

    data.valid = 1;
    return data;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    int cycle = 0;
    while (keep_running && cycle < NUM_CYCLES) {
        DHT22Data data = read_dht22();

        if (data.valid) {
            printf("Temperature: %.1f\u00b0C, Humidity: %.1f%%\n", data.temperature, data.humidity);
        } else {
            fprintf(stderr, "Invalid DHT22 data\n");
        }

        cycle++;
        sleep(5);
    }

    // Release the GPIO line and chip
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

