#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_GPIO 17
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    signal(SIGINT, signal_handler);

    int duty_cycle = 0;
    int direction = 1; // 1 for increasing, -1 for decreasing

    printf("PWM on GPIO %d, frequency %d Hz, range %d\n", PWM_GPIO, PWM_FREQUENCY, PWM_RANGE);

    while (!terminate) {
        gpioPWM(PWM_GPIO, duty_cycle);
        printf("Duty cycle: %d\n", duty_cycle);

        duty_cycle += direction * 10;

        if (duty_cycle >= PWM_RANGE) {
            duty_cycle = PWM_RANGE - 1;
            direction = -1;
        } else if (duty_cycle <= 0) {
            duty_cycle = 0;
            direction = 1;
        }

        gpioDelay(100000); // 100ms
    }

    gpioPWM(PWM_GPIO, 0); // Stop PWM
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

