#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <gpiod.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define DHT22_PIN 4
#define LED_PIN 17

// Define constants
#define MAX_TIMINGS 85
#define NUM_CYCLES 3
#define CYCLE_DELAY 60 // seconds

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *dht22_line;
static struct gpiod_line *led_line;
static volatile sig_atomic_t terminate = 0;

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int valid;
} DHT22Data;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to read DHT22 data
DHT22Data read_dht22_data() {
    uint8_t data[5] = {0, 0, 0, 0, 0};
    int dht22_data[40] = {0};
    int laststate = HIGH;
    int j = 0;
    DHT22Data dht_data = {0.0, 0.0, 0};

    // Set pin as output
    if (gpiod_line_set_value(dht22_line, 0) < 0) {
        perror("Failed to set DHT22 pin as output");
        return dht_data; // Return invalid data
    }

    // Send start signal
    if (gpiod_line_set_value(dht22_line, 0) < 0) {
        perror("Failed to set DHT22 pin low");
        return dht_data; // Return invalid data
    }
    usleep(1000); // 1ms
    if (gpiod_line_set_value(dht22_line, 1) < 0) {
        perror("Failed to set DHT22 pin high");
        return dht_data; // Return invalid data
    }
    usleep(40); // 40us

    // Read data
    for (int i = 0; i < MAX_TIMINGS; i++) {
        int count = 0;
        while (gpiod_line_get_value(dht22_line) == laststate) {
            count++;
            usleep(1); // Wait 1us
            if (count == 255) {
                break;
            }
        }
        laststate = gpiod_line_get_value(dht22_line);

        if (count == 255) break;

        // Ignore first 3 transitions
        if ((i >= 4) && (i % 2 == 0)) {
            dht22_data[j / 8] <<= 1;
            if (count > 16) // Adjust threshold for reliability
                dht22_data[j / 8] |= 1;
            j++;
        }
    }

    // Check we read 40 bits (8bit humidity + 8bit humidity + 8bit temperature + 8bit checksum)
    if (j < 40) {
        fprintf(stderr, "DHT22: Not enough data received (%d bits)\n", j);
        return dht_data; // Return invalid data
    }

    // Check checksum
    if (dht22_data[4] != ((dht22_data[0] + dht22_data[1] + dht22_data[2] + dht22_data[3]) & 0xFF)) {
        fprintf(stderr, "DHT22: Checksum failure\n");
        return dht_data; // Return invalid data
    }

    // Convert data to temperature and humidity
    float humidity = (float)((dht22_data[0] << 8) + dht22_data[1]) / 10.0;
    float temperature = (float)(((dht22_data[2] & 0x7F) << 8) + dht22_data[3]) / 10.0;
    if (dht22_data[2] & 0x80) {
        temperature = -temperature;
    }

    // Validate data
    if (temperature < -40.0 || temperature > 80.0 || humidity < 0.0 || humidity > 100.0) {
        fprintf(stderr, "DHT22: Invalid data (temperature=%.1f, humidity=%.1f)\n", temperature, humidity);
        return dht_data; // Return invalid data
    }

    dht_data.temperature = temperature;
    dht_data.humidity = humidity;
    dht_data.valid = 1;

    return dht_data;
}

// Function to control the LED
void control_led(int state) {
    if (gpiod_line_set_value(led_line, state) < 0) {
        perror("Failed to set LED state");
    }
}

int main() {
    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Get DHT22 line
    dht22_line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!dht22_line) {
        perror("Failed to get DHT22 line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request lines for input and output
    if (gpiod_line_request_input(dht22_line, "dht22") < 0) {
        perror("Failed to request DHT22 line for input");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Failed to request LED line for output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    int cycle_count = 0;
    while (!terminate && cycle_count < NUM_CYCLES) {
        printf("Cycle %d of %d\n", cycle_count + 1, NUM_CYCLES);

        // Read DHT22 data
        DHT22Data dht_data = read_dht22_data();

        // Check if data is valid
        if (dht_data.valid) {
            printf("Temperature: %.1f°C, Humidity: %.1f%%\n", dht_data.temperature, dht_data.humidity);

            // Control LED based on temperature
            if (dht_data.temperature > 30.0) {
                control_led(1); // Turn LED on
            } else {
                control_led(0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Invalid DHT22 data, skipping LED control.\n");
        }

        // Wait for the next cycle
        sleep(CYCLE_DELAY);
        cycle_count++;
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_led(0); // Turn off LED
    gpiod_line_release(dht22_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    printf("Exiting.\n");
    return 0;
}

