#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for PWM output
#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 27

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stdout, "Ctrl+C detected. Exiting gracefully.\n");
}

int main() {
    int result;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Set PWM frequency to 1 kHz
    gpioSetPWMfrequency(PWM_PIN_1, 1000);
    gpioSetPWMfrequency(PWM_PIN_2, 1000);
    gpioSetPWMfrequency(PWM_PIN_3, 1000);

    // Set PWM range (0-255)
    gpioSetPWMrange(PWM_PIN_1, 255);
    gpioSetPWMrange(PWM_PIN_2, 255);
    gpioSetPWMrange(PWM_PIN_3, 255);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set PWM duty cycle for each pin (example values)
        gpioPWM(PWM_PIN_1, 128); // 50% duty cycle
        gpioPWM(PWM_PIN_2, 191); // 75% duty cycle
        gpioPWM(PWM_PIN_3, 255); // 100% duty cycle

        // Report PWM state to standard output
        result = fprintf(stdout, "PWM_PIN_1: %d, PWM_PIN_2: %d, PWM_PIN_3: %d\n", gpioPWM(PWM_PIN_1, 128), gpioPWM(PWM_PIN_2, 191), gpioPWM(PWM_PIN_3, 255));
        if (result < 0) {
            fprintf(stderr, "Error writing to stdout\n");
            break; // Exit loop on write error
        }

        // Wait for 1 second
        sleep(1);
    }

    // Stop PWM signals
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);

    // Terminate pigpio library
    gpioTerminate();

    fprintf(stdout, "Program terminated.\n");
    return 0;
}

