// SPI device and settings
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// Global variable for SPI file descriptor
int spi_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (spi_fd != -1) {
        close(spi_fd);
    }
    exit(0);
}

// Function to read data from MAX31855 via SPI
int read_max31855(int fd, unsigned char *data) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = 0, // No transmit buffer
        .rx_buf = (unsigned long)data,
        .len = 4, // Read 4 bytes
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("SPI transaction failed");
        return -1;
    }

    return 0;
}

// Function to process the raw data and extract temperature
float process_data(unsigned char *data) {
    // Check for fault bits
    if (data[3] & 0x01) {
        fprintf(stderr, "Fault detected: Open circuit\n");
        return -273.15; // Return absolute zero as error indicator
    }
    if (data[3] & 0x02) {
        fprintf(stderr, "Fault detected: Short to GND\n");
        return -273.15;
    }
    if (data[3] & 0x04) {
        fprintf(stderr, "Fault detected: Short to VCC\n");
        return -273.15;
    }

    // Extract temperature data (bits 31:18)
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;

    // Convert to Celsius
    float temperature = raw_temp * 0.25;

    return temperature;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Configure SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }

    // Configure SPI bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return 1;
    }

    // Configure SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return 1;
    }

    unsigned char data[4];

    // Read data from MAX31855
    if (read_max31855(spi_fd, data) == 0) {
        // Process the data
        float temperature = process_data(data);

        // Print the temperature
        if (temperature > -273.0) {
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Error reading temperature\n");
        }
    } else {
        fprintf(stderr, "Failed to read data from MAX31855\n");
    }

    // Close SPI device
    close(spi_fd);

    return 0;
}

