#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 500000       // 0.5 seconds in microseconds

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static volatile int echo_start_time = 0;
static volatile int echo_end_time = 0;
static volatile int timeout_flag = 0;
static volatile int program_running = 1;

// Function prototypes
int initialize_gpio();
void trigger_sensor();
void echo_callback(int line, struct gpiod_line_event *event);
double calculate_distance(int start_time, int end_time);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initializes the GPIO chip and lines
int initialize_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(trigger_line, "hcsr04", 0) < 0) {
        perror("Error requesting trigger line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(echo_line, "hcsr04") < 0) {
        perror("Error requesting echo line as input");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Triggers the HC-SR04 sensor
void trigger_sensor() {
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        perror("Error setting trigger line high");
        return;
    }
    usleep(10); // 10 us trigger pulse
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        perror("Error setting trigger line low");
        return;
    }
}

// Callback function for echo pin events
void echo_callback(int line, struct gpiod_line_event *event) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    int current_time = ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

    if (event->event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
        echo_start_time = current_time;
        timeout_flag = 0; // Reset timeout flag on rising edge
    } else if (event->event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
        echo_end_time = current_time;
    }
}

// Calculates the distance in centimeters
double calculate_distance(int start_time, int end_time) {
    if (start_time == 0 || end_time == 0) {
        return -1.0; // Indicate error
    }
    int pulse_duration = end_time - start_time;
    return (double)pulse_duration * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Cleans up the GPIO resources
void cleanup_gpio() {
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Set up event watcher for echo pin
    struct gpiod_line_event_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "hcsr04";
    config.request_type = GPIOD_LINE_REQUEST_EVENT_BOTH_EDGES;

    if (gpiod_line_event_request(echo_line, &config, echo_callback) < 0) {
        perror("Error requesting echo line event");
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Trigger the sensor
        trigger_sensor();

        // Wait for a short period
        usleep(50000); // 50 ms

        // Check for timeout
        if (timeout_flag) {
            fprintf(stderr, "Timeout waiting for echo. Retrying.\n");
            cleanup_gpio();
            if (initialize_gpio() < 0) {
                fprintf(stderr, "GPIO re-initialization failed. Exiting.\n");
                return 1;
            }
            if (gpiod_line_event_request(echo_line, &config, echo_callback) < 0) {
                perror("Error requesting echo line event");
                cleanup_gpio();
                return 1;
            }
            continue; // Retry the measurement
        }

        // Calculate distance
        double distance = calculate_distance(echo_start_time, echo_end_time);

        // Print the distance
        if (distance >= 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error calculating distance.\n");
        }

        // Reset echo times
        echo_start_time = 0;
        echo_end_time = 0;
    }

    // Cleanup GPIO resources
    cleanup_gpio();

    return 0;
}

