    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize BMP280 sensor
    if (bmp280_init(i2c_fd) != 0) {
        fprintf(stderr, "BMP280 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Read and print data 3 times
    for (int i = 0; i < 3; i++) {
        int32_t temperature, pressure;
        int retry_count = 0;

        while (retry_count < retries) {
            if (bmp280_read_data(i2c_fd, &temperature, &pressure) == 0) {
                // Success, break out of retry loop
                break;
            } else {
                fprintf(stderr, "I2C read failed, retrying (%d/%d)...\n", retry_count + 1, retries);
                retry_count++;
                usleep(delay_ms * 1000); // Delay in microseconds
                delay_ms *= 2; // Exponential backoff
            }
        }

        if (retry_count == retries) {
            fprintf(stderr, "Failed to read BMP280 data after %d retries\n", retries);
            close(i2c_fd);
            return 1;
        }

        printf("Temperature: %d, Pressure: %d\n", temperature, pressure);
        usleep(1000000); // 1 second delay
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

