#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 50

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int ret;
    int current_state = -1; // Initialize to an invalid state
    int previous_state = -1;
    struct timespec delay = {0, DEBOUNCE_DELAY_MS * 1000000L}; // 50ms

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio-control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read GPIO state
        current_state = gpiod_line_get_value(line);
        if (current_state < 0) {
            fprintf(stderr, "Error reading GPIO line value: %s\n", strerror(errno));
            break; // Exit loop on error
        }

        // Debounce and check for state change
        if (current_state != previous_state) {
            nanosleep(&delay, NULL);
            int debounced_state = gpiod_line_get_value(line);
            if (debounced_state < 0) {
                fprintf(stderr, "Error reading GPIO line value during debounce: %s\n", strerror(errno));
                break; // Exit loop on error
            }
            if (debounced_state == current_state) {
                // State has been confirmed
                previous_state = current_state;
                printf("GPIO %d state: %d\n", GPIO_PIN, current_state);
            }
        }

        // Small delay to avoid busy-waiting
        usleep(10000); // 10ms
    }

    // Release GPIO line and chip
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>
#include <time.h>

// BME280 I2C address
#define BME280_I2C_ADDR 0x76

// BME280 register addresses
#define BME280_REG_TEMP_MSB 0xFA
#define BME280_REG_PRESSURE_MSB 0xF7
#define BME280_REG_HUMIDITY_MSB 0xFD
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_ID 0xD0

// Calibration data registers
#define BME280_REG_CALIB_00 0x88
#define BME280_REG_CALIB_26 0xE1

// Oversampling settings
#define BME280_OVERSAMPLING_TEMP 1 // x1
#define BME280_OVERSAMPLING_PRESS 1 // x1
#define BME280_OVERSAMPLING_HUM 1   // x1

// Global variables for calibration data
int32_t t_fine;
uint16_t dig_T1;
int16_t dig_T2;
int16_t dig_T3;
uint16_t dig_P1;
int16_t dig_P2;
int16_t dig_P3;
int16_t dig_P4;
int16_t dig_P5;
int16_t dig_P6;
int16_t dig_P7;
int16_t dig_P8;
int16_t dig_P9;
uint8_t dig_H1;
int16_t dig_H2;
uint8_t dig_H3;
int16_t dig_H4;
int16_t dig_H5;
uint8_t dig_H6;

// Function to read a single byte from the BME280
int read_register(int fd, uint8_t reg_addr)
{
    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    uint8_t data;
    if (read(fd, &data, 1) != 1) {
        perror("Failed to read register data");
        return -1;
    }
    return data;
}

// Function to write a single byte to the BME280
int write_register(int fd, uint8_t reg_addr, uint8_t data)
{
    uint8_t buf[2];
    buf[0] = reg_addr;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register");
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BME280
int read_calibration_data(int fd)
{
    uint8_t data[26];
    uint8_t data_h[7];

    // Read temperature and pressure calibration data
    if (write(fd, (uint8_t[]){BME280_REG_CALIB_00}, 1) != 1) {
        perror("Failed to write calibration address");
        return -1;
    }
    if (read(fd, data, 26) != 26) {
        perror("Failed to read calibration data");
        return -1;
    }

    // Read humidity calibration data
    if (write(fd, (uint8_t[]){BME280_REG_CALIB_26}, 1) != 1) {
        perror("Failed to write humidity calibration address");
        return -1;
    }
    if (read(fd, data_h, 7) != 7) {
        perror("Failed to read humidity calibration data");
        return -1;
    }

    dig_T1 = (data[1] << 8) | data[0];
    dig_T2 = (data[3] << 8) | (int8_t)data[2];
    dig_T3 = (data[5] << 8) | (int8_t)data[4];
    dig_P1 = (data[7] << 8) | data[6];
    dig_P2 = (data[9] << 8) | (int8_t)data[8];
    dig_P3 = (data[11] << 8) | (int8_t)data[10];
    dig_P4 = (data[13] << 8) | (int8_t)data[12];
    dig_P5 = (data[15] << 8) | (int8_t)data[14];
    dig_P6 = (data[17] << 8) | (int8_t)data[16];
    dig_P7 = (data[19] << 8) | (int8_t)data[18];
    dig_P8 = (data[21] << 8) | (int8_t)data[20];
    dig_P9 = (data[23] << 8) | (int8_t)data[22];
    dig_H1 = data[25];
    dig_H2 = (data_h[1] << 8) | (int8_t)data_h[0];
    dig_H3 = data_h[2];
    dig_H4 = (data_h[3] << 4) | (data_h[4] & 0x0F);
    dig_H5 = (data_h[5] << 4) | (data_h[4] >> 4);
    dig_H6 = data_h[6];

    return 0;
}

// Function to read raw data from the BME280
int read_raw_data(int fd, int32_t *temperature, int32_t *pressure, int32_t *humidity)
{
    uint8_t data[8];

    // Set the oversampling and mode
    if (write_register(fd, BME280_REG_CTRL_HUM, BME280_OVERSAMPLING_HUM) != 0) {
        fprintf(stderr, "Error writing humidity control register\n");
        return -1;
    }
    if (write_register(fd, BME280_REG_CTRL_MEAS, (BME280_OVERSAMPLING_TEMP << 5) | (BME280_OVERSAMPLING_PRESS << 2) | 0x03) != 0) { // Forced mode
        fprintf(stderr, "Error writing control register\n");
        return -1;
    }

    // Wait for the measurement to complete (adjust delay as needed)
    usleep(100000); // 100ms

    // Read the data
    if (write(fd, (uint8_t[]){BME280_REG_PRESSURE_MSB}, 1) != 1) {
        perror("Failed to write pressure register address");
        return -1;
    }
    if (read(fd, data, 8) != 8) {
        perror("Failed to read data");
        return -1;
    }

    *pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    *temperature = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    *humidity = (data[6] << 8) | data[7];

    return 0;
}

// Function to compensate temperature
float compensate_temperature(int32_t raw_temperature)
{
    float var1 = (raw_temperature / 16384.0 - dig_T1 / 1024.0) * dig_T2;
    float var2 = ((raw_temperature / 131072.0 - dig_T1 / 8192.0) * (raw_temperature / 131072.0 - dig_T1 / 8192.0)) * dig_T3;
    t_fine = (int32_t)(var1 + var2);
    float T = (var1 + var2) / 5120.0;
    return T;
}

// Function to compensate pressure
float compensate_pressure(int32_t raw_pressure)
{
    float var1 = (t_fine / 2.0) - 64000.0;
    float var2 = var1 * var1 * dig_P6 / 32768.0;
    var2 = var2 + var1 * dig_P5 * 2.0;
    var2 = (var2 / 4.0) + (dig_P4 * 65536.0);
    var1 = (dig_P3 * var1 * var1 / 524288.0 + dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * dig_P1;
    float P = 1048576.0 - raw_pressure;
    P = (P - var2 / 4096.0) * 6250.0 / var1;
    var1 = dig_P9 * P * P / 2147483648.0;
    var2 = P * dig_P8 / 32768.0;
    P = P + (var1 + var2 + dig_P7) / 16.0;
    return P;
}

// Function to compensate humidity
float compensate_humidity(int32_t raw_humidity)
{
    float var_H = (t_fine - 76800.0);
    var_H = (raw_humidity - (dig_H4 * 64.0 + dig_H5 / 16384.0 * var_H)) * (dig_H2 / 65536.0 * (1.0 + dig_H6 / 67108864.0 * var_H * (1.0 + dig_H3 / 67108864.0 * var_H)));
    var_H = var_H * (1.0 - dig_H1 * var_H / 524288.0);
    if (var_H > 100.0)
        var_H = 100.0;
    else if (var_H < 0.0)
        var_H = 0.0;
    return var_H;
}

int main()
{
    int fd;
    int32_t raw_temperature, raw_pressure, raw_humidity;
    float temperature, pressure, humidity;
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    // Open the I2C device
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return 1;
    }

    // Check the device ID
    int chip_id = read_register(fd, BME280_REG_ID);
    if (chip_id != 0x60) {
        fprintf(stderr, "Error: Incorrect chip ID: 0x%x\n", chip_id);
        close(fd);
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(fd) != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        close(fd);
        return 1;
    }

    // Main loop
    for (int i = 0; i < 3; i++) {
        // Read raw data
        if (read_raw_data(fd, &raw_temperature, &raw_pressure, &raw_humidity) != 0) {
            fprintf(stderr, "Error reading raw data\n");
            close(fd);
            return 1;
        }

        // Compensate data
        temperature = compensate_temperature(raw_temperature);
        pressure = compensate_pressure(raw_pressure);
        humidity = compensate_humidity(raw_humidity);

        // Get current timestamp
        time(&now);
        timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Print the data
        printf("%s - Temperature: %.2f \u00b0C, Pressure: %.2f hPa, Humidity: %.2f %%\n", timestamp, temperature, pressure / 100.0, humidity);

        // Wait 5 seconds
        sleep(5);
    }

    // Close the I2C device
    close(fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define DELAY_SECONDS 1

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int ret;
    int i;

    /* Register signal handler for SIGINT (Ctrl+C) */
    signal(SIGINT, signal_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    /* Request GPIO line for output */
    ret = gpiod_line_request_output(line, "gpio-test", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    /* Main loop */
    while (!terminate) {
        /* Toggle GPIO output */
        for (i = 0; i < 2; i++) {
            ret = gpiod_line_set_value(line, i);
            if (ret < 0) {
                fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
                goto cleanup;
            }

            /* Report GPIO state */
            printf("GPIO %d set to %d\n", GPIO_PIN, i);

            /* Delay */
            sleep(DELAY_SECONDS);
        }
    }

cleanup:
    /* Release GPIO line */
    if (line) {
        gpiod_line_release(line);
    }

    /* Close GPIO chip */
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define VEML7700_ADDR 0x10

int i2c_fd;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting...\n");
    if (i2c_fd > 0) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read data from VEML7700
int read_veml7700(int fd) {
    unsigned char buf[2];
    int result;

    // Read two bytes from the sensor
    result = read(fd, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    int data = (buf[0] << 8) | buf[1];
    return data;
}

int main() {
    int data;

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        data = read_veml7700(i2c_fd);
        if (data >= 0) {
            printf("Raw Data: %d\n", data);
        } else {
            fprintf(stderr, "Failed to read data. Retrying...\n");
        }

        sleep(0.5);
    }

    return 0;
}

