volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
}

int setup_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 10; // 0.1 seconds timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int read_uart(int fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return 0; // No data available
        } else {
            perror("Error reading from UART");
            return -1;
        }
    } else {
        buffer[bytes_read] = '\0';
        return (int)bytes_read;
    }
}

int main() {
    signal(SIGINT, signal_handler);

    uart_fd = setup_uart(UART_DEVICE);
    if (uart_fd == -1) {
        fprintf(stderr, "Failed to setup UART. Exiting.\n");
        return 1;
    }

    char buffer[BUFFER_SIZE];
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (program_running) {
        int bytes_read = read_uart(uart_fd, buffer, BUFFER_SIZE);
        if (bytes_read > 0) {
            printf("Received: %s", buffer);
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART. Continuing.\n");
        }

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        double elapsed_time = (current_time.tv_sec - start_time.tv_sec) +
                              (current_time.tv_nsec - start_time.tv_nsec) / 1e9;

        if (elapsed_time >= TIMEOUT_SEC) {
            printf("Timeout waiting for data. Exiting.\n");
            break;
        }

        usleep(100000); // 100ms delay
    }

    close(uart_fd);
    printf("UART closed. Exiting.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 500000       // 0.5 seconds in microseconds

// Global variable for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to trigger the HC-SR04 sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance in centimeters
float measureDistance() {
    long long start_tick, end_tick, diff_tick;

    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Wait for the echo pin to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo start.\n");
        return -1.0; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo end.\n");
        return -1.0; // Indicate timeout error
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 for us to s conversion, then by 2 for one-way distance

    return distance;
}

// Function to validate the distance reading
int validateDistance(float distance) {
    if (distance < 0.0 || distance > 400.0) {
        fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
        return 0; // Invalid
    }
    return 1; // Valid
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Trigger the sensor
        triggerSensor();

        // Measure the distance
        float distance = measureDistance();

        // Validate the distance
        if (distance >= 0.0) {
            if (validateDistance(distance)) {
                // Get current timestamp
                time_t rawtime;
                struct tm *timeinfo;
                time(&rawtime);
                timeinfo = localtime(&rawtime);

                // Print the distance with timestamp
                char timestamp[80];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
                printf("%s Distance: %.2f cm\n", timestamp, distance);
            }
        } else {
            fprintf(stderr, "Failed to measure distance.\n");
        }

        // Wait for 0.5 seconds
        gpioDelay(500000); // 500 ms
    }

    // Release GPIO resources
    gpioTerminate();

    return 0;
}

