#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>

#define ADXL345_I2C_ADDR 0x53
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32

int main() {
    int file;
    int16_t x, y, z;
    char buf[6];

    // Open I2C device
    if ((file = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify slave address
    if (ioctl(file, I2C_SLAVE, ADXL345_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return 1;
    }

    // Wake up the ADXL345 (set POWER_CTL to 0x08)
    buf[0] = ADXL345_REG_POWER_CTL;
    buf[1] = 0x08;
    if (write(file, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        close(file);
        return 1;
    }

    // Read 6 bytes of data starting from DATAX0
    buf[0] = ADXL345_REG_DATAX0;
    if (write(file, buf, 1) != 1) {
        perror("Failed to write to I2C device");
        close(file);
        return 1;
    }

    if (read(file, buf, 6) != 6) {
        perror("Failed to read from I2C device");
        close(file);
        return 1;
    }

    // Combine bytes to form 16-bit values
    x = (int16_t)((buf[1] << 8) | buf[0]);
    y = (int16_t)((buf[3] << 8) | buf[2]);
    z = (int16_t)((buf[5] << 8) | buf[4]);

    // Print the values
    printf("X: %d, Y: %d, Z: %d\n", x, y, z);

    close(file);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins to control
const int gpio_pins[] = {4, 17, 18, 22, 23, 24, 25, 27};
const int num_pins = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

// Global variables for GPIO chip and line
struct gpiod_chip *chip;
struct gpiod_line *lines[8]; // Assuming 8 pins maximum

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Close and release GPIO lines
    for (int i = 0; i < num_pins; i++)
    {
        if (lines[i])
        {
            gpiod_line_release(lines[i]);
        }
    }

    // Close GPIO chip
    if (chip)
    {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip)
    {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Request GPIO lines for output
    for (int i = 0; i < num_pins; i++)
    {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!lines[i])
        {
            perror("Error getting GPIO line");
            // Release previously opened lines before exiting
            for (int j = 0; j < i; j++)
            {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }

        if (gpiod_line_request_output(lines[i], "gpio_control", 0) < 0)
        {
            perror("Error requesting GPIO line for output");
            // Release previously opened lines before exiting
            for (int j = 0; j <= i; j++)
            {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Main loop: toggle GPIO pins
    while (1)
    {
        for (int i = 0; i < num_pins; i++)
        {
            // Toggle the GPIO pin
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                perror("Error getting GPIO line value");
                // Release previously opened lines before exiting
                for (int j = 0; j <= i; j++)
                {
                    gpiod_line_release(lines[j]);
                }
                gpiod_chip_close(chip);
                return 1;
            }
            int new_value = !value;
            if (gpiod_line_set_value(lines[i], new_value) < 0)
            {
                perror("Error setting GPIO line value");
                // Release previously opened lines before exiting
                for (int j = 0; j <= i; j++)
                {
                    gpiod_line_release(lines[j]);
                }
                gpiod_chip_close(chip);
                return 1;
            }

            // Report the state
            printf("GPIO %d: %d\n", gpio_pins[i], new_value);
        }

        // Wait for 0.05 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 50000000; // 50 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // The program should never reach here due to the infinite loop.
    return 0;
}

