                previous_state = current_state;
            }
        }
    }

    // Release GPIO line and chip
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("GPIO control program stopped.\n");
