#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 30000       // 30ms timeout

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static volatile int echo_start_time = 0;
static volatile int echo_end_time = 0;
static volatile int timeout_flag = 0;
static volatile int running = 1;

// Function prototypes
int initialize_gpio();
void trigger_pulse();
double measure_distance();
void echo_callback(int line, struct gpiod_line_event *event);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize GPIO lines
int initialize_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(trigger_line, "hcsr04", 0) < 0) {
        perror("Error requesting trigger line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(echo_line, "hcsr04") < 0) {
        perror("Error requesting echo line as input");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Trigger the HC-SR04 sensor
void trigger_pulse() {
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        perror("Error setting trigger line high");
        return;
    }
    usleep(10); // 10us pulse
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        perror("Error setting trigger line low");
        return;
    }
}

// Measure the distance using the HC-SR04 sensor
double measure_distance() {
    struct timespec start, end;
    double distance;

    // Reset echo times
    echo_start_time = 0;
    echo_end_time = 0;
    timeout_flag = 0;

    // Trigger the sensor
    trigger_pulse();

    // Wait for echo to start
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 > TIMEOUT_US) {
            timeout_flag = 1;
            return -1.0; // Timeout
        }
    }

    // Record start time
    clock_gettime(CLOCK_MONOTONIC, &start);

    // Wait for echo to end
    clock_gettime(CLOCK_MONOTONIC, &end);
    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 > TIMEOUT_US) {
            timeout_flag = 1;
            return -1.0; // Timeout
        }
    }

    // Record end time
    clock_gettime(CLOCK_MONOTONIC, &end);

    // Calculate pulse duration in microseconds
    double pulse_duration = (end.tv_sec - start.tv_sec) * 1000000.0 + (end.tv_nsec - start.tv_nsec) / 1000.0;

    // Calculate distance in centimeters
    distance = (pulse_duration * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

// Callback function for echo pin events
void echo_callback(int line, struct gpiod_line_event *event) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    int timestamp = (ts.tv_sec * 1000000) + (ts.tv_nsec / 1000);

    if (event->event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
        echo_start_time = timestamp;
    } else if (event->event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
        echo_end_time = timestamp;
    }
}

// Cleanup GPIO resources
void cleanup_gpio() {
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Set up event watcher for echo pin
    struct gpiod_line_event_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "hcsr04";
    config.request_type = GPIOD_LINE_REQUEST_EVENT_BOTH_EDGES;

    if (gpiod_line_event_request(echo_line, &config, echo_callback) < 0) {
        perror("Error requesting echo line event");
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (running) {
        double distance = measure_distance();

        if (timeout_flag) {
            fprintf(stderr, "Timeout occurred. Retrying.\n");
        } else if (distance >= 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error measuring distance.\n");
        }

        usleep(100000); // 100ms delay
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

