        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            fprintf(stderr, "Set line %d value failed\n", pins[i]);
            gpiod_chip_close(chip);
            return 1;
        }

        printf("GPIO %d set to HIGH\n", pins[i]);
        gpiod_line_release(line);
    }

    gpiod_chip_close(chip);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 500000       // 0.5 seconds in microseconds

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *trigger_line;
struct gpiod_line *echo_line;

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Function to trigger the ultrasonic sensor
int trigger_sensor(struct gpiod_line *trigger_line);

// Function to measure the echo pulse width
long measure_pulse_width(struct gpiod_line *echo_line);

// Function to calculate the distance in centimeters
float calculate_distance(long pulse_width);

// Function to print the distance to standard output
void print_distance(float distance);

// Function to release GPIO resources
void cleanup(void);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines for trigger and echo pins
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        cleanup();
        return 1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        cleanup();
        return 1;
    }

    // Request GPIO lines for output and input
    if (gpiod_line_request_output(trigger_line, "ultrasonic", 0) < 0) {
        perror("Error requesting trigger line for output");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_input(echo_line, "ultrasonic") < 0) {
        perror("Error requesting echo line for input");
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Trigger the sensor
        if (trigger_sensor(trigger_line) != 0) {
            fprintf(stderr, "Error triggering sensor\n");
        } else {
            // Measure the echo pulse width
            long pulse_width = measure_pulse_width(echo_line);

            // Calculate the distance
            float distance = calculate_distance(pulse_width);

            // Print the distance
            print_distance(distance);
        }

        // Wait for 0.1 seconds
        usleep(100000); // 100 milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Signal handler function
void signal_handler(int sig)
{
    program_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

// Function to trigger the ultrasonic sensor
int trigger_sensor(struct gpiod_line *trigger_line)
{
    // Set trigger pin HIGH for 10 microseconds
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        perror("Error setting trigger pin HIGH");
        return -1;
    }
    usleep(10);

    // Set trigger pin LOW
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        perror("Error setting trigger pin LOW");
        return -1;
    }

    return 0;
}

// Function to measure the echo pulse width
long measure_pulse_width(struct gpiod_line *echo_line)
{
    struct timespec start, end;
    int value;

    // Wait for the echo pin to go HIGH
    int timeout_count = 0;
    while ((value = gpiod_line_get_value(echo_line)) < 0) {
        if (timeout_count > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo HIGH\n");
            return -1;
        }
        usleep(1); // Small delay to avoid busy-waiting
        timeout_count++;
    }
    if (value == 0) return -1; //Echo pin went low before timeout

    clock_gettime(CLOCK_MONOTONIC, &start);

    // Wait for the echo pin to go LOW
    timeout_count = 0;
    while ((value = gpiod_line_get_value(echo_line)) < 0) {
        if (timeout_count > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo LOW\n");
            return -1;
        }
        usleep(1); // Small delay to avoid busy-waiting
        timeout_count++;
    }
    if (value == 1) return -1; //Echo pin went high before timeout

    clock_gettime(CLOCK_MONOTONIC, &end);

    // Calculate the pulse width in microseconds
    long pulse_width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

    return pulse_width;
}

// Function to calculate the distance in centimeters
float calculate_distance(long pulse_width)
{
    if (pulse_width < 0) {
        return -1.0; // Indicate an error
    }
    return (float)pulse_width * SPEED_OF_SOUND / 20000.0; // Divide by 20000 to convert us to s and then convert to cm
}

// Function to print the distance to standard output
void print_distance(float distance)
{
    if (distance >= 0) {
        printf("Distance: %.2f cm\n", distance);
    } else {
        fprintf(stderr, "Error: Invalid distance measurement\n");
    }
}

// Function to release GPIO resources
void cleanup(void)
{
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

