#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// TCS34725 I2C address
#define TCS34725_ADDRESS 0x29

// TCS34725 Registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_CDATA 0x94
#define TCS34725_RDATA 0x96
#define TCS34725_GDATA 0x98
#define TCS34725_BDATA 0x9A

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the TCS34725 sensor
int tcs34725_init(int fd) {
    // Enable the sensor (PON and AEN)
    if (write(fd, "\x03", 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from the TCS34725 sensor
int tcs34725_read_16(int fd, unsigned char reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    unsigned char buffer[2];
    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    return (buffer[1] << 8) | buffer[0];
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Initialize the TCS34725 sensor
    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop to read and print sensor data
    while (1) {
        // Read the clear, red, green, and blue values
        int clear = tcs34725_read_16(i2c_fd, TCS34725_CDATA);
        int red = tcs34725_read_16(i2c_fd, TCS34725_RDATA);
        int green = tcs34725_read_16(i2c_fd, TCS34725_GDATA);
        int blue = tcs34725_read_16(i2c_fd, TCS34725_BDATA);

        // Check for errors during read operations
        if (clear < 0 || red < 0 || green < 0 || blue < 0) {
            fprintf(stderr, "Error reading sensor data.\n");
        } else {
            // Print the values to the console
            printf("Clear: %d, Red: %d, Green: %d, Blue: %d\n", clear, red, green, blue);
        }

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    // The program should never reach this point due to the infinite loop
    close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
