#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_PIN_1 18
#define GPIO_PIN_2 23

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line1, *line2;

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Function to set GPIO line value
int set_gpio_value(struct gpiod_line *line, int value);

// Function to get GPIO line value
int get_gpio_value(struct gpiod_line *line);

// Function to cleanup GPIO resources
void cleanup_gpio();

// Structure to hold GPIO configuration
typedef struct {
    int pin1;
    int pin2;
    char *chip_name;
} gpio_config_t;

// Global GPIO configuration
gpio_config_t gpio_config = {
    .pin1 = GPIO_PIN_1,
    .pin2 = GPIO_PIN_2,
    .chip_name = CHIP_NAME
};

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(gpio_config.chip_name);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'\n", gpio_config.chip_name);
        return 1;
    }

    // Get GPIO lines
    line1 = gpiod_chip_get_line(chip, gpio_config.pin1);
    if (!line1) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", gpio_config.pin1);
        cleanup_gpio();
        return 1;
    }

    line2 = gpiod_chip_get_line(chip, gpio_config.pin2);
    if (!line2) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", gpio_config.pin2);
        cleanup_gpio();
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line1, "gpio_control", 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d for output\n", gpio_config.pin1);
        cleanup_gpio();
        return 1;
    }

    if (gpiod_line_request_output(line2, "gpio_control", 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d for output\n", gpio_config.pin2);
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (1) {
        // Toggle GPIO 18
        if (set_gpio_value(line1, 1) < 0) {
            fprintf(stderr, "Error setting GPIO %d\n", gpio_config.pin1);
            cleanup_gpio();
            return 1;
        }
        printf("GPIO %d: %d\n", gpio_config.pin1, get_gpio_value(line1));

        // Toggle GPIO 23
        if (set_gpio_value(line2, 0) < 0) {
            fprintf(stderr, "Error setting GPIO %d\n", gpio_config.pin2);
            cleanup_gpio();
            return 1;
        }
        printf("GPIO %d: %d\n", gpio_config.pin2, get_gpio_value(line2));

        // Wait for 0.01 seconds
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 10000000; // 10 milliseconds
        nanosleep(&ts, NULL);
    }

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Function to set GPIO line value
int set_gpio_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %d\n", ret);
        return -1;
    }
    return 0;
}

// Function to get GPIO line value
int get_gpio_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error getting GPIO value: %d\n", value);
        return -1;
    }
    return value;
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

