#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN_17 17
#define GPIO_PIN_18 18

struct gpiod_chip *chip;
struct gpiod_line *line_17, *line_18;

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", sig);
}

int main() {
    int ret;
    int value_17, value_18;
    struct timespec delay = {0, 1000000}; // 0.01 seconds

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line_17 = gpiod_chip_get_line(chip, GPIO_PIN_17);
    if (!line_17) {
        perror("Error getting GPIO line 17");
        gpiod_chip_close(chip);
        return 1;
    }

    line_18 = gpiod_chip_get_line(chip, GPIO_PIN_18);
    if (!line_18) {
        perror("Error getting GPIO line 18");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line_17, "gpio_test", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 17 for output");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line_18, "gpio_test", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 18 for output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Toggle GPIO 17
        value_17 = !gpiod_line_get_value(line_17);
        ret = gpiod_line_set_value(line_17, value_17);
        if (ret < 0) {
            perror("Error setting GPIO line 17 value");
            break;
        }

        // Toggle GPIO 18
        value_18 = !gpiod_line_get_value(line_18);
        ret = gpiod_line_set_value(line_18, value_18);
        if (ret < 0) {
            perror("Error setting GPIO line 18 value");
            break;
        }

        // Print GPIO states
        printf("GPIO 17: %d, GPIO 18: %d\n", value_17, value_18);

        // Delay
        nanosleep(&delay, NULL);
    }

    // Cleanup
    gpiod_line_release(line_17);
    gpiod_line_release(line_18);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_PIN_1 22
#define GPIO_PIN_2 24

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line1, *line2;

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Function to set GPIO output
int set_gpio_output(struct gpiod_line *line, int value);

// Function to read GPIO input
int read_gpio_input(struct gpiod_line *line);

// Global variable to control the main loop
volatile sig_atomic_t running = 1;

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);

    if (!line1 || !line2) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines as output
    if (gpiod_line_request_output(line1, "gpio_test", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line2, "gpio_test", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (running) {
        // Toggle GPIO 22
        if (set_gpio_output(line1, 1) < 0) {
            fprintf(stderr, "Error setting GPIO output\n");
            break;
        }
        printf("GPIO %d set to 1\n", GPIO_PIN_1);
        usleep(50000); // 50ms

        // Toggle GPIO 24
        if (set_gpio_output(line2, 0) < 0) {
            fprintf(stderr, "Error setting GPIO output\n");
            break;
        }
        printf("GPIO %d set to 0\n", GPIO_PIN_2);
        usleep(50000); // 50ms
    }

    // Cleanup
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    printf("Program terminated cleanly.\n");
    return 0;
}

// Signal handler function
void signal_handler(int sig)
{
    running = 0;
    printf("Ctrl+C pressed, exiting...\n");
}

// Function to set GPIO output
int set_gpio_output(struct gpiod_line *line, int value)
{
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Function to read GPIO input (not used in this example, but kept for completeness)
int read_gpio_input(struct gpiod_line *line)
{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading GPIO value");
        return -1;
    }
    return value;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18
#define DELAY_SECONDS 5

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int ret;
    int i;

    /* Register signal handler for SIGINT (Ctrl+C) */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    /* Request GPIO line for output */
    ret = gpiod_line_request_output(line, "gpio-test", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    /* Main loop */
    while (!terminate) {
        /* Toggle GPIO output */
        for (i = 0; i < 2; i++) {
            ret = gpiod_line_set_value(line, i);
            if (ret < 0) {
                fprintf(stderr, "Error setting GPIO value: %s\n", strerror(errno));
                goto cleanup;
            }
            printf("GPIO %d set to %d\n", GPIO_PIN, i);
            sleep(DELAY_SECONDS);
        }
    }

cleanup:
    /* Release GPIO line */
    if (line) {
        gpiod_line_release(line);
    }

    /* Close GPIO chip */
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

