#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PWM_PIN 2
#define DHT22_PIN 3
#define LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read DHT22 sensor data (simulated)
int read_dht22(float *temperature, float *humidity) {
    // Simulate DHT22 sensor reading
    // In a real application, this would involve reading from the DHT22 sensor
    // via I2C or SPI.
    // For this example, we'll just return some dummy values.
    static int call_count = 0;
    if (call_count % 2 == 0) {
        *temperature = 25.5;
        *humidity = 60.2;
    } else {
        *temperature = 26.6;
        *humidity = 61.3;
    }
    call_count++;
    return 0; // Indicate success (replace with actual error checking)
}

// Function to set LED state
void set_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Function to set PWM duty cycle
void set_pwm(int duty_cycle) {
    gpioPWM(PWM_PIN, duty_cycle);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetMode(DHT22_PIN, PI_INPUT); // DHT22 is input, but we simulate reading
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set PWM frequency (e.g., 1000 Hz)
    gpioSetPWMfrequency(PWM_PIN, 1000);

    // Set PWM range (0-255)
    gpioSetPWMrange(PWM_PIN, 255);

    // Set PWM duty cycle to 128 initially
    set_pwm(128);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        float temperature, humidity;

        // Read DHT22 sensor data
        if (read_dht22(&temperature, &humidity) == 0) {
            // Validate sensor readings
            if (temperature >= -40.0 && temperature <= 80.0 && humidity >= 0.0 && humidity <= 100.0) {
                // Map temperature to PWM duty cycle (0-255)
                int duty_cycle = (int)((temperature - -40.0) / (80.0 - -40.0) * 255.0);
                if (duty_cycle < 0) duty_cycle = 0;
                if (duty_cycle > 255) duty_cycle = 255;

                // Set PWM duty cycle
                set_pwm(duty_cycle);

                // Set LED state based on humidity (example)
                if (humidity > 70.0) {
                    set_led(1); // Turn LED on
                } else {
                    set_led(0); // Turn LED off
                }

                // Print sensor data to standard output
                printf("Temperature: %.1f\u00b0C, Humidity: %.1f%%, Duty Cycle: %d\n", temperature, humidity, duty_cycle);
            } else {
                fprintf(stderr, "Invalid sensor readings: Temperature=%.1f, Humidity=%.1f\n", temperature, humidity);
            }
        } else {
            fprintf(stderr, "Error reading DHT22 sensor\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Clean up and exit
    set_pwm(0); // Turn off PWM
    gpioTerminate(); // Terminate pigpio
    return 0;
}

