#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_PIN_1 18
#define GPIO_PIN_2 22

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line1, *line2;

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Function to set GPIO output
int set_gpio_output(struct gpiod_line *line, int value);

// Function to read GPIO input
int read_gpio_input(struct gpiod_line *line);

// Function to cleanup GPIO resources
void cleanup_gpio(void);

int main(void)
{
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line for GPIO 18
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("Error getting GPIO line 18");
        cleanup_gpio();
        return 1;
    }

    // Get GPIO line for GPIO 22
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("Error getting GPIO line 22");
        cleanup_gpio();
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(line1, "gpio_control", 0) < 0) {
        perror("Error requesting GPIO line for output");
        cleanup_gpio();
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(line2, "gpio_control", 0) < 0) {
        perror("Error requesting GPIO line for output");
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (1) {
        // Toggle GPIO 18
        if (set_gpio_output(line1, 1) < 0) {
            fprintf(stderr, "Error setting GPIO 18\n");
            cleanup_gpio();
            return 1;
        }
        printf("GPIO 18: HIGH\n");
        usleep(50000); // 50ms

        // Toggle GPIO 22
        if (set_gpio_output(line2, 0) < 0) {
            fprintf(stderr, "Error setting GPIO 22\n");
            cleanup_gpio();
            return 1;
        }
        printf("GPIO 22: LOW\n");
        usleep(50000); // 50ms
    }

    return 0;
}

// Signal handler function
void signal_handler(int sig)
{
    printf("Caught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Function to set GPIO output
int set_gpio_output(struct gpiod_line *line, int value)
{
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Error setting GPIO output");
        return -1;
    }
    return 0;
}

