{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading GPIO input");
        return -1;
    }
    return value;
}

// Function to cleanup GPIO resources
void cleanup_gpio(void)
{
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE B115200
#define TIMEOUT_SEC 5

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int setup_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 8N1, no parity, no hardware flow control
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 1; // 0.1 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int read_uart(int fd, char *buffer, size_t max_len) {
    ssize_t bytes_read = read(fd, buffer, max_len - 1);
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return 0; // Timeout or no data
        } else {
            perror("Error reading from UART");
            return -1;
        }
    } else {
        buffer[bytes_read] = '\0';
        return (int)bytes_read;
    }
}

int main() {
    signal(SIGINT, signal_handler);

    uart_fd = setup_uart(UART_DEVICE);
    if (uart_fd == -1) {
        fprintf(stderr, "Failed to setup UART. Exiting.\n");
        return 1;
    }

    char buffer[256];
    time_t last_read_time = time(NULL);

    while (program_running) {
        int bytes_read = read_uart(uart_fd, buffer, sizeof(buffer));
        if (bytes_read > 0) {
            printf("Received: %s", buffer);
            last_read_time = time(NULL);
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART. Continuing.\n");
        }

        if (time(NULL) - last_read_time > TIMEOUT_SEC) {
            fprintf(stderr, "Timeout waiting for data. Exiting.\n");
            program_running = 0;
        }

        usleep(100000); // 0.1 seconds
    }

    close(uart_fd);
    printf("UART closed.\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_CHIP "gpiochip0"
#define GPIO_OUTPUT_PIN 3
#define GPIO_INPUT_PIN 5

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *output_line;
struct gpiod_line *input_line;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (output_line) {
        gpiod_line_release(output_line);
    }
    if (input_line) {
        gpiod_line_release(input_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    int i, ret;
    int output_value = 0;
    int input_value;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line for output pin
    output_line = gpiod_chip_get_line(chip, GPIO_OUTPUT_PIN);
    if (!output_line) {
        perror("Error getting output GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Get GPIO line for input pin
    input_line = gpiod_chip_get_line(chip, GPIO_INPUT_PIN);
    if (!input_line) {
        perror("Error getting input GPIO line");
        gpiod_chip_close(chip);
        gpiod_line_release(output_line);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(output_line, "gpio_control", output_value);
    if (ret < 0) {
        perror("Error requesting output GPIO line");
        gpiod_chip_close(chip);
        gpiod_line_release(output_line);
        gpiod_line_release(input_line);
        return 1;
    }

    // Request GPIO line for input
    ret = gpiod_line_request_input(input_line, "gpio_control");
    if (ret < 0) {
        perror("Error requesting input GPIO line");
        gpiod_chip_close(chip);
        gpiod_line_release(output_line);
        gpiod_line_release(input_line);
        return 1;
    }

    // Main loop
    while (1) {
        // Toggle output value
        output_value = !output_value;

        // Set output value
        ret = gpiod_line_set_value(output_line, output_value);
        if (ret < 0) {
            perror("Error setting output GPIO value");
            break;
        }

        // Read input value
        input_value = gpiod_line_get_value(input_line);
        if (input_value < 0) {
            perror("Error getting input GPIO value");
            break;
        }

        // Print output and input values
        printf("Output: %d, Input: %d\n", output_value, input_value);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup (in case of error)
    gpiod_line_release(output_line);
    gpiod_line_release(input_line);
    gpiod_chip_close(chip);

    return 1;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 18
#define ECHO_PIN 23

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 500000       // 0.5 seconds in microseconds

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static volatile int echo_start_time = 0;
static volatile int echo_end_time = 0;
static volatile int timeout_flag = 0;
static volatile int program_running = 1;

// Function prototypes
int initialize_gpio();
void trigger_sensor();
void echo_callback(int line, struct gpiod_line_event *event);
double calculate_distance(int start_time, int end_time);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initializes the GPIO chip and lines
int initialize_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(trigger_line, "hcsr04", 0) < 0) {
        perror("Error requesting trigger line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(echo_line, "hcsr04") < 0) {
        perror("Error requesting echo line as input");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Triggers the HC-SR04 sensor
void trigger_sensor() {
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        perror("Error setting trigger line high");
        return;
    }
    usleep(10); // 10 us trigger pulse
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        perror("Error setting trigger line low");
        return;
    }
}

// Callback function for echo pin events
void echo_callback(int line, struct gpiod_line_event *event) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    int current_time = ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

    if (event->event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
        echo_start_time = current_time;
        timeout_flag = 0; // Reset timeout flag on rising edge
    } else if (event->event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
        echo_end_time = current_time;
    }
}

// Calculates the distance in centimeters
double calculate_distance(int start_time, int end_time) {
    if (start_time == 0 || end_time == 0) {
        return -1.0; // Indicate error
    }
    int pulse_duration = end_time - start_time;
    return (double)pulse_duration * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Cleans up the GPIO resources
void cleanup_gpio() {
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Set up event watcher for echo pin
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "hcsr04";
    config.request_type = GPIOD_LINE_REQUEST_EVENT_BOTH_EDGES;

    if (gpiod_line_event_watch(echo_line, &config, echo_callback) < 0) {
        perror("Error watching for echo events");
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Trigger the sensor
        trigger_sensor();

        // Wait for a short period
        usleep(50000); // 50 ms

        // Check for timeout
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        int current_time = ts.tv_sec * 1000000 + ts.tv_nsec / 1000;
        if (current_time - echo_start_time > TIMEOUT_US || current_time - echo_end_time > TIMEOUT_US) {
            timeout_flag = 1;
        }

        // Calculate distance
        double distance = calculate_distance(echo_start_time, echo_end_time);

        // Print the distance
        if (distance >= 0) {
            printf("Distance: %.2f cm\n", distance);
        } else if (timeout_flag) {
            fprintf(stderr, "Timeout occurred. No echo received.\n");
        } else {
            fprintf(stderr, "Error calculating distance.\n");
        }

        // Reset echo times
        echo_start_time = 0;
        echo_end_time = 0;
        timeout_flag = 0;
    }

    // Cleanup GPIO resources
    cleanup_gpio();

    return 0;
}

