    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    signal(SIGINT, signal_handler);

    int duty_cycle = 0;
    int increment = 100;

    while (!terminate) {
        gpioPWM(PWM_GPIO, duty_cycle);
        printf("Duty cycle: %d\n", duty_cycle);
        fflush(stdout);
        sleep(0.2);

        duty_cycle += increment;
        if (duty_cycle > PWM_RANGE || duty_cycle < 0) {
            increment = -increment;
            duty_cycle += increment;
        }
    }

    gpioPWM(PWM_GPIO, 0);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

